-- Activity Centre: seed the authored Activity library.
--
-- Places the authored Activities into public.activities so they are
-- assignable from the teacher library and reach students through the Activity
-- Centre. Content is generated from the item banks in the vault
-- (~/ai-os/brainstorms/2026-08-03-*-bank.md) and mirrored, typed and tested, at
-- src/features/activity-centre/content/.
--
--   vocab-rehab            Vocab Rehab               51 items
--   spot-the-relationship  Spot the Relationship     48 items
--   conditional-rephrase   Conditional Rephrase      62 items
--   find-the-conclusion    Find the Conclusion       62 items
--   rebuttal-rephrase      Rebuttal Rephrase         42 items
--   dumb-it-down           Dumb it Down              24 items
--   spot-the-callback      Spot the Callback         20 items
--   read-recall-colour     Read, Recall, Colour       1 items
--   read-recall-colour-pt1-s3 Read, Recall, Colour · PT1 Section 3  22 items
--   read-recall-colour-pt21-s3 Read, Recall, Colour · PT21 Section 3  22 items
--   read-recall-colour-pt102-s3 Read, Recall, Colour · PT102 Section 3  22 items
--   read-recall-colour-pt105-s2 Read, Recall, Colour · PT105 Section 2  23 items
--   read-recall-colour-pt134-s3 Read, Recall, Colour · PT134 Section 3  26 items
--                                                   425 items total
--
-- Negation Station is deliberately untouched: it already exists and its items
-- are authored verbatim. Its instructions carry no `coach` block, so the
-- activity-coach function keeps applying its original negation rubric.
--
-- Ownership: activities.created_by must be a real admin and RLS scopes reads to
-- created_by = auth.uid(), so each row is attached to the first admin account.
-- The profiles.class_id = user_id invariant gives class_id. If no admin exists
-- the insert is a no-op rather than an error, and re-running after one is
-- created will seed correctly.
--
-- Idempotent: re-running refreshes title/subtitle/instructions/items in place
-- on the slug conflict. Existing activity_assignments are snapshots and are
-- intentionally NOT rewritten; a student mid-Activity keeps what they started.

DO $$
DECLARE
  admin_id uuid;
  admin_class uuid;
BEGIN
  SELECT ur.user_id INTO admin_id
  FROM public.user_roles ur
  WHERE ur.role = 'admin'
  ORDER BY ur.user_id
  LIMIT 1;

  IF admin_id IS NULL THEN
    RAISE NOTICE 'seed_activity_library: no admin account found, skipping seed';
    RETURN;
  END IF;

  -- `public.profiles` has no `id` column: its PRIMARY KEY is `class_id`, which
  -- holds the user id, and it is `text` where `activities.class_id` is `uuid`.
  -- An earlier version of this script looked up `profiles.id` and the whole DO
  -- block aborted with 42703 the first time anyone applied it by hand
  -- (2026-08-29). The lookup was never doing anything anyway: the
  -- class_id = user_id invariant is the answer, and it matches every row
  -- already in `activities`, where created_by and class_id are the same uuid.
  admin_class := admin_id;

  INSERT INTO public.activities
    (slug, title, subtitle, instructions, item_format, items, mode, time_goal_minutes, source_section, created_by, class_id)
  SELECT s.slug, s.title, s.subtitle, s.instructions, s.item_format, s.items,
         s.mode, s.time_goal_minutes, s.source_section, admin_id, admin_class
  FROM (VALUES
  (
    'vocab-rehab',
    'Vocab Rehab',
    'Work out the word from the sentence around it',
    '{"coach": {"drill": "a context-definition drill: the student works out what a marked word probably means from the structure of the paragraph around it, and says why", "rubric": ["The reasoning is the point. An answer that gives a correct definition with no reason is incomplete, and an answer that gives the wrong definition for a well-identified clue is closer to the skill than a lucky guess.", "Hedged, multi-candidate answers are the target form, not a weakness. Probably means A, B or C, because of this clue, is a full-credit answer.", "Accept any phrasing that lands the meaning. This drill never tests dictionary wording.", "A correct positive or negative read is a full answer on its own, which is what this drill promises the student in its own rules. Credit it as correct and hand them the sharper meaning as the next rung. Never score an answer down for stopping at valence.", "Right valence with wrong precision is the signature miss to teach past, not to mark down. Balance is not the same as peace, a substitute is not the same as bad, and treated-as-such is not the same as fake: name the exact shade after crediting what they already got.", "When the student names the clue correctly, say so explicitly before correcting anything else, because the clue is the transferable part."], "partial_rule": "Mark ''partial'' when the student gives a workable meaning but cites no evidence from the paragraph, or names a clue and then reads its direction backwards. A correct valence call with a reason attached is ''correct'', never ''partial'', even when the precise meaning is still missing. Mark ''incorrect'' when the meaning is wrong and no usable clue has been identified."}, "tagline": "You do not need to know the word. You need to read the sentence.", "task": "What do you think the marked word could mean, and why do you think that?", "rules": ["Guessing is the exercise. Even deciding whether the word is positive or negative is a real answer.", "Relate it to a word you already know, then look for what the sentence does with it.", "Look for the clue: a restatement right next to the word, a contrast, a list of examples, or an antonym.", "Answer in this shape: the word probably means A or B, and I think that because of this specific thing in the paragraph.", "Getting the right feeling with the wrong precision is the usual miss. Push for the exact shade."], "worked_example": {"statement": "Investors hesitated, wary of the market''s *capricious* mood swings.", "credited_answers": ["Capricious probably means unpredictable, erratic or changeable. I think this because it describes mood swings, and because the investors are wary, which tells me it is negative."], "explanation": "Two clues, and the answer names both. Mood swings restates the word, and the investors'' wariness fixes the valence as negative. Notice the answer hedges with probably and offers more than one candidate, which is exactly right."}, "answer_label": "Your reading of the word", "answer_placeholder": "What could the marked word mean, and why…"}'::jsonb,
    'free-text',
    '[{"order": 1, "prompt": "In regions with heavy snowfall, avalanche training for mountain guides becomes an *imperative* part of their preparation. It is not merely an option but a crucial requirement to ensure safety during their expeditions.", "credited_answers": ["imperative probably means essential, necessary, crucial. I think this because of the necessity/requirement signal (\"not merely an option\") in the sentence."], "explanation": "Meaning in context: absolutely necessary; required. Reusable pattern: necessity/requirement signal (\"not merely an option\"). Quick synonyms: essential, necessary, crucial. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 2, "prompt": "Critics argue that the new film lacks *authenticity*, as its portrayal of historical events appears overly dramatized rather than true to actual occurrences.", "credited_answers": ["authenticity probably means genuineness, truthfulness, realness. I think this because of the real vs dramatized contrast in the sentence."], "explanation": "Meaning in context: genuineness; truth to facts. Reusable pattern: real vs dramatized contrast. Quick synonyms: genuineness, truthfulness, realness. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 3, "prompt": "The *crescendo* of public enthusiasm for the festival reached its peak as the main musical act took the stage, with the crowd''s energy building to an explosive climax.", "credited_answers": ["crescendo probably means climax, build-up, swelling. I think this because of the rising-to-peak signal in the sentence."], "explanation": "Meaning in context: a rise building to a peak. Reusable pattern: rising-to-peak signal. Quick synonyms: climax, build-up, swelling. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 4, "prompt": "The scientist''s approach was *a priori*, developing theories through logical reasoning rather than direct observation.", "credited_answers": ["a priori probably means theoretical, deductive, presumed. I think this because of the reasoning-not-observation contrast in the sentence."], "explanation": "Meaning in context: from reasoning, not experience. Reusable pattern: reasoning-not-observation contrast. Quick synonyms: theoretical, deductive, presumed. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 5, "prompt": "After the oil spill, the environmental agency focused on the *abatement* of pollution to minimize harm to local wildlife. The reduction of contaminants was crucial.", "credited_answers": ["abatement probably means reduction, lessening, decline. I think this because of the minimize/reduce signal in the sentence."], "explanation": "Meaning in context: a reduction or decrease. Reusable pattern: minimize/reduce signal. Quick synonyms: reduction, lessening, decline. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 6, "prompt": "Recognizing that the demands of the presidency were overwhelming, the leader chose to *abdicate* and pass the responsibility to a successor.", "credited_answers": ["abdicate probably means step down, resign, relinquish. I think this because of the hand-off signal (\"pass the responsibility to a successor\") in the sentence."], "explanation": "Meaning in context: to give up a position or duty formally. Reusable pattern: hand-off signal (\"pass the responsibility to a successor\"). Quick synonyms: step down, resign, relinquish. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 7, "prompt": "The sudden, *aberrant* behavior of the normally placid animal surprised the researchers.", "credited_answers": ["aberrant probably means abnormal, atypical, deviant. I think this because of the normally-x contrast (\"normally placid,\" \"surprised\") in the sentence."], "explanation": "Meaning in context: departing from what is normal. Reusable pattern: normally-X contrast (\"normally placid,\" \"surprised\"). Quick synonyms: abnormal, atypical, deviant. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 8, "prompt": "Geologists study *abiogenic* processes to understand how certain minerals form without the influence of life.", "credited_answers": ["abiogenic probably means non-biological, lifeless in origin. I think this because of the in-sentence definition (\"without the influence of life\") + prefix *a-* = not, *bio-* = life in the sentence."], "explanation": "Meaning in context: arising without living organisms. Reusable pattern: in-sentence definition (\"without the influence of life\") + prefix *a-* = not, *bio-* = life. Quick synonyms: non-biological, lifeless in origin. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 9, "prompt": "The *abolition* of outdated laws was essential for creating a more just legal system, ensuring progress was not hindered by archaic rules.", "credited_answers": ["abolition probably means elimination, repeal, ending. I think this because of the removal signal (outdated rules no longer hindering) in the sentence."], "explanation": "Meaning in context: formal ending or doing away with. Reusable pattern: removal signal (outdated rules no longer hindering). Quick synonyms: elimination, repeal, ending. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 10, "prompt": "Efforts to preserve *aboriginal* cultures often focus on traditions that predate colonization.", "credited_answers": ["aboriginal probably means original, indigenous, earliest. I think this because of the time-priority signal (\"predate colonization,\" \"ancient ways\") in the sentence."], "explanation": "Meaning in context: original to a place, from the earliest time. Reusable pattern: time-priority signal (\"predate colonization,\" \"ancient ways\"). Quick synonyms: original, indigenous, earliest. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 11, "prompt": "Using an *abrasive* scrub, the workers cleaned the corroded metal, revealing a shiny surface beneath.", "credited_answers": ["abrasive probably means rough, scouring, grinding. I think this because of the function-from-result (\"cleaned the corroded metal,\" \"revealing a shiny surface\") in the sentence."], "explanation": "Meaning in context: rough; wearing a surface away by friction. Reusable pattern: function-from-result (\"cleaned the corroded metal,\" \"revealing a shiny surface\"). Quick synonyms: rough, scouring, grinding. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 12, "prompt": "Her *laconic* reply left the board uncertain whether she supported the motion.", "credited_answers": ["laconic probably means terse, brief, curt. I think this because of the consequence clue: too little said to tell in the sentence."], "explanation": "Meaning in context: using very few words. Reusable pattern: consequence clue: too little said to tell. Quick synonyms: terse, brief, curt. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 13, "prompt": "By the time the product launched, its marketing was *ubiquitous*, saturating every commute.", "credited_answers": ["ubiquitous probably means omnipresent, pervasive, everywhere. I think this because of the saturation restatement in the sentence."], "explanation": "Meaning in context: present everywhere. Reusable pattern: saturation restatement. Quick synonyms: omnipresent, pervasive, everywhere. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 14, "prompt": "The memo urged analysts to *eschew* speculation and rely solely on audited figures.", "credited_answers": ["eschew probably means avoid, shun, abstain from. I think this because of the *and rely solely on* opposition in the sentence."], "explanation": "Meaning in context: to deliberately avoid. Reusable pattern: *and rely solely on* opposition. Quick synonyms: avoid, shun, abstain from. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 15, "prompt": "The most *salient* detail in the report was the unexplained spike in returns.", "credited_answers": ["salient probably means prominent, striking, standout. I think this because of the superlative + the thing singled out in the sentence."], "explanation": "Meaning in context: most noticeable or important. Reusable pattern: superlative + the thing singled out. Quick synonyms: prominent, striking, standout. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 16, "prompt": "Investors hesitated, wary of the market''s *capricious* mood swings.", "credited_answers": ["capricious probably means unpredictable, erratic, fickle. I think this because of the *mood swings* restatement, negative valence in the sentence."], "explanation": "Meaning in context: changing suddenly and without reason. Reusable pattern: *mood swings* restatement, negative valence. Quick synonyms: unpredictable, erratic, fickle. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 17, "prompt": "Her *pragmatic* fix didn''t impress purists, but it solved the outage in minutes.", "credited_answers": ["pragmatic probably means practical, workable, results-focused. I think this because of the purists-vs-worked contrast in the sentence."], "explanation": "Meaning in context: practical; focused on what works. Reusable pattern: purists-vs-worked contrast. Quick synonyms: practical, workable, results-focused. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 18, "prompt": "Skipping quality checks had a *deleterious* effect on customer trust.", "credited_answers": ["deleterious probably means damaging, harmful, injurious. I think this because of the cause is a lapse, so the effect is bad in the sentence."], "explanation": "Meaning in context: harmful. Reusable pattern: cause is a lapse, so the effect is bad. Quick synonyms: damaging, harmful, injurious. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 19, "prompt": "He was *circumspect* in his comments, avoiding anything that might be construed as an admission.", "credited_answers": ["circumspect probably means cautious, guarded, wary. I think this because of the *avoiding anything that might* expansion in the sentence."], "explanation": "Meaning in context: cautious; watchful of consequences. Reusable pattern: *avoiding anything that might* expansion. Quick synonyms: cautious, guarded, wary. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 20, "prompt": "The playful tone felt *incongruous* with the gravity of the findings.", "credited_answers": ["incongruous probably means mismatched, out of place, jarring. I think this because of the playful-vs-gravity mismatch in the sentence."], "explanation": "Meaning in context: out of keeping; not fitting together. Reusable pattern: playful-vs-gravity mismatch. Quick synonyms: mismatched, out of place, jarring. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 21, "prompt": "The policy aims to *ameliorate* the delays without increasing costs.", "credited_answers": ["ameliorate probably means improve, ease, alleviate. I think this because of the goal-directed improvement in the sentence."], "explanation": "Meaning in context: to make better; to ease. Reusable pattern: goal-directed improvement. Quick synonyms: improve, ease, alleviate. Say what the word probably means AND why, citing the clue. A definition with no reasoning is not a complete answer.", "category": "Joshua''s worksheet"}, {"order": 22, "prompt": "The commission''s work was surprisingly *remunerative*, paying enough over three years that two of its members gave up their practices to serve full time.", "credited_answers": ["*Remunerative* probably means well paid or profitable. I think this because the sentence expands it immediately: paying enough that members could give up their practices."], "explanation": "Clue: appositive expansion. Boundary: it is about payment, not about being worthwhile or important.", "category": "Tier 1: The clue sits next to the word"}, {"order": 23, "prompt": "The specimens arrived *desiccated*, dried so completely that the leaves crumbled when the box was opened.", "credited_answers": ["*Desiccated* probably means dried out or moisture-free. I think this because the next clause defines it: dried so completely that the leaves crumbled."], "explanation": "Clue: in-sentence definition.", "category": "Tier 1: The clue sits next to the word"}, {"order": 24, "prompt": "The new drainage scheme proved *inimical* to the meadow, working steadily against the very conditions the reserve had been created to hold.", "credited_answers": ["*Inimical* probably means harmful or actively opposed to. I think this because it is restated as working steadily against those conditions."], "explanation": "Clue: restatement. Boundary: stronger than merely unhelpful. It implies working against.", "category": "Tier 1: The clue sits next to the word"}, {"order": 25, "prompt": "His output over those years was *prodigious*: four novels, two translations, and a correspondence that fills nine volumes.", "credited_answers": ["*Prodigious* probably means enormous or extraordinarily large. I think this because the colon introduces a list whose whole point is the quantity."], "explanation": "Clue: post-word example list.", "category": "Tier 1: The clue sits next to the word"}, {"order": 26, "prompt": "The final statement was so *anodyne* that no delegate could object to it and no delegate could remember it an hour later.", "credited_answers": ["*Anodyne* probably means inoffensive or bland. I think this because the sentence says nobody could object and nobody could remember."], "explanation": "Clue: paired consequence. Boundary: not *false* and not *short*. Inoffensive to the point of being forgettable.", "category": "Tier 1: The clue sits next to the word"}, {"order": 27, "prompt": "The normally accommodating chair turned *truculent* the moment the audit was mentioned, cutting off two speakers and refusing the motion outright.", "credited_answers": ["*Truculent* probably means aggressive or hostile. I think this because it is set against *normally accommodating*, and the behaviour after it is cutting people off."], "explanation": "Clue: normally-X contrast plus behavioural evidence.", "category": "Tier 2: Direct contrast"}, {"order": 28, "prompt": "Where the other founders left modest bequests, hers was *munificent*, endowing the library, the chair in classics, and the whole east wing.", "credited_answers": ["*Munificent* probably means extremely generous or lavish. I think this because it is contrasted with *modest bequests* and followed by a list of large gifts."], "explanation": "Clue: contrast plus list.", "category": "Tier 2: Direct contrast"}, {"order": 29, "prompt": "The argument looked sound on first reading and turned out to be *specious*: every step followed except the one that mattered.", "credited_answers": ["*Specious* probably means seemingly right but actually false. I think this because it is set against *looked sound on first reading*, and the colon says one step failed."], "explanation": "Clue: appearance-versus-reality contrast. Boundary: not simply *wrong*. The point is that it looks right.", "category": "Tier 2: Direct contrast"}, {"order": 30, "prompt": "One side moved on every point of substance; the other remained *intransigent*, conceding nothing across eleven sessions.", "credited_answers": ["*Intransigent* probably means unwilling to compromise or immovable. I think this because it is contrasted with the side that moved, and expanded by *conceding nothing*."], "explanation": "Clue: contrast plus expansion.", "category": "Tier 2: Direct contrast"}, {"order": 31, "prompt": "Most of the testimony wandered into matters the tribunal had no power to consider. Only the section on the timeline was *germane*.", "credited_answers": ["*Germane* probably means relevant or on point. I think this because it is set against testimony that wandered outside what the tribunal could consider."], "explanation": "Clue: contrast across sentences.", "category": "Tier 2: Direct contrast"}, {"order": 32, "prompt": "The clinic''s *ancillary* services grew faster than its clinical ones: transport, interpretation, records retrieval, and a small pharmacy.", "credited_answers": ["*Ancillary* probably means supporting or secondary. I think this because the list after the colon is all support functions rather than the clinical work itself."], "explanation": "Clue: post-word list. Boundary: secondary in role, not necessarily minor in size. The sentence says they grew faster.", "category": "Tier 3: Example list or evidence after the word"}, {"order": 33, "prompt": "He was *peripatetic* even by the standards of his trade, holding posts in Lisbon, Kraków, Montreal, and finally Perth, none for longer than three years.", "credited_answers": ["*Peripatetic* probably means constantly moving or itinerant. I think this because the list is a sequence of places and the closing clause says none lasted long."], "explanation": "Clue: list plus duration evidence.", "category": "Tier 3: Example list or evidence after the word"}, {"order": 34, "prompt": "The room was *redolent* of the building''s earlier life: coal dust, machine oil, and something faintly like wet rope.", "credited_answers": ["*Redolent* probably means strongly smelling of, or strongly suggestive of. I think this because the list after the colon is all smells."], "explanation": "Clue: post-word list. Boundary: it can be literal smell or figurative evocation, and here it is doing both.", "category": "Tier 3: Example list or evidence after the word"}, {"order": 35, "prompt": "The estate''s accounts describe a *profligate* decade: two houses bought and sold at a loss, a racing stable, and a subscription to an opera company that never performed.", "credited_answers": ["*Profligate* probably means recklessly extravagant or wasteful. I think this because the list is expensive things that produced nothing."], "explanation": "Clue: list with a shared negative pattern. Boundary: wasteful, not merely rich.", "category": "Tier 3: Example list or evidence after the word"}, {"order": 36, "prompt": "She was *assiduous* about the checking: every entry read twice, every source noted, every discrepancy logged with a date.", "credited_answers": ["*Assiduous* probably means diligent or painstakingly thorough. I think this because the colon introduces three parallel examples of careful repeated work."], "explanation": "Clue: parallel example list.", "category": "Tier 3: Example list or evidence after the word"}, {"order": 37, "prompt": "The field is *nascent* rather than established: three laboratories, one journal, and no agreed method.", "credited_answers": ["*Nascent* probably means new or just beginning. I think this because it is placed directly against *established*, and the evidence is how little exists yet."], "explanation": "Clue: explicit antonym.", "category": "Tier 4: Antonym or opposition clue"}, {"order": 38, "prompt": "The earlier accounts are transparent about their sources. This one is *opaque*, and after two readings I still cannot tell where the figures came from.", "credited_answers": ["*Opaque* probably means unclear or impossible to see into. I think this because it is opposed to *transparent* and followed by not being able to tell where figures came from."], "explanation": "Clue: antonym plus consequence. Boundary: unclear to the reader, not secret by intent.", "category": "Tier 4: Antonym or opposition clue"}, {"order": 39, "prompt": "Nothing about the arrangement was *ephemeral*; the parties expected it to outlast all of them, and it did.", "credited_answers": ["*Ephemeral* probably means short-lived or fleeting. I think this because it is negated and set against outlasting everyone."], "explanation": "Clue: negation plus opposite. Note: the word appears under a *not*, so the student has to flip once before answering.", "category": "Tier 4: Antonym or opposition clue"}, {"order": 40, "prompt": "The defence pressed for the second file, arguing that where the first was incriminating the second was *exculpatory*.", "credited_answers": ["*Exculpatory* probably means clearing of blame or tending to show innocence. I think this because it is set directly against *incriminating*."], "explanation": "Clue: explicit antonym.", "category": "Tier 4: Antonym or opposition clue"}, {"order": 41, "prompt": "Every forecast in the room was gloomy except hers, which was *sanguine* about all three quarters.", "credited_answers": ["*Sanguine* probably means optimistic or cheerfully confident. I think this because it is the exception to gloomy forecasts."], "explanation": "Clue: exception-to-the-set. Boundary: optimistic, not merely calm.", "category": "Tier 4: Antonym or opposition clue"}, {"order": 42, "prompt": "The survey is presented as neutral, but it asks about waste before it asks about services, describes one option as a burden and the other as an investment, and offers no box for ''neither.'' Calling it *tendentious* is generous.", "credited_answers": ["*Tendentious* probably means biased or written to push a conclusion. I think this because the whole paragraph is a list of ways the survey is loaded, and the last sentence says the word is a mild description of it."], "explanation": "Clue: whole-paragraph accumulation. Boundary: biased on purpose, not simply mistaken.", "category": "Tier 5: No nearby clue; the paragraph''s structure carries it"}, {"order": 43, "prompt": "He worked at it for a decade in a *desultory* way, weeks of nothing followed by a fortnight of intensity, no plan across the years, each return starting from wherever he had stopped.", "credited_answers": ["*Desultory* probably means unmethodical or lacking a steady plan. I think this because the rest of the sentence describes work with no continuity or direction."], "explanation": "Clue: structural description after the word. Boundary: it is about lacking method, not about lacking effort.", "category": "Tier 5: No nearby clue; the paragraph''s structure carries it"}, {"order": 44, "prompt": "Of the four quotations he might have used, only one actually concerned the question of who bore the cost, and that is the one he chose. The choice was *apposite*.", "credited_answers": ["*Apposite* probably means fitting or exactly suited to the point. I think this because the previous sentence sets up that only one of four was on the real question and he picked it."], "explanation": "Clue: prior-sentence setup. Boundary: well suited, not merely correct.", "category": "Tier 5: No nearby clue; the paragraph''s structure carries it"}, {"order": 45, "prompt": "The theory in that first paper is *inchoate*. The terms shift between sections, two of the central claims are stated only as questions, and the mechanism is named but never described.", "credited_answers": ["*Inchoate* probably means unformed or only partly developed. I think this because the following sentence lists ways the theory is not finished."], "explanation": "Clue: following-sentence evidence. Boundary: undeveloped, not wrong.", "category": "Tier 5: No nearby clue; the paragraph''s structure carries it"}, {"order": 46, "prompt": "What the diaries record is *quotidian* almost throughout: what was eaten, what the weather did, who called and for how long. The two pages everyone quotes are the exception.", "credited_answers": ["*Quotidian* probably means everyday or ordinary. I think this because the list is routine daily detail and the famous pages are called the exception."], "explanation": "Clue: list plus exception framing.", "category": "Tier 5: No nearby clue; the paragraph''s structure carries it"}, {"order": 47, "prompt": "The panel wanted a *disinterested* assessor, someone with no stake in either outcome, and spent four months finding one.", "credited_answers": ["*Disinterested* probably means impartial or having no stake. I think this because the sentence defines it: no stake in either outcome."], "explanation": "The trap: *uninterested*, meaning bored. The paragraph rules it out. Someone bored would not take four months to find.", "category": "Tier 6: Precision traps"}, {"order": 48, "prompt": "The introduction is so *fulsome* in its praise of the donor that the reader begins to doubt the rest of the book.", "credited_answers": ["*Fulsome* probably means excessive or so overdone it reads as insincere. I think this because the praise causes the reader to doubt the book."], "explanation": "The trap: *generous* or *full*. Those are positive; the clue is that it produces doubt.", "category": "Tier 6: Precision traps"}, {"order": 49, "prompt": "Two hours in that room *enervated* the whole committee, and the afternoon session achieved nothing.", "credited_answers": ["*Enervated* probably means drained or sapped of energy. I think this because the afternoon achieved nothing afterward."], "explanation": "The trap: *energized*, which the word looks like and which the consequence contradicts.", "category": "Tier 6: Precision traps"}, {"order": 50, "prompt": "She was *nonplussed* by the question and said nothing at all for several seconds.", "credited_answers": ["*Nonplussed* probably means bewildered or at a loss. I think this because she was silent for several seconds."], "explanation": "The trap: *unbothered*, from reading *non-* as a simple negative. The evidence is a pause, which is what confusion looks like.", "category": "Tier 6: Precision traps"}, {"order": 51, "prompt": "The meeting was entirely *fortuitous*; neither of them had known the other would be in the city that week.", "credited_answers": ["*Fortuitous* probably means happening by chance or accidental. I think this because neither knew the other would be there."], "explanation": "The trap: *fortunate*. Nothing in the sentence says the meeting was lucky, only that it was unplanned.", "category": "Tier 6: Precision traps"}]'::jsonb,
    NULL,
    NULL,
    NULL
  ),
  (
    'spot-the-relationship',
    'Spot the Relationship',
    'Name the relationship and the exact words that create it',
    '{"coach": {"drill": "a relationship-identification drill: the student names whether a statement is conditional, causal or comparative, and quotes the exact word or words that create it", "rubric": ["A correct answer has two parts and needs both: the relationship type, and the exact indicator word or words from the statement. Type alone is not a complete answer.", "A statement can carry more than one relationship. When it does, every relationship must be named with its own indicators, and naming a relationship that is not there is also wrong.", "The strongest causal indicator is often a verb rather than a connective. Raises, drives, yields, starves, dries, lowers and homogenizes are causal words, and a student who quotes one has found the right thing.", "Requirement language is conditional, not causal. Requires, depends on, contingent on and provided name what must be true; they do not claim that anything made anything happen.", "Accept any reasonable quotation of the indicator. Do not penalise capitalisation, a slightly wider or narrower span, or a student who writes only if as only-if."], "partial_rule": "Mark ''partial'' when the student names the right type with wrong or missing indicators, quotes the credited indicators but labels the type wrongly, or finds some but not all of the relationships in a multi-relationship statement. Mark ''incorrect'' only when both parts miss."}, "tagline": "Type plus the exact words. Both halves, every time.", "task": "Tell me what kind of relationship this statement contains and the exact word or words that create it. If there is more than one, name them all.", "rules": ["Answer in the game format: type, then the words. Conditional, only if. Causal, caused. Comparative, heavier than.", "A conditional says what must be true. A causal says one thing made another happen. A comparative measures one thing against another.", "Causal words are often verbs, not connectives. Raises, drives, dries, starves and lowers are all causal.", "Requires, depends on and contingent on are conditional. They name a requirement, not a mechanism.", "Some statements carry two or three relationships at once. Name every one you find."], "worked_example": {"statement": "A lantern can be lit only if its wick is dry.", "credited_answers": ["conditional, only if"], "explanation": "Only if introduces the necessary condition. A dry wick is required for lighting, which is not the same as saying a dry wick makes the lantern light. That would be causal, and this statement does not claim it."}, "answer_label": "Your answer", "answer_placeholder": "Name the relationship and the exact words that create it…"}'::jsonb,
    'free-text',
    '[{"order": 1, "prompt": "A greenhouse vent opens only if the interior temperature exceeds 28 degrees.", "credited_answers": ["conditional, \"only if\""], "explanation": "1 relationship in this statement. The textbook necessary condition.", "category": "Rung 1: Single relationship, classic indicators"}, {"order": 2, "prompt": "If the ferry misses the tide, it docks at the outer berth.", "credited_answers": ["conditional, \"if\""], "explanation": "1 relationship in this statement. The plain sufficient condition, front seat.", "category": "Rung 1: Single relationship, classic indicators"}, {"order": 3, "prompt": "Whenever the tide gauge is recalibrated, the readings shift by a few centimetres.", "credited_answers": ["conditional, \"whenever\""], "explanation": "1 relationship in this statement. Reads like time, works like *if*.", "category": "Rung 1: Single relationship, classic indicators"}, {"order": 4, "prompt": "A permit is required before any tree on the boulevard may be removed.", "credited_answers": ["conditional, \"required\""], "explanation": "1 relationship in this statement. First requirement verb. No claim that the permit makes anything happen.", "category": "Rung 1: Single relationship, classic indicators"}, {"order": 5, "prompt": "A blocked flue caused the smoke to back into the reading room.", "credited_answers": ["causal, \"caused\""], "explanation": "1 relationship in this statement. The clean case, matching his heater seed.", "category": "Rung 1: Single relationship, classic indicators"}, {"order": 6, "prompt": "The late frost destroyed most of the apricot blossom.", "credited_answers": ["causal, \"destroyed\""], "explanation": "1 relationship in this statement. First verb-only causal. There is no connective at all.", "category": "Rung 1: Single relationship, classic indicators"}, {"order": 7, "prompt": "Salt spray corroded the bridge''s lower bolts.", "credited_answers": ["causal, \"corroded\""], "explanation": "1 relationship in this statement. Same shape, different verb. Say the verb aloud and the causation is audible.", "category": "Rung 1: Single relationship, classic indicators"}, {"order": 8, "prompt": "The new filter produced a measurable drop in turbidity.", "credited_answers": ["causal, \"produced\""], "explanation": "1 relationship in this statement. Matches the \"produced\" indicator from his own list.", "category": "Rung 1: Single relationship, classic indicators"}, {"order": 9, "prompt": "The bronze bell is louder than the iron one.", "credited_answers": ["comparative, \"louder than\""], "explanation": "1 relationship in this statement. The twin of his astrolabe seed.", "category": "Rung 1: Single relationship, classic indicators"}, {"order": 10, "prompt": "This year''s harvest came in lighter than last year''s.", "credited_answers": ["comparative, \"lighter than\""], "explanation": "1 relationship in this statement. Comparison across time rather than objects.", "category": "Rung 1: Single relationship, classic indicators"}, {"order": 11, "prompt": "The southern route takes less time than the coastal one.", "credited_answers": ["comparative, \"less time than\""], "explanation": "1 relationship in this statement. The comparison sits in a noun phrase.", "category": "Rung 1: Single relationship, classic indicators"}, {"order": 12, "prompt": "The oak beam is as strong as the steel channel it replaced.", "credited_answers": ["comparative, \"as strong as\""], "explanation": "1 relationship in this statement. Equality, not superiority. Still comparative.", "category": "Rung 1: Single relationship, classic indicators"}, {"order": 13, "prompt": "The kiln reaches cone 10 only when the damper is fully closed.", "credited_answers": ["conditional, \"only when\""], "explanation": "1 relationship in this statement. Pair A, conditional half. A requirement, not a mechanism.", "category": "Rung 2: Discrimination"}, {"order": 14, "prompt": "Closing the damper raises the kiln to cone 10.", "credited_answers": ["causal, \"raises\""], "explanation": "1 relationship in this statement. Pair A, causal half. Same facts, and now the sentence claims the closing *makes* the rise happen.", "category": "Rung 2: Discrimination"}, {"order": 15, "prompt": "A stable emulsion requires an added lecithin.", "credited_answers": ["conditional, \"requires\""], "explanation": "1 relationship in this statement. Pair B, conditional half. *Requires* is the most-missed conditional word in the bank.", "category": "Rung 2: Discrimination"}, {"order": 16, "prompt": "Adding lecithin stabilizes the emulsion.", "credited_answers": ["causal, \"stabilizes\""], "explanation": "1 relationship in this statement. Pair B, causal half.", "category": "Rung 2: Discrimination"}, {"order": 17, "prompt": "The grant is contingent on a matching pledge from the county.", "credited_answers": ["conditional, \"contingent on\""], "explanation": "1 relationship in this statement. Pair C, conditional half.", "category": "Rung 2: Discrimination"}, {"order": 18, "prompt": "The matching pledge from the county secured the grant.", "credited_answers": ["causal, \"secured\""], "explanation": "1 relationship in this statement. Pair C, causal half.", "category": "Rung 2: Discrimination"}, {"order": 19, "prompt": "Certification depends on an unbroken chain of custody.", "credited_answers": ["conditional, \"depends on\""], "explanation": "1 relationship in this statement. Pair D, conditional half. His own necessary-condition verb, reused here.", "category": "Rung 2: Discrimination"}, {"order": 20, "prompt": "The broken chain of custody sank the certification.", "credited_answers": ["causal, \"sank\""], "explanation": "1 relationship in this statement. Pair D, causal half. An informal verb still carries the causal claim.", "category": "Rung 2: Discrimination"}, {"order": 21, "prompt": "No manuscript is catalogued unless a conservator has signed the condition report.", "credited_answers": ["conditional, \"unless\""], "explanation": "1 relationship in this statement. Negative main clause plus *unless*, the pair students scramble most.", "category": "Rung 2: Discrimination"}, {"order": 22, "prompt": "Longer soak times yield a deeper indigo.", "credited_answers": ["causal, \"yield\""], "explanation": "1 relationship in this statement. Bait: the comparatives *longer* and *deeper* are real words on the page, but neither one compares two named things. The sentence claims a mechanism.", "category": "Rung 2: Discrimination"}, {"order": 23, "prompt": "The archive''s holdings are more extensive than the university library''s.", "credited_answers": ["comparative, \"more extensive than\""], "explanation": "1 relationship in this statement. Clean comparative after two baited items.", "category": "Rung 2: Discrimination"}, {"order": 24, "prompt": "Peat soils hold water better than sandy soils do.", "credited_answers": ["comparative, \"better than\""], "explanation": "1 relationship in this statement. Comparison of a capacity rather than a property.", "category": "Rung 2: Discrimination"}, {"order": 25, "prompt": "The tremor registered stronger on the eastern array than on the western.", "credited_answers": ["comparative, \"stronger than\""], "explanation": "1 relationship in this statement. One event, two measurements. Still a comparison.", "category": "Rung 2: Discrimination"}, {"order": 26, "prompt": "Because the sluice was left open, the lower field flooded.", "credited_answers": ["causal, \"because\""], "explanation": "1 relationship in this statement. The word that does double duty. Here it names a cause. In an argument the same word marks support, which is why the Coach names the ambiguity rather than letting a rule form.", "category": "Rung 2: Discrimination"}, {"order": 27, "prompt": "Only if the vat is held below four degrees does the culture stay viable, because warmth accelerates the competing bacteria.", "credited_answers": ["conditional, \"Only if\"; causal, \"because\" and \"accelerates\""], "explanation": "2 relationships in this statement. Two relationships. The causal clause is doing explanatory work for the conditional one.", "category": "Rung 3: Compound statements"}, {"order": 28, "prompt": "The northern kiln fires more evenly than the southern one, since its flue draws harder.", "credited_answers": ["comparative, \"more evenly than\"; causal, \"since\" and \"draws\""], "explanation": "2 relationships in this statement. Note *harder* is part of the causal clause, not a second comparison between two named things.", "category": "Rung 3: Compound statements"}, {"order": 29, "prompt": "Only when the moisture content falls lower than eight percent will the beams season without checking, because trapped water expands the grain.", "credited_answers": ["conditional, \"Only when\"; comparative, \"lower than\"; causal, \"because\" and \"expands\""], "explanation": "3 relationships in this statement. The full triple, matching his kiln seed''s shape.", "category": "Rung 3: Compound statements"}, {"order": 30, "prompt": "Unless the primer is thinner than the topcoat, the finish will craze, since the layers cure at different rates.", "credited_answers": ["conditional, \"Unless\"; comparative, \"thinner than\"; causal, \"since\" and \"cure\""], "explanation": "3 relationships in this statement. Triple, with the conditional in its negative form.", "category": "Rung 3: Compound statements"}, {"order": 31, "prompt": "The heavier bell carries farther than the light one, which is why the foundry cast the alarm bell in the larger mould.", "credited_answers": ["comparative, \"heavier\" and \"farther than\"; causal, \"which is why\""], "explanation": "2 relationships in this statement. A causal connective that is not a single word.", "category": "Rung 3: Compound statements"}, {"order": 32, "prompt": "The rate rises only when demand exceeds supply, and the rise itself dampens demand.", "credited_answers": ["conditional, \"only when\"; comparative, \"exceeds\"; causal, \"dampens\""], "explanation": "3 relationships in this statement. *Exceeds* is a comparison hiding in a verb.", "category": "Rung 3: Compound statements"}, {"order": 33, "prompt": "Provided the sample is colder than the reference cell, the reading drifts upward, because the thermocouple lags.", "credited_answers": ["conditional, \"Provided\"; comparative, \"colder than\"; causal, \"because\" and \"lags.\""], "explanation": "3 relationships in this statement.", "category": "Rung 3: Compound statements"}, {"order": 34, "prompt": "The eastern quarry yields harder stone than the western, so masons reserve it for thresholds, but only if the block is free of iron staining.", "credited_answers": ["comparative, \"harder than\"; causal, \"so\"; conditional, \"only if\""], "explanation": "3 relationships in this statement. Three relationships in three clauses, in an order that hides the conditional at the end.", "category": "Rung 3: Compound statements"}, {"order": 35, "prompt": "Since the mill race silted, the wheel turns slower than it did, and the mill cannot grind unless the race is dredged each spring.", "credited_answers": ["causal, \"Since\" and \"silted\"; comparative, \"slower than\"; conditional, \"unless\""], "explanation": "3 relationships in this statement. The causal opens, which students read as a support indicator.", "category": "Rung 3: Compound statements"}, {"order": 36, "prompt": "Repointing lasts longer when the mortar is softer than the brick, because a hard mortar drives the stress into the face of the brick.", "credited_answers": ["conditional, \"when\"; comparative, \"longer\" and \"softer than\"; causal, \"because\" and \"drives.\""], "explanation": "3 relationships in this statement.", "category": "Rung 3: Compound statements"}, {"order": 37, "prompt": "The transplant takes only if the rootstock is more vigorous than the scion, since a weak stock starves the graft.", "credited_answers": ["conditional, \"only if\"; comparative, \"more vigorous than\"; causal, \"since\" and \"starves.\""], "explanation": "3 relationships in this statement.", "category": "Rung 3: Compound statements"}, {"order": 38, "prompt": "Only where the canopy is denser than sixty percent do the seedlings survive, because direct sun dries the litter layer.", "credited_answers": ["conditional, \"Only where\"; comparative, \"denser than\"; causal, \"because\" and \"dries\""], "explanation": "3 relationships in this statement. *Only where* is the spatial sibling of *only when*.", "category": "Rung 3: Compound statements"}, {"order": 39, "prompt": "Only when the delta-13C value of the sample sits closer to the C3 range than to the C4 range will the provenance panel accept the attribution, since maize agriculture elevates the ratio.", "credited_answers": ["conditional, \"Only when\"; comparative, \"closer to … than to\"; causal, \"since\" and \"elevates\""], "explanation": "3 relationships in this statement. The twin of his vanilla-extract seed, same triple, different field.", "category": "Rung 4: The same structures under jargon"}, {"order": 40, "prompt": "Anodization passivates the surface, so a coupon with a thicker oxide layer than the control resists pitting, provided the electrolyte is chloride-free.", "credited_answers": ["causal, \"passivates\" and \"so\"; comparative, \"thicker than\"; conditional, \"provided\"; Causal first, conditional last, which inverts the usual reading order."], "explanation": "4 relationships in this statement.", "category": "Rung 4: The same structures under jargon"}, {"order": 41, "prompt": "Unless the interstitial fluid osmolality exceeds that of the tubular filtrate, the countercurrent multiplier cannot concentrate the urine, because water follows the gradient.", "credited_answers": ["conditional, \"Unless\"; comparative, \"exceeds\"; causal, \"because\" and \"follows.\""], "explanation": "3 relationships in this statement.", "category": "Rung 4: The same structures under jargon"}, {"order": 42, "prompt": "A dendrochronological match is accepted only if the cross-correlation coefficient is higher than the site threshold, since spurious matches inflate at short series lengths.", "credited_answers": ["conditional, \"only if\"; comparative, \"higher than\"; causal, \"since\" and \"inflate.\""], "explanation": "3 relationships in this statement.", "category": "Rung 4: The same structures under jargon"}, {"order": 43, "prompt": "The catalyst lowers the activation barrier, which is why the reaction proceeds faster at ambient temperature than the uncatalyzed route does.", "credited_answers": ["causal, \"lowers\" and \"which is why\"; comparative, \"faster … than\""], "explanation": "2 relationships in this statement. Two relationships only, in a rung where students start expecting three. Naming a relationship that is not there is not a correct answer.", "category": "Rung 4: The same structures under jargon"}, {"order": 44, "prompt": "Only where the sediment''s magnetic susceptibility runs lower than the regional baseline does the core preserve an intact excursion, because bioturbation homogenizes the signal.", "credited_answers": ["conditional, \"Only where\"; comparative, \"lower than\"; causal, \"because\" and \"homogenizes.\""], "explanation": "3 relationships in this statement.", "category": "Rung 4: The same structures under jargon"}, {"order": 45, "prompt": "Provided the assay''s limit of detection is finer than the regulatory threshold, a null result is meaningful, since a coarse assay produces nulls that mean nothing.", "credited_answers": ["conditional, \"Provided\"; comparative, \"finer than\"; causal, \"since\" and \"produces.\""], "explanation": "3 relationships in this statement.", "category": "Rung 4: The same structures under jargon"}, {"order": 46, "prompt": "Isostatic rebound raises the shoreline, so a terrace formed after deglaciation sits higher than one formed before, unless local subsidence offsets the uplift.", "credited_answers": ["causal, \"raises\" and \"so\"; comparative, \"higher than\"; conditional, \"unless\""], "explanation": "3 relationships in this statement. The conditional arrives last, after the student has already committed.", "category": "Rung 4: The same structures under jargon"}, {"order": 47, "prompt": "The membrane fouls only when the transmembrane pressure climbs above the critical flux, and the fouling itself drives the pressure higher still.", "credited_answers": ["conditional, \"only when\"; comparative, \"above\" and \"higher still\"; causal, \"drives\""], "explanation": "3 relationships in this statement. A feedback loop: the effect feeds the condition.", "category": "Rung 4: The same structures under jargon"}, {"order": 48, "prompt": "Only if the radiocarbon date is calibrated against a curve more regionally appropriate than the global one can the offset be trusted, because atmospheric mixing produces hemispheric differences.", "credited_answers": ["conditional, \"Only if\"; comparative, \"more … than\"; causal, \"because\" and \"produces\""], "explanation": "3 relationships in this statement. The hardest reading order in the bank: the conditional''s main clause is inverted and sits behind a long comparative phrase.", "category": "Rung 4: The same structures under jargon"}]'::jsonb,
    NULL,
    NULL,
    NULL
  ),
  (
    'conditional-rephrase',
    'Conditional Rephrase',
    'Put the statement into if-then, then turn it around',
    '{"coach": {"drill": "a conditional-translation drill: the student rewrites a statement as If [sufficient], then [necessary] and gives its contrapositive", "rubric": ["Two forms are credited and they are the same statement: the if-then form, and its contrapositive. A student who gives either one has translated correctly. On an ordinary one-way conditional, nothing else counts as a direction: the converse (swapping the two sides) and the inverse (negating both without swapping) are errors, not alternative phrasings. Biconditional items are the stated exception, covered below.", "The core judgment is which condition is sufficient and which is necessary. Words like if, when, whenever, every, all and the only mark the sufficient side. Words like only if, only when, unless, without, except, requires, presupposes, depends on, necessitates and must mark the necessary side.", "Compound conditions (both X and Y) and internal contrasts (X rather than Y) must be carried into the answer whole, not simplified away.", "The compound flip is a correctness rule, not a stylistic one. Contraposing \"If A and B, then C\" yields \"If not C, then not A or not B\". A student who carries the and through unchanged has written a stronger claim than the statement supports, and that is an error to name, not a phrasing quibble. The same applies in reverse: an or on the trigger side becomes an and.", "Two errors have names worth using in the feedback, and both apply to one-way conditionals, not to biconditionals. Reversing the arrow is treating the necessary condition as if meeting it guaranteed the trigger. Negating the trigger is concluding that because the trigger did not fire, the outcome cannot happen. Say which one the student made.", "Unless, until and without translate as if not on the trigger side. When the idea being negated there is itself a compound, the and or or inside it flips too.", "With no and none the negation attaches to the necessary side, never to the trigger. The subject of the sentence still goes on the if side, intact.", "If and only if, then and only then, and the otherwise construction are biconditionals, where the arrow genuinely runs both ways and the converse is therefore credited. Only on these items. A student may write both conditionals, or a single two-way statement, or say that the two sides stand or fall together. Do not credit an exclusive either-or, which says something different.", "Wording is free. Judge the logical structure, not the phrasing."], "partial_rule": "Mark ''partial'' when the student produces a well-formed conditional but reverses sufficiency and necessity, drops a negation, or trims a compound or contrasting condition down to one part. Mark ''incorrect'' when the response is not a conditional at all, or states a relationship the statement does not support."}, "tagline": "Find the trigger word, and it tells you which side is which.", "task": "Rephrase the statement as If [sufficient], then [necessary], in your own words. The contrapositive counts too, since it says the same thing.", "rules": ["Some words introduce the sufficient condition and some introduce the necessary one. That is the whole game.", "If, when, whenever, every, all, the only: these mark the sufficient side, the trigger.", "Only if, only when, unless, without, requires, depends on, must: these mark the necessary side, what is required.", "A necessary condition is required but never a guarantee. It can be met and the thing still not happen.", "Unless, until and without all mean the same thing. Read them as if not, or ask yourself what is being required and put that on the then side.", "With no and none, the negation belongs to the second half. No X does Y becomes: if it is an X, then it does not do Y.", "Contrapositive: negate both sides and swap them.", "When you contrapose a compound, and becomes or, and or becomes and. If a thing needs both X and Y, then losing either one alone is enough to sink it.", "Two moves are always wrong. Running the arrow backwards, and deciding that because the trigger did not fire the outcome cannot happen.", "If and only if, then and only then, and otherwise all make the arrow run both ways. There the reverse direction is fair game."], "worked_example": {"statement": "You can''t master the LSAT without mastering conditional reasoning.", "credited_answers": ["If you master the LSAT, then you master conditional reasoning.", "If you don''t master conditional reasoning, you won''t master the LSAT."], "explanation": "Without marks the necessary condition, so mastering conditional reasoning goes on the then side. Both forms above are credited: the second is just the contrapositive of the first."}, "answer_label": "Your rephrase", "answer_placeholder": "Write it as If [sufficient], then [necessary]…", "credited_secondary_label": "Contrapositive"}'::jsonb,
    'free-text',
    '[{"order": 1, "prompt": "Whenever the greenhouse fans run overnight, the orchids bloom by morning.", "credited_answers": ["If the fans run overnight, then the orchids bloom by morning.", "If the orchids did not bloom by morning, then the fans did not run overnight."], "explanation": "\"Whenever\" (sufficient). \"Whenever,\" like \"every\" and \"all,\" marks the sufficient side.", "category": "Trigger word: whenever"}, {"order": 2, "prompt": "The drawbridge is raised only if a tall ship signals the operator.", "credited_answers": ["If the drawbridge is raised, then a tall ship signaled the operator.", "If no tall ship signaled, then the drawbridge is not raised."], "explanation": "\"Only if\" (necessary). The classic; signaling does not guarantee raising.", "category": "Requirement word: only if"}, {"order": 3, "prompt": "When the kiln reaches firing temperature, the glaze sets within the hour.", "credited_answers": ["If the kiln reaches firing temperature, then the glaze sets within the hour.", "If the glaze did not set within the hour, the kiln did not reach temperature."], "explanation": "\"When\" (sufficient). \"When\" reads like time but works like \"if.\"", "category": "Trigger word: when"}, {"order": 4, "prompt": "The vault opens only when two floor managers are present.", "credited_answers": ["If the vault opens, then two floor managers are present.", "If two managers are not present, the vault does not open."], "explanation": "\"Only when\" (necessary). Twin of \"only if.\"", "category": "Requirement word: only when"}, {"order": 5, "prompt": "The choir performs outdoors if the evening stays dry.", "credited_answers": ["If the evening stays dry, then the choir performs outdoors.", "If the choir does not perform outdoors, the evening did not stay dry."], "explanation": "Mid-sentence \"if\" (sufficient). Outcome stated first; the if-clause still marks the trigger.", "category": "Trigger word: if"}, {"order": 6, "prompt": "Every manuscript accepted by the quarterly is read by two editors.", "credited_answers": ["If a manuscript is accepted by the quarterly, then it is read by two editors.", "If a manuscript was not read by two editors, then it was not accepted."], "explanation": "\"Every\" (sufficient). The noun phrase \"every…accepted\" goes whole into the if-clause.", "category": "Trigger word: every"}, {"order": 7, "prompt": "As long as the yeast stays refrigerated, the starter keeps its rise.", "credited_answers": ["If the yeast stays refrigerated, then the starter keeps its rise.", "Lost its rise, it was not kept cold."], "explanation": "\"As long as\" (sufficient). Duration framing of \"if.\"", "category": "Trigger word: as long as"}, {"order": 8, "prompt": "All entries that win the pastry competition use seasonal fruit.", "credited_answers": ["If an entry wins, then it uses seasonal fruit.", "If an entry does not use seasonal fruit, it does not win."], "explanation": "\"All\" (sufficient). Reversal bait: using seasonal fruit guarantees nothing.", "category": "Trigger word: all"}, {"order": 9, "prompt": "The loan converts to a grant provided that the clinic stays open five years.", "credited_answers": ["If the clinic stays open five years, then the loan converts.", "No conversion, it did not stay open."], "explanation": "\"Provided that\" (sufficient).", "category": "Trigger word: provided that"}, {"order": 10, "prompt": "Visiting scholars must clear the manuscript room''s ultraviolet screening.", "credited_answers": ["If someone works in the manuscript room as a visiting scholar, then they cleared the screening.", "Not cleared, not admitted."], "explanation": "\"Must\" (necessary). Requirement language: must marks what is required, never what suffices.", "category": "Requirement word: must"}, {"order": 11, "prompt": "The relay team advances only with a clean baton exchange.", "credited_answers": ["If the team advances, then the exchange was clean.", "If the exchange was not clean, the team does not advance."], "explanation": "\"Only with\" (necessary). \"Only\" attaching to a phrase, not a clause.", "category": "Requirement word: only with"}, {"order": 12, "prompt": "Certification as a master falconer requires five seasons of supervised apprenticeship.", "credited_answers": ["If someone is certified, then they completed five seasons.", "No five seasons, no certification."], "explanation": "\"Requires\" (necessary verb). First of the verb indicators: no \"if\" anywhere.", "category": "Requirement word: requires"}, {"order": 13, "prompt": "The painting travels on the condition that the borrower installs seismic mounts.", "credited_answers": ["If the painting travels, then the mounts are installed.", "No mounts, no travel."], "explanation": "\"On the condition that\" (NECESSARY). The trio''s discrimination: provided-that and as-long-as mark the sufficient side; on-the-condition-that states a requirement.", "category": "Requirement word: on the condition that"}, {"order": 14, "prompt": "Whether the observatory renews the comet survey depends on funding from the maritime trust.", "credited_answers": ["If the survey is renewed, then the trust funded it.", "No funding, no renewal."], "explanation": "\"Depends on\" (necessary verb). Funding permits renewal; it does not guarantee it.", "category": "Requirement word: depends on"}, {"order": 15, "prompt": "The only way to reach the fire lookout before noon is the switchback trail.", "credited_answers": ["If you reach the lookout before noon, then you took the switchback trail.", "Not the switchback, not before noon."], "explanation": "\"The only way\" (necessary). Cousin of \"the only,\" pointing the other direction: here the described thing is the requirement.", "category": "Requirement word: the only way"}, {"order": 16, "prompt": "A stable magnetic bearing is essential to calibrating the drone''s compass.", "credited_answers": ["If the compass is calibrated, then the bearing was stable.", "Unstable bearing, no calibration."], "explanation": "\"Essential to\" (necessary). Adjective form of the same move.", "category": "Requirement word: essential to"}, {"order": 17, "prompt": "In order to bottle under the heritage label, a cidery has to press fruit from registered orchards.", "credited_answers": ["If a cidery bottles under the label, then it pressed registered fruit.", "No registered fruit, no label."], "explanation": "\"In order to\" (the goal side is sufficient; the stated requirement is necessary). Purpose framing.", "category": "Requirement word: in order to"}, {"order": 18, "prompt": "Unless the generator is refueled by dusk, the beacon goes dark.", "credited_answers": ["If the generator is not refueled by dusk, then the beacon goes dark.", "If the beacon did not go dark, the generator was refueled by dusk."], "explanation": "\"Unless\" (= if not). The workhorse translation: unless = if not.", "category": "Negative requirement: unless"}, {"order": 19, "prompt": "The orchestra tours in the spring unless the hall renovation runs late.", "credited_answers": ["If the renovation does not run late, then the orchestra tours in the spring.", "If the orchestra does not tour, the renovation ran late."], "explanation": "\"Unless\" trailing. The same rule as the item before it, with the clauses swapped on the page.", "category": "Negative requirement: unless"}, {"order": 20, "prompt": "Without a permit, no vendor may sell at the night market.", "credited_answers": ["If a vendor sells at the night market, then the vendor has a permit.", "If a vendor has no permit, the vendor may not sell."], "explanation": "\"Without\" (necessary). Double negative resolves cleanly.", "category": "Negative requirement: without"}, {"order": 21, "prompt": "Without the harbormaster''s stamp, no manifest clears customs.", "credited_answers": ["If a manifest clears customs, then it carries the harbormaster''s stamp.", "If a manifest does not carry the harbormaster''s stamp, then it does not clear customs."], "explanation": "\"Without\" (necessary). One rule, two seats; drilled as a single item pair, and the translation is identical from either seat. Seat: initial. Same rule in final position: \"No manifest clears customs without the harbormaster''s stamp.\"", "category": "Negative requirement: without"}, {"order": 22, "prompt": "File the appeal by Thursday, or else the ruling becomes final.", "credited_answers": ["If the appeal is not filed by Thursday, then the ruling becomes final.", "If the ruling did not become final, the appeal was filed in time."], "explanation": "\"Or else\" (= if not). Commands hide conditionals.", "category": "Negative requirement: or else"}, {"order": 23, "prompt": "The reef pumps must cycle nightly; otherwise the tank crashes.", "credited_answers": ["If the pumps do not cycle nightly, then the tank crashes.", "Tank fine, pumps cycled."], "explanation": "\"Otherwise\" (= if not). Sibling of \"or else\" across a semicolon.", "category": "Negative requirement: otherwise"}, {"order": 24, "prompt": "A climber cannot attempt the summit without registering at the base station.", "credited_answers": ["If a climber attempts the summit, then the climber registered at the base station.", "If a climber did not register, the climber cannot attempt the summit."], "explanation": "\"Cannot…without\" (necessary). The reference-statement form.", "category": "Negative requirement: cannot … without"}, {"order": 25, "prompt": "No thesis passes the review board without an outside reader''s signature.", "credited_answers": ["If a thesis passes, then an outside reader signed.", "No signature, no pass."], "explanation": "\"No…without\" (necessary). Signature is required, not sufficient; the board can still reject.", "category": "Negative requirement: no … without"}, {"order": 26, "prompt": "The curing shed stays sealed until the humidity gauge reads forty percent.", "credited_answers": ["If the gauge has not read forty percent, then the shed stays sealed.", "If the shed is unsealed, the gauge read forty percent."], "explanation": "\"Until\" (the unlock condition is necessary for the change). The state persists as long as the condition is unmet.", "category": "Negative requirement: until"}, {"order": 27, "prompt": "The museum does not deaccession a painting unless the donor''s estate consents.", "credited_answers": ["If the museum deaccessions a painting, then the estate consented.", "If the estate did not consent, the museum does not deaccession."], "explanation": "\"Not…unless\" (necessary). Negative main clause + unless: the pair students scramble most.", "category": "Negative requirement: not … unless"}, {"order": 28, "prompt": "Not until the auditor countersigns the ledger does the treasury release quarterly funds.", "credited_answers": ["If funds are released, then the auditor countersigned.", "No countersignature, no release."], "explanation": "\"Not until,\" sentence-initial with inverted syntax. Twin of \"only when\" in disguise.", "category": "Negative requirement: not until"}, {"order": 29, "prompt": "Absent a unanimous vote, the bylaws stay unchanged.", "credited_answers": ["If the vote is not unanimous, then the bylaws stay unchanged.", "If the bylaws changed, the vote was unanimous."], "explanation": "\"Absent\" (= without). New synonym for the family; one word carrying the whole structure.", "category": "Negative requirement: absent"}, {"order": 30, "prompt": "None of the trails above the ridge line are open in March.", "credited_answers": ["If a trail is above the ridge line, then it is not open in March.", "If a trail is open in March, it is not above the ridge line."], "explanation": "\"None\" (sufficient subject, negated result). The subject is the trigger; what follows it is denied.", "category": "Negated result: none"}, {"order": 31, "prompt": "Snow leopards never abandon a den before the cubs can climb.", "credited_answers": ["If the cubs cannot yet climb, then the den is not abandoned.", "If a den is abandoned, the cubs can climb."], "explanation": "\"Never\" (universal negative). \"Never\" builds a conditional with a negated result.", "category": "Negated result: never"}, {"order": 32, "prompt": "The registrar never certifies a transcript that lacks the dean''s seal.", "credited_answers": ["If a transcript is certified, then it carries the dean''s seal.", "No seal, no certification."], "explanation": "\"Never,\" mid-sentence. The negative universal quietly marks the subject as sufficient.", "category": "Negated result: never"}, {"order": 33, "prompt": "A kite cannot hold altitude in dead air.", "credited_answers": ["If the air is dead, then a kite does not hold altitude.", "If a kite holds altitude, the air is not dead."], "explanation": "\"Cannot\" (impossibility). Impossibility statements are conditionals wearing a flat disguise.", "category": "Negated result: cannot"}, {"order": 34, "prompt": "Sealed bids cannot be amended after the auction gavel falls.", "credited_answers": ["If the gavel has fallen, then bids cannot be amended.", "If a bid was amended, the gavel had not fallen."], "explanation": "\"Cannot,\" sentence-final condition. The time clause is the sufficient side.", "category": "Negated result: cannot"}, {"order": 35, "prompt": "Except during festival week, the archive reading room stays locked.", "credited_answers": ["If it is not festival week, then the reading room is locked.", "If the reading room is unlocked, it is festival week."], "explanation": "\"Except\" (exception = the only escape). Exception-first order; the exception is not a guarantee of unlocking.", "category": "Negative requirement: except"}, {"order": 36, "prompt": "Except where the levee has been reinforced, the river road closes during spring melt.", "credited_answers": ["If the levee has not been reinforced, then the road closes during spring melt.", "If the road stays open, the levee was reinforced."], "explanation": "\"Except where\" (necessary). Exception-first; reinforcement permits an open road, it never guarantees one.", "category": "Negative requirement: except where"}, {"order": 37, "prompt": "No one boards the research vessel unless the harbor physician signs their medical card.", "credited_answers": ["If someone boards, then the physician signed their card.", "No signature, no boarding."], "explanation": "\"No one…unless.\" Two negatives and an unless resolving into one clean rule.", "category": "Negative requirement: no one … unless"}, {"order": 38, "prompt": "The only candles sold at the apiary are poured from the hive''s own wax.", "credited_answers": ["If a candle is sold at the apiary, then it is poured from the hive''s wax.", "Not hive wax, not sold there."], "explanation": "\"The only\" (SUFFICIENT: the described thing goes in the if-clause). The look-alike that flips sides; the next item is its opposite number.", "category": "Look-alike pair: the only"}, {"order": 39, "prompt": "Only cellists who audition in person join the chamber ensemble.", "credited_answers": ["If a musician joins the ensemble, then that musician is a cellist who auditioned in person.", "No in-person audition, no seat."], "explanation": "\"Only\" (necessary). The pair with the item before it: one word of difference, opposite structure.", "category": "Look-alike pair: only"}, {"order": 40, "prompt": "The saplings recover if only the deer fencing goes up before bud break.", "credited_answers": ["If the fencing goes up before bud break, then the saplings recover.", "If the saplings did not recover, the fencing did not go up in time."], "explanation": "\"If only\" (SUFFICIENT). The discrimination pair with \"only if\": in \"only if,\" the only governs the if (necessary); in \"if only,\" the if still marks the sufficient side and \"only\" just says the requirement is small. One word order, opposite structure.", "category": "Look-alike pair: if only"}, {"order": 41, "prompt": "A perfect score on the final audition guarantees a seat in the touring company.", "credited_answers": ["If the audition score is perfect, then a seat is guaranteed.", "No seat, the score was not perfect."], "explanation": "\"Guarantees\" (SUFFICIENT verb). The counterweight: some verbs mark the sufficient side. Requires and guarantees point opposite ways, and that is the whole discrimination.", "category": "Trigger word: guarantees"}, {"order": 42, "prompt": "Restoring the fresco''s cobalt border demands pigment ground from the original quarry.", "credited_answers": ["If the border is restored, then quarry-ground pigment was used.", "No quarry pigment, no restoration."], "explanation": "\"Demands\" (necessary verb). Verb lexicon depth.", "category": "Requirement word: demands"}, {"order": 43, "prompt": "Sealing the ferment under an airlock ensures the batch survives the summer heat.", "credited_answers": ["If the ferment is sealed under an airlock, then the batch survives.", "Batch spoiled, it was not sealed."], "explanation": "\"Ensures\" (sufficient verb). Sibling of \"guarantees\".", "category": "Trigger word: ensures"}, {"order": 44, "prompt": "Entering the archive''s cold vault necessitates logging the visit with the conservator on duty.", "credited_answers": ["If someone enters the vault, then the visit was logged.", "Not logged, no entry."], "explanation": "\"Necessitates\" (necessary verb). The indicator sits mid-sentence and there is no \"if\" anywhere.", "category": "Requirement word: necessitates"}, {"order": 45, "prompt": "Dating the shipwreck to the spice trade presupposes that the hull timber was felled after the monsoon routes opened.", "credited_answers": ["If the wreck is dated to the spice trade, then the timber was felled after the routes opened.", "Felled earlier, not so dated."], "explanation": "\"Presupposes\" (necessary verb). To make the claim at all, you are already committed to the timber.", "category": "Requirement word: presupposes"}, {"order": 46, "prompt": "The festival committee will not book both the brass band and the string quartet.", "credited_answers": ["If the brass band is booked, then the string quartet is not.", "If the string quartet is booked, then the brass band is not."], "explanation": "\"Not both\" (A → not B). Not-both allows neither; it only forbids the pair.", "category": "Not both"}, {"order": 47, "prompt": "A juror may review the exhibit log or the testimony transcripts overnight, but not both.", "credited_answers": ["If a juror reviews the exhibit log overnight, then the juror does not review the testimony transcripts.", "If a juror reviews the testimony transcripts, then the juror does not review the exhibit log."], "explanation": "\"But not both,\" sentence-final. The or-with-a-cap construction. Here the contrapositive and the converse coincide, which is what \"not both\" means: each one rules out the other. \"Or\" still permits either alone, and permits neither.", "category": "Not both"}, {"order": 48, "prompt": "The observatory grants dark-sky certification if and only if every fixture in the district is fully shielded.", "credited_answers": ["If a district is granted dark-sky certification, then every fixture in it is fully shielded.", "If any fixture in the district is not fully shielded, then the district is not granted certification."], "explanation": "\"If and only if\" (biconditional). The one construction where both sides are both sufficient and necessary, so the converse is credited too: if every fixture is fully shielded, then the district is granted certification.", "category": "Both ways: if and only if"}, {"order": 49, "prompt": "The senate ratifies the water compact only if every border county holds a public hearing.", "credited_answers": ["If the senate ratifies the water compact, then every border county holds a public hearing.", "If some border county does not hold a public hearing, then the senate does not ratify the compact."], "explanation": "\"Only if\" (necessary), final seat. The textbook seat. Seat: final.", "category": "Same rule, new seat: only if"}, {"order": 50, "prompt": "Only if every border county holds a public hearing does the senate ratify the water compact.", "credited_answers": ["If the senate ratifies the water compact, then every border county holds a public hearing.", "If some border county does not hold a public hearing, then the senate does not ratify the compact."], "explanation": "\"Only if\" (necessary), initial seat, inverted. Identical to the previous item. Fronting changes emphasis, never structure; the inversion (\"does the senate…\") is the disguise. Seat: initial, inverted.", "category": "Same rule, new seat: only if"}, {"order": 51, "prompt": "Ratification of the compact, which the senate grants only if every border county has held a hearing, remains stalled this term.", "credited_answers": ["If the senate grants ratification of the compact, then every border county has held a hearing.", "If some border county has not held a hearing, then the senate does not grant ratification."], "explanation": "\"Only if\" (necessary), mid-sentence, embedded. Same rule as the previous two, buried in a relative clause inside a sentence about something else. Extraction under load. Seat: mid, embedded.", "category": "Same rule, new seat: only if"}, {"order": 52, "prompt": "Unless the dye bath holds at a simmer, the wool takes the color unevenly.", "credited_answers": ["If the dye bath does not hold at a simmer, then the wool takes the color unevenly.", "If the wool takes the color evenly, then the dye bath held at a simmer."], "explanation": "\"Unless\" (= if not), initial seat. The base case for the three seats below it. Seat: initial.", "category": "Same rule, new seat: unless"}, {"order": 53, "prompt": "The wool takes the color unevenly unless the dye bath holds at a simmer.", "credited_answers": ["If the dye bath does not hold at a simmer, then the wool takes the color unevenly.", "If the wool takes the color evenly, then the dye bath held at a simmer."], "explanation": "\"Unless\" (= if not), final seat. Identical translation to the previous item; only the clause order on the page has flipped. Seat: final.", "category": "Same rule, new seat: unless"}, {"order": 54, "prompt": "Every batch this season, unless the dye bath held at a simmer throughout, has come out mottled.", "credited_answers": ["If the dye bath did not hold at a simmer throughout, then the batch came out mottled.", "If a batch did not come out mottled, then the dye bath held at a simmer throughout."], "explanation": "\"Unless\" (= if not), mid-sentence, embedded. Same rule inside an interrupting clause. The eye must reassemble the split main clause. Seat: mid, embedded.", "category": "Same rule, new seat: unless"}, {"order": 55, "prompt": "Only when the reef survey records juvenile parrotfish at three consecutive stations does the marine reserve loosen its no-anchor rule.", "credited_answers": ["If the reserve loosens the rule, then the survey recorded juveniles at three consecutive stations.", "No three-station record, no loosening."], "explanation": "\"Only when\" + inverted syntax. The inversion (\"does the reserve…\") hides which clause is the outcome.", "category": "Same rule, new seat: only when"}, {"order": 56, "prompt": "Except where the surveyor has verified both the boundary markers and the floodplain easement, the records office will not transfer the deed.", "credited_answers": ["If the deed is transferred, then both the markers and the easement were verified.", "If either was unverified, no transfer."], "explanation": "\"Except where\" + compound. Both conjuncts must survive; \"either unverified\" is the contrapositive''s hinge.", "category": "Compound condition: except where"}, {"order": 57, "prompt": "The only expeditions cleared for the ice shelf carry redundant beacons and a certified glacier medic.", "credited_answers": ["If an expedition is cleared, then it carries both.", "Missing either, not cleared."], "explanation": "\"The only\" + compound. The side-flipping look-alike, now carrying two conditions at once.", "category": "Compound condition: the only"}, {"order": 58, "prompt": "No restoration receives the guild''s seal without both a reversible adhesive and a documented provenance chain.", "credited_answers": ["If a restoration receives the seal, then it used a reversible adhesive and has a provenance chain.", "Lacking either, no seal."], "explanation": "\"No…without\" + compound. Both requirements have to survive into the if-then; dropping one is a partial.", "category": "Compound condition: no … without"}, {"order": 59, "prompt": "Unless the tasting panel finds no trace of cork taint, the vintage is not released under the estate label.", "credited_answers": ["If the vintage is released under the estate label, then the panel found no trace of taint.", "If any taint was found, no estate release."], "explanation": "\"Unless\" + embedded negative. Three negatives thread into one clean pair.", "category": "Stacked negatives: unless"}, {"order": 60, "prompt": "Classifying the manuscript hand as professional necessitates matching its letterforms to guild exemplars rather than to household copybooks.", "credited_answers": ["If the hand is classified as professional, then its letterforms match guild exemplars rather than household copybooks.", "If they do not match guild exemplars rather than copybooks, not classified professional."], "explanation": "\"Necessitates\" + internal contrast. The \"rather than\" clause is part of the condition; trimming it is a partial.", "category": "Contrast inside the condition"}, {"order": 61, "prompt": "Attributing the seismic swarm to hydrothermal circulation presupposes that the tremor spectra lack the impulsive onsets characteristic of tectonic slip.", "credited_answers": ["If the swarm is attributed to hydrothermal circulation, then the spectra lack impulsive onsets.", "Impulsive onsets present, no such attribution."], "explanation": "\"Presupposes\" under jargon. The structure is three words long; everything else is noise to see through.", "category": "Requirement word under jargon: presupposes"}, {"order": 62, "prompt": "A confirmed match in the pollen record guarantees a spring dating for the flood layer, but only a sealed stratum makes the match itself trustworthy.", "credited_answers": ["If the pollen match is confirmed (and trustworthy), then the flood layer dates to spring; and if the match is trustworthy, then the stratum was sealed.", "Chained the other way: if the stratum was not sealed, the match is not trustworthy; and with no trustworthy match, no confirmed spring dating."], "explanation": "\"Guarantees\" + \"only.\" Two conditionals in one sentence, and the hardest item here. Chain them rather than picking one.", "category": "Two conditionals in one sentence"}]'::jsonb,
    NULL,
    NULL,
    NULL
  ),
  (
    'find-the-conclusion',
    'Find the Conclusion',
    'Name the claim the argument is trying to prove',
    '{"coach": {"drill": "a main-conclusion identification drill: the student reads an argument and names the claim the author is trying to prove", "rubric": ["The credited answer is the argument''s main conclusion. Accept any accurate paraphrase as readily as a direct quote; students are told to answer in their own words.", "Apply the 2-Point Check: a conclusion sounds like the author''s opinion (facts are not conclusions) and is supported by at least one other explicit claim in the argument.", "The conclusion is usually NOT the last sentence. Do not reward a response just because it quotes the closing line.", "If the argument''s stated conclusion uses referential language (this position, such a rule, they are wrong), a response that writes the reference back in is correct, and one that leaves the pronoun unresolved is at best partial."], "partial_rule": "Mark ''partial'' when the student names an INTERMEDIATE conclusion (a claim that is supported but is itself there to support the main one), or names the right claim but drops a qualifier that changes its scope or strength (an ''even if'', a comparison, a time limit). Mark ''incorrect'' when they give a premise, the opposing view the author is arguing against, background framing, or a claim the author would agree with but never argues for."}, "tagline": "The conclusion is rarely the last thing you read.", "task": "Read the argument and tell me, in your own words or as a direct quote, the main conclusion. Then I will tell you what I see.", "rules": ["Run the 2-Point Check on any claim you are considering. Does it sound like the author''s opinion? Facts are not conclusions. And is it supported by at least one other claim in the argument?", "More than nine times out of ten the conclusion comes before its support. Look at the first sentence, and look at the claim right after a But, Yet, or However.", "FABS marks evidence: for, after all, because, since. Whatever follows one of those is support, so the claim in front of it is usually the point.", "If the conclusion is a pronoun sentence (this position, such a rule, they are wrong), write the reference back in before you say it.", "Point at your candidate and ask, why should we believe that? If the rest of the argument answers you, you have found it."], "worked_example": {"statement": "Some critics say the reading room should stay open past midnight. But the security desk closes at eleven, and an unstaffed room with open stacks is how the last three thefts happened. Extended hours are not worth the risk to the collection.", "credited_answers": ["Extended hours are not worth the risk to the collection."], "explanation": "The attribution comes first, the pivot at But turns to the author, and the last sentence is the claim the theft history is there to support. The critics'' proposal is somebody else''s view, and the thefts are evidence."}, "answer_label": "Your conclusion", "answer_placeholder": "Name the claim the argument is trying to prove…"}'::jsonb,
    'free-text',
    '[{"order": 1, "prompt": "The city''s bike-share docks sit full every weekday morning. Ridership logs show almost no trips beginning before ten. Therefore the program''s early-commuter goal has not been met.", "credited_answers": ["The program''s early-commuter goal has not been met."], "explanation": "Wrong turn: \"Almost no trips begin before ten\" (premise). \"Therefore,\" final seat. Baseline. Note: the clean case, so the student can feel the shape before it gets hidden.", "category": "Level 1: Basic conclusion indicator"}, {"order": 2, "prompt": "So the archive should digitize the glass negatives before the paper files. The negatives are deteriorating faster and a single loss is unrecoverable, while the paper files are stable in current storage.", "credited_answers": ["The archive should digitize the glass negatives before the paper files."], "explanation": "Wrong turn: \"The negatives are deteriorating faster\" (premise). \"So\" opening plus \"should,\" initial seat. Baseline. Note: a conclusion indicator can open an argument. Position is not the tell; support is.", "category": "Level 1: Basic conclusion indicator"}, {"order": 3, "prompt": "Attendance at the lunchtime lecture series has fallen for six straight terms. The room runs half empty even for invited speakers. It follows that the series in its current form no longer earns the room booking.", "credited_answers": ["The series in its current form no longer earns the room booking."], "explanation": "Wrong turn: the attendance fact. \"It follows that,\" final seat. Baseline.", "category": "Level 1: Basic conclusion indicator"}, {"order": 4, "prompt": "Consequently the co-op should stock the smaller flour sacks. Members living alone report throwing out spoiled flour, and the twenty-pound sack is the only size on the shelf.", "credited_answers": ["The co-op should stock the smaller flour sacks."], "explanation": "Wrong turn: \"the twenty-pound sack is the only size\" (premise). \"Consequently\" opening. Baseline.", "category": "Level 1: Basic conclusion indicator"}, {"order": 5, "prompt": "Hospital records show the revised triage script cut average wait time by eleven minutes. Complaints about waiting dropped over the same period. Thus the script is doing what it was written to do.", "credited_answers": ["The script is doing what it was written to do."], "explanation": "Wrong turn: the eleven-minute figure. \"Thus,\" final seat. Baseline.", "category": "Level 1: Basic conclusion indicator"}, {"order": 6, "prompt": "This shows that the vineyard''s frost fans are earning their cost. Rows inside the fan radius lost four percent of buds in the April freeze. Unprotected rows lost nineteen.", "credited_answers": ["The frost fans are earning their cost."], "explanation": "Wrong turn: either bud-loss figure. \"This shows that,\" initial seat. Baseline. Note: \"This shows that\" usually marks an intermediate conclusion at Level 4. Here it marks the main one. The phrase is a clue, never a verdict.", "category": "Level 1: Basic conclusion indicator"}, {"order": 7, "prompt": "The translation committee has met eleven times without producing a chapter. Two members have not attended since spring. As a result the committee cannot deliver the manuscript on the promised schedule.", "credited_answers": ["The committee cannot deliver the manuscript on the promised schedule."], "explanation": "Wrong turn: the attendance fact. \"As a result,\" final seat. Baseline.", "category": "Level 1: Basic conclusion indicator"}, {"order": 8, "prompt": "Hence the museum''s audio guide needs rewriting. Visitors surveyed at the exit could not recall a single fact from it, and the guide has not been revised since the collection was rehung.", "credited_answers": ["The audio guide needs rewriting."], "explanation": "Wrong turn: the survey result. \"Hence,\" initial seat. Baseline.", "category": "Level 1: Basic conclusion indicator"}, {"order": 9, "prompt": "Every trailhead sign in the park was replaced last season. Rangers report a sharp drop in calls from lost hikers. We can conclude that the new signs are doing their job.", "credited_answers": ["The new signs are doing their job."], "explanation": "Wrong turn: the drop in calls. \"We can conclude,\" final seat. Baseline.", "category": "Level 1: Basic conclusion indicator"}, {"order": 10, "prompt": "The press should keep the hardcover in print. Libraries continue to order it, the paperback has not displaced those orders, and the plates are already paid for. So the print run should be renewed on the current schedule.", "credited_answers": ["The press should keep the hardcover in print."], "explanation": "Near miss (partial): \"the print run should be renewed on the current schedule\" (the closing sentence restates the opening claim; crediting it is acceptable, but a student who picks it because it carries \"So\" has used the wrong reason). Wrong turn: \"the plates are already paid for.\" \"So,\" final seat, with the real claim opening. Trait 1 preview. Note: first sighting of the Last Claim Trap in a friendly setting.", "category": "Level 1: Basic conclusion indicator"}, {"order": 11, "prompt": "The apprenticeship should be extended to a second year. After all, first-year apprentices still need supervision on every complex repair, and the shop cannot bill their hours at full rate.", "credited_answers": ["The apprenticeship should be extended to a second year."], "explanation": "Wrong turn: either supervision or billing fact. \"After all,\" support. Trait 3. Note: \"After all\" is the purest FABS marker. Nothing after it is ever the conclusion.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 12, "prompt": "The lab''s freezer alarm is inadequate, since it pages one technician and gives no second alert if that page goes unanswered.", "credited_answers": ["The freezer alarm is inadequate."], "explanation": "Wrong turn: the paging description. \"Since,\" support. Trait 3.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 13, "prompt": "The island grocery now runs short by Thursday because the ferry schedule was cut to two crossings. The store cannot restock between crossings, and Thursday is when weekend demand begins.", "credited_answers": ["The grocery runs short by Thursday because the ferry schedule was cut."], "explanation": "Near miss (partial): \"the grocery runs short by Thursday\" with the cause dropped (scope loss: the claim is causal). Wrong turn: \"the store cannot restock between crossings.\" \"Because,\" support. Trait 4. Note: when the conclusion is causal, an answer that keeps only the effect is a scope drop.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 14, "prompt": "Reviewers should be paid for their time. For the journal now waits five months on average for a report, and unpaid work is the first thing a busy academic drops.", "credited_answers": ["Reviewers should be paid for their time."], "explanation": "Wrong turn: the five-month figure. \"For,\" support. Trait 3. Note: sentence-initial \"For\" reads as archaic to students and gets misread as a preposition. Worth one Coach line.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 15, "prompt": "The removable resin is the better choice for this restoration, since it comes off with a solvent that does not touch the original pigment.", "credited_answers": ["The removable resin is the better choice for this restoration."], "explanation": "Near miss (partial): \"the resin is the better choice\" with \"for this restoration\" dropped. \"Since,\" support. Trait 4.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 16, "prompt": "Digitizing the oral histories is more urgent than cataloguing them, because the tapes shed oxide with every playback while the catalogue can be built from a digital copy at any time.", "credited_answers": ["Digitizing is more urgent than cataloguing."], "explanation": "Near miss (partial): \"digitizing is urgent\" (drops the comparison, which is the whole claim). \"Because,\" support. Trait 4. Note: comparative conclusions lose their meaning the moment the comparison is trimmed.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 17, "prompt": "The second bakery will not break even this year. After all, it opened in March, its lease is nearly double the original shop''s, and the neighborhood empties out in summer.", "credited_answers": ["The second bakery will not break even this year."], "explanation": "Wrong turn: the lease fact. \"After all,\" support. Trait 5. Note: an answer saying the second location was a mistake is agreeable and not the claim.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 18, "prompt": "The council''s parking study is unreliable, for the counts were taken during the two weeks the arena was closed for repairs.", "credited_answers": ["The parking study is unreliable."], "explanation": "Wrong turn: the closure fact. \"For,\" support. Trait 3.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 19, "prompt": "Students learn the citation rules faster by marking up a flawed bibliography than by reading the style guide, since correcting an error forces them to name the rule it breaks.", "credited_answers": ["The comparative claim about the two methods."], "explanation": "Near miss (partial): \"marking up a flawed bibliography teaches citation rules\" (comparison dropped). \"Since,\" support. Trait 4.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 20, "prompt": "The orchard should replace its older pollinator hives this winter, because a fifth-season hive produces roughly half the foraging activity of a second-season hive, and the bloom window is too short to make up the difference.", "credited_answers": ["The orchard should replace its older hives this winter."], "explanation": "Near miss (partial): \"older hives forage less\" (that is the premise doing the work). \"Because,\" support. Trait 3.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 21, "prompt": "It is not worth resurfacing the north court this year. After all, the surface is worn but still playable, and the crew charges a premium before June.", "credited_answers": ["It is not worth resurfacing the north court this year."], "explanation": "Near miss (partial): \"the court does not need resurfacing\" (drops \"this year,\" which is the qualification carrying the claim). \"After all,\" support. Trait 4.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 22, "prompt": "The revised intake form is an improvement, since the field that most often went blank has been split into two shorter questions and now gets answered.", "credited_answers": ["The revised intake form is an improvement."], "explanation": "Wrong turn: the split-field description. \"Since,\" support. Trait 3.", "category": "Level 2: Conclusion before a support indicator (FABS)"}, {"order": 23, "prompt": "Some curators maintain that rotating the textiles every three months keeps any single piece from fading. But the handling is what damages the fibers. Each rotation means two mountings and two dismountings, and conservators have logged more thread loss from handling than from light.", "credited_answers": ["The handling is what damages the fibers."], "explanation": "Near miss (partial): the thread-loss comparison (support). Wrong turn: the curators'' rotation claim (opposing view). \"Some curators maintain\" attribution, \"But\" pivot. Trait 3.", "category": "Level 3: Pivot from an opposing view"}, {"order": 24, "prompt": "It is commonly believed that a longer warranty signals a more durable product. However, warranty length is set by the finance department, not by the engineers. Two of the company''s shortest-lived models carry its longest warranties.", "credited_answers": ["Warranty length is set by finance, not engineering (therefore it does not signal durability). Credit either the stated pivot claim or the unpacked version."], "explanation": "Wrong turn: the common belief. \"It''s commonly believed\" attribution, \"However\" pivot. Trait 3.", "category": "Level 3: Pivot from an opposing view"}, {"order": 25, "prompt": "Some economists argue that the vacancy tax will bring rents down. Yet the tax applies only to units empty more than a year, and the units driving the increase turn over every few months.", "credited_answers": ["The vacancy tax will not bring rents down (the pivot claim, unpacked)."], "explanation": "Near miss (partial): \"the tax applies only to units empty more than a year\" left as-is without drawing the point. Wrong turn: the economists'' claim. \"Yet\" pivot. Trait 2 blend. Note: the pivot sentence here is evidence for a conclusion the author leaves implicit. Flagged deliberately.", "category": "Level 3: Pivot from an opposing view"}, {"order": 26, "prompt": "Trainers often say the taper week before a race is optional for recreational runners. That advice is probably wrong. Recreational runners accumulate the same relative fatigue as competitive ones and have less recovery capacity to absorb it.", "credited_answers": ["(substituted): The taper week is not optional for recreational runners."], "explanation": "Near miss (partial): \"that advice is probably wrong\" left referential. Wrong turn: the trainers'' advice. \"Often say\" attribution, \"probably\" opinion indicator. Trait 3 plus referential substitution. Note: the explicit conclusion is a pronoun sentence. Write the reference back in.", "category": "Level 3: Pivot from an opposing view"}, {"order": 27, "prompt": "Several reviewers have written that the novel''s second half loses focus. But the shift they describe is the point. The narrator''s account fragments precisely as her memory does, and every apparent digression returns in the final chapter.", "credited_answers": ["The shift the reviewers describe is deliberate, not a loss of focus."], "explanation": "Near miss (partial): \"the digressions return in the final chapter\" (support). Wrong turn: the reviewers'' complaint. \"But\" pivot. Trait 3.", "category": "Level 3: Pivot from an opposing view"}, {"order": 28, "prompt": "The received view is that the fort was abandoned after the flood. However, the abandonment layer sits below the flood silt, not above it. Whatever emptied the fort happened first.", "credited_answers": ["Whatever emptied the fort happened before the flood."], "explanation": "Near miss (partial): the stratigraphy fact (this is the pivot sentence, and it is evidence). Wrong turn: the received view. \"However\" pivot carrying evidence, conclusion in the final seat. Trait 7 cousin. Note: designed counterexample. The pivot marks where the author turns, not always what the author concludes. Run the 2-Point Check.", "category": "Level 3: Pivot from an opposing view"}, {"order": 29, "prompt": "Many gardeners insist that autumn mulching protects perennials through winter. But mulch laid before the ground freezes keeps the soil warm enough for voles to tunnel, and vole damage costs more crowns than frost does.", "credited_answers": ["Autumn mulching does not protect perennials as claimed (the pivot claim, unpacked)."], "explanation": "Wrong turn: the gardeners'' claim. \"But\" pivot. Trait 2 blend.", "category": "Level 3: Pivot from an opposing view"}, {"order": 30, "prompt": "Administrators have claimed the new scheduling software saves staff time. It clearly does not. The software removed the paper roster but added a daily reconciliation step that takes longer than the roster ever did.", "credited_answers": ["(substituted): The new scheduling software does not save staff time."], "explanation": "Near miss (partial): \"it clearly does not\" left referential. Wrong turn: the administrators'' claim. \"Clearly\" opinion indicator. Trait 3 plus referential substitution.", "category": "Level 3: Pivot from an opposing view"}, {"order": 31, "prompt": "Some readers hold that footnotes interrupt a narrative history. Granted, a dense note can pull a reader out of a scene. Even so, a history without notes asks the reader to take every claim on trust, and that is the worse interruption.", "credited_answers": ["A history without notes is the worse interruption."], "explanation": "Near miss (partial): the concession (\"a dense note can pull a reader out of a scene\"). Wrong turn: the readers'' position. \"Granted\" concession, \"Even so\" pivot. Trait 5. Note: the concession is engineered to sound balanced and reasonable. It is not the point.", "category": "Level 3: Pivot from an opposing view"}, {"order": 32, "prompt": "Critics of the ferry subsidy say it benefits only weekend visitors. However, the ridership data separate residents from visitors, and residents account for two-thirds of subsidized trips. The subsidy is primarily a resident service.", "credited_answers": ["The subsidy is primarily a resident service."], "explanation": "Near miss (partial): the two-thirds figure. Wrong turn: the critics'' claim. \"However\" pivot carrying evidence, conclusion final. Trait 7 cousin. Note: second designed counterexample, paired with item 28.", "category": "Level 3: Pivot from an opposing view"}, {"order": 33, "prompt": "Prevailing opinion treats the anonymous letters as forgeries. Yet the paper stock matches the mill''s records for those years, and the watermark could not have been reproduced with period equipment. The letters are almost certainly genuine.", "credited_answers": ["The letters are almost certainly genuine."], "explanation": "Near miss (partial): \"the letters are genuine\" (drops \"almost certainly\"). Wrong turn: the prevailing opinion. \"Yet\" pivot, conclusion final with a hedge. Trait 4.", "category": "Level 3: Pivot from an opposing view"}, {"order": 34, "prompt": "Some argue the reading room should stay open past midnight. But the security desk closes at eleven, and an unstaffed room with open stacks is how the last three thefts happened. Extended hours are not worth the risk to the collection.", "credited_answers": ["Extended hours are not worth the risk to the collection."], "explanation": "Near miss (partial): the theft history. Wrong turn: the proposal being rejected. \"But\" pivot, conclusion final. Trait 5.", "category": "Level 3: Pivot from an opposing view"}, {"order": 35, "prompt": "It is often said that a small press cannot compete for prizes. This is not so. Three of the last five poetry awards went to presses with fewer than four employees.", "credited_answers": ["(substituted): A small press can compete for prizes."], "explanation": "Near miss (partial): \"this is not so\" left referential; also \"small presses win most poetry awards\" (overshoot). Wrong turn: the award statistic. \"It is often said\" attribution, bare referential rejection. Trait 4 plus substitution. Note: the closest item in this bank to Rebuttal Rephrase. Same anatomy, different task: here you name the conclusion, there you rewrite it.", "category": "Level 3: Pivot from an opposing view"}, {"order": 36, "prompt": "Some historians argue the guild records understate apprentice numbers. But the records were kept for tax purposes, and the tax fell on masters rather than apprentices, so the guild had no reason to undercount them.", "credited_answers": ["The guild had no reason to undercount apprentices."], "explanation": "Near miss (partial): \"the tax fell on masters\" (support). Wrong turn: the historians'' claim. \"But\" pivot plus \"so.\" Trait 3.", "category": "Level 3: Pivot from an opposing view"}, {"order": 37, "prompt": "The bindery''s new adhesive holds a text block through three thousand open-and-close cycles. The old adhesive failed at eight hundred. This shows the new adhesive is substantially more durable. Therefore the library should specify it for all rebinding going forward.", "credited_answers": ["The library should specify the new adhesive for all rebinding."], "explanation": "Near miss (partial): \"the new adhesive is substantially more durable\" (intermediate). Wrong turn: the cycle counts. \"This shows that\" then \"Therefore.\" Trait 7 baseline. Note: two indicators, two claims. The one that supports the other is the intermediate.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 38, "prompt": "Enrollment in the evening section has doubled while the morning section has shrunk. Thus students prefer the evening slot. The department should move the second lecture to the evening as well.", "credited_answers": ["The department should move the second lecture to the evening."], "explanation": "Near miss (partial): \"students prefer the evening slot\" (intermediate, and it carries the \"Thus\"). Wrong turn: the enrollment figures. Unmarked final conclusion. Trait 7.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 39, "prompt": "Every batch that failed inspection last quarter came from the same mixing line. That line has not been recalibrated since installation. So the calibration schedule, not the operators, explains the failures. The plant should recalibrate before assigning any retraining.", "credited_answers": ["The plant should recalibrate before assigning retraining."], "explanation": "Near miss (partial): \"the calibration schedule explains the failures\" (intermediate). Wrong turn: the same-line fact. \"So\" on the intermediate. Trait 7.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 40, "prompt": "Rooftop sensors record surface temperatures twenty degrees higher on tar roofs than on planted roofs. Planted roofs cost more to install but need no cooling equipment on the floors below. The city''s roof-replacement grant should favor planted roofs. Thus a building that switches will draw less power on the hottest afternoons of the year.", "credited_answers": ["The grant should favor planted roofs."], "explanation": "Near miss (partial): the closing \"Thus\" sentence (a downstream consequence, not the point). Wrong turn: the temperature reading. \"Thus\" in the final seat on a non-conclusion. Trait 7 inverted. Note: this is the trap his part 2 names outright. A mechanical reader takes the \"thus\" sentence every time.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 41, "prompt": "The new bus route carries three times the riders the planners forecast. This shows the forecast model underestimates demand on cross-town corridors. The agency should re-run its projections for the two remaining corridors before setting their schedules.", "credited_answers": ["The agency should re-run its projections before setting schedules."], "explanation": "Near miss (partial): \"the model underestimates cross-town demand\" (intermediate). \"This shows that.\" Trait 7.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 42, "prompt": "Wheat sown after the first hard frost germinated at less than half the rate of wheat sown two weeks earlier. Thus the planting window is narrower than the almanac suggests. Growers who wait for the almanac date are losing yield they could keep by sowing early.", "credited_answers": ["Growers who wait for the almanac date are losing yield."], "explanation": "Near miss (partial): \"the planting window is narrower than the almanac suggests\" (intermediate). \"Thus\" on the intermediate. Trait 7.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 43, "prompt": "Since the clinic began calling patients the day before an appointment, no-shows have fallen by a third. This demonstrates the reminder call works. The clinic should extend the calls to its satellite location, where the no-show rate is higher still.", "credited_answers": ["The clinic should extend the calls to the satellite location."], "explanation": "Near miss (partial): \"the reminder call works\" (intermediate). Wrong turn: the one-third figure. \"Since\" opening a premise, \"This demonstrates\" on the intermediate. Trait 7. Note: \"Since\" here is temporal, not FABS. Worth a Coach line.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 44, "prompt": "The recording made in the stone chapel has a reverberation tail nearly four seconds long. Thus the chapel is acoustically unsuitable for spoken word. The society should book the rehearsal hall for the audiobook sessions and keep the chapel for choral work.", "credited_answers": ["The society should book the rehearsal hall for audiobooks and keep the chapel for choral work."], "explanation": "Near miss (partial): \"the chapel is unsuitable for spoken word\" (intermediate); also the recommendation with only half its content (scope drop). Trait 4 plus Trait 7.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 45, "prompt": "Sea ice around the inlet breaks up eleven days earlier than it did thirty years ago. Seals rely on stable ice for pupping, and the pups are not weaned when the ice goes. The inlet''s seal population is unlikely to recover without a change in ice conditions. Thus the operators who advertise reliable seal sightings will disappoint their customers more often each year.", "credited_answers": ["The seal population is unlikely to recover without a change in ice conditions."], "explanation": "Near miss (partial): the closing \"Thus\" sentence (consequence). Wrong turn: the weaning fact. Trait 7 inverted.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 46, "prompt": "Applications rose the year the fee was waived and fell the year it returned. This suggests the fee, not the program''s reputation, drives application volume. The admissions office should treat the fee as a policy lever rather than a revenue line.", "credited_answers": ["The office should treat the fee as a policy lever rather than a revenue line."], "explanation": "Near miss (partial): \"the fee drives application volume\" (intermediate). Trait 7.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 47, "prompt": "Two independent labs dated the timber to within five years of each other. So the construction date is now well established. The gallery''s wall text, which still gives a range of two centuries, needs replacing.", "credited_answers": ["The wall text needs replacing."], "explanation": "Near miss (partial): \"the construction date is well established\" (intermediate). \"So\" on the intermediate. Trait 7.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 48, "prompt": "The pump station has failed twice during storms and never in dry weather. This points to the storm drain intake rather than the pump motor as the source. Replacing the motor a third time would not address the problem.", "credited_answers": ["Replacing the motor a third time would not address the problem."], "explanation": "Near miss (partial): \"the intake is the source\" (intermediate). Wrong turn: the failure pattern. Trait 7.", "category": "Level 4: Intermediate versus main conclusion"}, {"order": 49, "prompt": "The board''s decision to sell the water rights before commissioning a hydrology study was indefensible. The study would have taken four months. The buyer''s offer was open for a year. Nothing about the timeline required acting first and learning later.", "credited_answers": ["The decision to sell before commissioning the study was indefensible."], "explanation": "Near miss (partial): \"the board should have commissioned the study first\" (close, but drops the evaluative force the argument is defending). Wrong turn: the four-month figure. No indicator; evaluative word \"indefensible\" in the first seat. Trait 1 and Trait 4. Note: with no indicator anywhere, the evaluative word is the tell, and the last three sentences answer \"Why should we believe that?\"", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 50, "prompt": "The orchestra''s committee argues that screened auditions eliminate bias and that this alone settles the question. Screens do remove one kind of bias. But the repertoire list is set before the screen goes up, and that list favors the training available at a few conservatories. Even if the screen works exactly as intended, it cannot correct a bias that operates before anyone plays.", "credited_answers": ["Even if the screen works as intended, it cannot correct a bias operating before anyone plays."], "explanation": "Near miss (partial): \"screened auditions do not eliminate bias\" (drops the \"even if,\" which is the author''s careful concession). Wrong turn: \"screens do remove one kind of bias\" (concession) or the committee''s position. Outside party''s conclusion, author''s objection, qualified main conclusion. Trait 4 and Trait 5. Note: the hardest shape in his taxonomy. The qualification is not decoration; removing it makes a claim the author declined to make.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 51, "prompt": "No manuscript enters the conservation queue without a condition report. Condition reports are written only by staff conservators. Both staff conservators have been on leave since January, and no reports have been filed since.", "credited_answers": ["(derived): No manuscript has entered the conservation queue since January."], "explanation": "Near miss (partial): \"no condition reports have been filed since January\" (a link in the chain, not its end). Wrong turn: any single premise. No conclusion stated at all. Trait 2. Note: connect the chain, then say what has to be true if every premise is.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 52, "prompt": "Any exhibit that travels must be crated to the lender''s specification. The lender specifies a climate-controlled crate for anything on panel. The altarpiece is on panel and is scheduled to travel in March.", "credited_answers": ["(derived): The altarpiece must be crated in a climate-controlled crate."], "explanation": "Near miss (partial): \"the altarpiece must be crated to the lender''s specification\" (true, one link short). No conclusion stated. Trait 2.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 53, "prompt": "Good archival practice is ultimately a matter of judgment rather than rules. The retention schedule the state provides cannot anticipate the records this office generates. Half our series have no matching category, and the categories that do match were written for paper. So the schedule should be treated as a starting point, not an authority.", "credited_answers": ["The retention schedule should be treated as a starting point, not an authority."], "explanation": "Near miss (partial): \"the state schedule does not fit this office''s records\" (support). Wrong turn: the opening sentence, which is broad, confident, and supported by nothing. Trait 1. Note: his exact Trait 1 shape. Support beats sound.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 54, "prompt": "A total ban on rooftop beekeeping is too strong a response. Two hives on one building did swarm into a schoolyard. That building had eight hives on a roof rated for two. Nothing in the incident tells us anything about a properly limited hive count.", "credited_answers": ["A total ban is too strong a response."], "explanation": "Near miss (partial): \"the ban should be narrower.\" Wrong turn: \"rooftop beekeeping is safe\" (the overshoot the argument specifically does not license); also the swarm incident. No indicator; conclusion first. Trait 4. Note: the reasons refute an absolute ban and nothing more. This is the scope trap in its cleanest form.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 55, "prompt": "The department will lose the fellowship line whether or not it files an appeal. The appeal window closed in August, the provost''s memo calls the reallocation final, and the two departments that appealed last year received the letter we received. It would be better if the university funded these lines properly, but that is not what will happen here.", "credited_answers": ["The department will lose the fellowship line regardless of an appeal."], "explanation": "Near miss (partial): \"an appeal would fail.\" Wrong turn: \"the university should fund these lines properly\" (the author agrees with it and is not arguing it). No indicator; prediction in the first seat. Trait 5. Note: do not turn a prediction into a policy. If the argument predicts, the conclusion predicts.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 56, "prompt": "The dispute assumes a work is either an original or a copy. The workshop that produced these panels used a master''s drawing, the master''s pigments, and the master''s hand on the faces alone. Calling the panels copies erases what the master did. Calling them originals erases the workshop. The category this argument needs does not exist in the catalogue.", "credited_answers": ["The category the argument needs does not exist in the catalogue."], "explanation": "Near miss (partial): \"the panels are neither originals nor copies\" (an acceptable paraphrase, and worth crediting; a student who lands here has the idea). Wrong turn: \"the master painted the faces\" (concrete, memorable, a premise). No indicator; abstract conclusion in the final seat. Trait 6. Note: the correct answer is the abstract one sitting next to a vivid concrete distractor.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 57, "prompt": "Some members propose requiring a sponsor for every new applicant. Such a requirement would not do what they expect. The applicants the society has failed to attract do not know anyone who could sponsor them, and that is the substance of the problem the rule is meant to solve.", "credited_answers": ["(substituted): Requiring a sponsor for every applicant would not solve the society''s problem attracting applicants."], "explanation": "Near miss (partial): \"such a requirement would not do what they expect\" left referential. Wrong turn: the members'' proposal. Attribution plus referential rejection, no pivot word. Trait 3 plus substitution.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 58, "prompt": "The survey went to every household on the water system. Only nine percent responded, and respondents skewed heavily toward the two neighborhoods that already had complaints on file. The results cannot support a system-wide conclusion. The utility has nonetheless printed them in the annual report under the heading Customer Satisfaction.", "credited_answers": ["The results cannot support a system-wide conclusion."], "explanation": "Near miss (partial): \"the utility should not have printed the results\" (a reasonable extension the author does not state). Wrong turn: the final sentence (Last Claim Trap; it is a further fact). No indicator; conclusion sandwiched third of four. Trait 1 and the Last Claim Trap.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 59, "prompt": "The consultant''s report concludes that the branch should close because its transaction volume is the lowest in the region. Transaction volume is the wrong measure here. The branch handles the region''s only safe-deposit vault and most of its notarizations, and the report counts neither.", "credited_answers": ["Transaction volume is the wrong measure for this decision."], "explanation": "Near miss (partial): \"the branch should not close\" (the author implies it and argues something narrower). Wrong turn: \"the branch should close\" (the consultant''s conclusion, not the author''s). Two conclusions in one argument, one of them quoted. Trait 5. Note: separate the author''s conclusion from a conclusion the author is reporting.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 60, "prompt": "Even if the new filtration removes every trace of the compound, the district should not treat the well as a long-term source. The aquifer beneath it is recharged by the same fields where the compound originated, and filtration addresses what is already in the water rather than what keeps arriving.", "credited_answers": ["The district should not treat the well as a long-term source, even if filtration works completely."], "explanation": "Near miss (partial): \"filtration will not remove the compound\" (contradicts the concession the author granted); \"the district should not use the well\" (drops the long-term qualifier). No indicator; conclusion in the first seat behind an \"even if.\" Trait 4.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 61, "prompt": "The board''s timeline for the renovation is evidently optimistic. Permits alone took fourteen months on the last project of this size, and the drawings for this one are not finished.", "credited_answers": ["The board''s renovation timeline is optimistic."], "explanation": "Near miss (partial): \"the renovation will be late\" (a prediction the author does not quite make). Wrong turn: the fourteen-month figure. \"Evidently\" opinion indicator, no structural marker. Trait 4. Note: when nothing else marks the claim, an opinion indicator is the best clue available.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}, {"order": 62, "prompt": "The tool library will be out of the tile saw for the rest of the season. Requests are arriving at four times last spring''s rate, the member who donated it has stopped lending, and no one has offered a substitute.", "credited_answers": ["The tool library will be out of the tile saw for the rest of the season."], "explanation": "Near miss (partial): \"the tool library needs another tile saw\" (a sensible recommendation the argument does not make). Wrong turn: the request rate. No indicator at all; prediction in the first seat, three reasons after. Trait 5. Note: the closing bare case. No marker anywhere, so the 2-Point Check and the \"Why should we believe that?\" test are the only tools left, which is the point of putting it last.", "category": "Level 5: No clean indicator, unstated, qualified, or somebody else''s conclusion"}]'::jsonb,
    NULL,
    NULL,
    NULL
  ),
  (
    'rebuttal-rephrase',
    'Rebuttal Rephrase',
    'Say what the author actually believes, at the author''s exact strength',
    '{"coach": {"drill": "a rebuttal-rephrasing drill: the argument''s conclusion is a referential rejection of somebody else''s claim, and the student must restate it in content terms", "rubric": ["The credited answer is the MINIMAL negation of the attributed claim, stated in content terms, preserving the author''s exact level of certainty.", "Minimal means smallest: the negation of ''can never'' is ''can sometimes'', never ''can always''. The negation of ''no'' is ''at least one'', never ''many''. The negation of ''must'' is ''not necessarily'', never ''definitely not''.", "Every qualifier in the original claim must survive into the answer. If the claim said ''exclusively'' or ''in every filing'' or named a comparison, an answer that drops it has changed the claim.", "Where the author concedes one claim and rejects another, a correct answer carries both moves. Contradicting something the author granted is not correct."], "partial_rule": "Mark ''partial'' when the student has the right claim but overshoots to the polar opposite, or drops a scope qualifier, or leaves the referential phrase unresolved (''these researchers are mistaken'' with no content substituted). Mark ''incorrect'' when they answer with the evidence rather than the conclusion, restate the attributed claim as if the author endorsed it, or address a different claim entirely."}, "tagline": "They''re wrong is the conclusion. It is not yet an answer.", "task": "Two steps. First find the conclusion of the argument. Then rephrase it, replacing the referential language with the claim it actually points at.", "rules": ["Every one of these arguments has the same anatomy: somebody else''s claim, then the author rejecting it. The rejection is the conclusion, and on its own it says nothing.", "The credited answer is the smallest negation of the attributed claim, stated in content terms.", "Preserve the author''s level of certainty. The negation of can never is can sometimes, not can always.", "Keep every qualifier. If the claim said exclusively, your answer still says exclusively.", "Do not answer with the evidence. The evidence supports the conclusion; it is not the conclusion."], "worked_example": {"statement": "People think gum is food, but they''re wrong.", "credited_answers": ["Gum is not food."], "explanation": "The explicit conclusion is they''re wrong. That is the sentence you locate. What we want to hear is what it means: gum is not food. Every item in this activity is that move on harder material."}, "answer_label": "Your rephrase", "answer_placeholder": "Say what the author believes, at the author''s exact strength…"}'::jsonb,
    'free-text',
    '[{"order": 1, "prompt": "Although some luthiers maintain that a violin top cannot be regraduated without dulling its tone, this is not so.", "credited_answers": ["A violin top can be regraduated without dulling its tone."], "explanation": "Overshoot to refuse: \"regraduation improves tone.\" Attribution \"some luthiers maintain\" \"cannot\" \"this is not so.\" Note: the flip is *can*, and it stops there. The author has not said regraduation is good.", "category": "Level 1: Bare flip"}, {"order": 2, "prompt": "That is mistaken. Curators have argued that a panel painting cannot be moved safely once its cradle is removed.", "credited_answers": ["A panel painting can be moved safely after its cradle is removed."], "explanation": "Rejection before the attribution. Note: order is reversed on the page and the task does not change. Find the attributed claim first, wherever it sits.", "category": "Level 1: Bare flip"}, {"order": 3, "prompt": "A number of coaches hold that it is impossible to correct a swimmer''s catch after adolescence. They are wrong.", "credited_answers": ["It is possible to correct a swimmer''s catch after adolescence."], "explanation": "Overshoot: \"the catch is easiest to correct after adolescence.\" \"impossible\" \"they are wrong.\"", "category": "Level 1: Bare flip"}, {"order": 4, "prompt": "The standard account says that no medieval scriptorium employed women as copyists. The account does not hold.", "credited_answers": ["At least one medieval scriptorium employed women as copyists."], "explanation": "Overshoot: \"many scriptoria employed women.\" Note: the negation of *no* is *at least one*. Not \"many,\" not \"most,\" not \"commonly.\" This is the single most common overshoot in the level.", "category": "Level 1: Bare flip"}, {"order": 5, "prompt": "Some agronomists maintain that saline soils cannot support a cereal crop, a position that cannot be sustained.", "credited_answers": ["Saline soils can support a cereal crop."], "explanation": "Rejection embedded in the same sentence as an apposition. Note: no pivot word at all. The rejection arrives as a relative clause.", "category": "Level 1: Bare flip"}, {"order": 6, "prompt": "It is widely assumed that a building of this period could not have carried a glazed clerestory. The assumption is false.", "credited_answers": ["A building of this period could have carried a glazed clerestory."], "explanation": "Overshoot: \"buildings of this period did carry glazed clerestories.\" Note: *could have* is a possibility claim. Negating it yields possibility, not fact.", "category": "Level 1: Bare flip"}, {"order": 7, "prompt": "Several reviewers insist that a chamber work cannot be scored for these four instruments without imbalance. Not so.", "credited_answers": ["A chamber work can be scored for these four instruments without imbalance."], "explanation": "Scope note: \"without imbalance\" must survive. \"A chamber work can be scored for these four instruments\" is a scope drop, and a much weaker claim.", "category": "Level 1: Bare flip"}, {"order": 8, "prompt": "Some archivists contend that a nitrate negative cannot be duplicated once decay has begun. This claim is incorrect.", "credited_answers": ["A nitrate negative can be duplicated after decay has begun."], "explanation": "Scope note: \"once decay has begun\" is the whole point of the dispute. Dropping it concedes nothing and claims nothing.", "category": "Level 1: Bare flip"}, {"order": 9, "prompt": "The prevailing view holds that no untrained listener can distinguish the two dialects. That view fails.", "credited_answers": ["At least one untrained listener can distinguish the two dialects."], "explanation": "Overshoot: \"untrained listeners can distinguish the two dialects\" (reads as a general capacity). \"no\" plus \"can.\"", "category": "Level 1: Bare flip"}, {"order": 10, "prompt": "Engineers on the review panel argued that a timber floor of this span cannot carry the intended load. Their argument does not survive scrutiny.", "credited_answers": ["A timber floor of this span can carry the intended load."], "explanation": "Note: \"does not survive scrutiny\" is a rejection dressed as an assessment. It behaves exactly like \"this is not so.\"", "category": "Level 1: Bare flip"}, {"order": 11, "prompt": "Some conservators claim that infrared reflectography can never recover an underdrawing beneath a lead-white ground. Reflectography at 2.2 microns recovered the full underdrawing on the Ghent panel, whose ground is lead white. These conservators are mistaken.", "credited_answers": ["Infrared reflectography can sometimes recover an underdrawing beneath a lead-white ground."], "explanation": "An even more precise answer folds in the evidence: it can do so at 2.2 microns. Overshoot: \"can always recover.\" Premise trap: \"reflectography recovered the underdrawing on the Ghent panel\" is the evidence, not the conclusion. \"never\" → \"sometimes.\"", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 12, "prompt": "It is often said that every surviving copy of the broadside was printed from the same forme. Two copies show a turned letter in the fourth line that the others do not. The claim is wrong.", "credited_answers": ["Not every surviving copy was printed from the same forme."], "explanation": "An even more precise answer folds in the evidence: at least two were printed from a different setting. Overshoot: \"no two copies came from the same forme.\" Note: the negation of *every* is *not every*, which is compatible with almost all of them matching.", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 13, "prompt": "A number of hydrologists maintain that a losing stream never recharges the aquifer beneath it. Tracer dye released above the reach appeared in two monitoring wells within a week. That position cannot stand.", "credited_answers": ["A losing stream can sometimes recharge the aquifer beneath it."], "explanation": "An even more precise answer folds in the evidence: it can do so within a week over this reach. Premise trap: the dye result. Overshoot: \"a losing stream always recharges the aquifer.\"", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 14, "prompt": "The committee''s report states that all applicants rejected at the first stage lacked the required certification. Three of last year''s first-stage rejections held current certification. The report is in error.", "credited_answers": ["Not all applicants rejected at the first stage lacked the certification."], "explanation": "An even more precise answer folds in the evidence: at least three held it. Overshoot: \"the rejected applicants held the certification\" (reads as all of them). Note: *all* negates to *not all*, which the three cases establish exactly.", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 15, "prompt": "Some ethnomusicologists argue that a work notated in this system can never be performed at its original tempo. The treatise gives a pendulum length for the opening movement. This inference is unwarranted.", "credited_answers": ["A work notated in this system can sometimes be performed at its original tempo."], "explanation": "An even more precise answer folds in the evidence: at least where a pendulum length survives, as it does for the opening movement. Premise trap: the pendulum length itself. \"never\" → \"sometimes.\"", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 16, "prompt": "It is a common assumption that a kiln of this type always fires unevenly across the chamber. Pyrometric cones placed at four heights in the Aswan kiln fell within one cone of each other. The assumption is unsound.", "credited_answers": ["A kiln of this type does not always fire unevenly across the chamber."], "explanation": "An even more precise answer folds in the evidence: at least one fired within one cone across four heights. Overshoot: \"a kiln of this type fires evenly.\" \"always\" → \"not always.\"", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 17, "prompt": "Several economists have written that a currency board never survives a terms-of-trade shock of this magnitude. Two boards in the region held through shocks larger than the one under discussion. They are wrong about this.", "credited_answers": ["A currency board can sometimes survive a terms-of-trade shock of this magnitude."], "explanation": "An even more precise answer folds in the evidence: at least two have survived larger ones. Premise trap: the two boards. Note: \"wrong about this\" is narrow. The author rejects one claim, not the economists generally.", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 18, "prompt": "The catalogue asserts that none of the workshop''s signed pieces postdate the master''s death. One signed piece bears a hallmark introduced two years after. The catalogue is incorrect on this point.", "credited_answers": ["At least one signed piece postdates the master''s death."], "explanation": "An even more precise answer folds in the evidence: at least one bears a hallmark introduced two years after. Overshoot: \"the signed pieces postdate the master''s death.\" \"none\" → \"at least one.\"", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 19, "prompt": "Some clinicians hold that a patient with this deficiency can never tolerate the standard dose. In the cohort described, four patients completed the full course without adverse events. That conclusion does not follow.", "credited_answers": ["A patient with this deficiency can sometimes tolerate the standard dose."], "explanation": "An even more precise answer folds in the evidence: at least four completed the full course without adverse events. Premise trap: the cohort result. Overshoot: \"patients with this deficiency tolerate the standard dose.\"", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 20, "prompt": "It is frequently claimed that every dialect in the valley lost the final vowel by the tenth century. The northern recordings preserve it in unstressed position. The claim is false.", "credited_answers": ["Not every dialect in the valley lost the final vowel by the tenth century."], "explanation": "An even more precise answer folds in the evidence: the northern dialects preserve it in unstressed position. Scope note: \"in unstressed position\" is a real limit. An answer saying the northern dialects kept the final vowel outright overstates the evidence.", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 21, "prompt": "Reviewers of the first edition wrote that the author never cites a source outside the two archives. The appendix quotes a letter held in a private collection. Those reviewers were mistaken.", "credited_answers": ["The author sometimes cites a source outside the two archives."], "explanation": "An even more precise answer folds in the evidence: at least once, a letter in a private collection. Overshoot: \"the author cites widely outside the two archives.\"", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 22, "prompt": "A standard textbook claims that all reactions of this class require a metal catalyst. The Hoffman preparation runs to completion in its absence. This is not correct.", "credited_answers": ["Not all reactions of this class require a metal catalyst."], "explanation": "An even more precise answer folds in the evidence: the Hoffman preparation does not. Overshoot: \"reactions of this class do not require a metal catalyst.\" Note: watch the difference between *not all require* and *none require*. Only the first is earned.", "category": "Level 2: Quantifier negation with evidence present"}, {"order": 23, "prompt": "It is erroneous to infer that any kiln site yielding wasters must have been a production centre rather than a dump.", "credited_answers": ["A kiln site yielding wasters was not necessarily a production centre rather than a dump."], "explanation": "Scope note: \"rather than a dump\" is the contrast the claim was built on; an answer that says only \"was not necessarily a production centre\" has dropped half of it. Negate the necessity, not the fact. The author is not saying no such site was a production centre. Rejection wraps the claim.", "category": "Level 3: Nested modality and scope"}, {"order": 24, "prompt": "There is no warrant for the conclusion that every manuscript in this hand must have been copied in the same scriptorium.", "credited_answers": ["Manuscripts in this hand were not necessarily all copied in the same scriptorium."], "explanation": "Overshoot: \"manuscripts in this hand were copied in different scriptoria.\" Note: two strength words stacked, *every* and *must*. The minimal negation loosens the necessity and leaves the rest alone.", "category": "Level 3: Nested modality and scope"}, {"order": 25, "prompt": "The inference that any sediment core showing this ash layer must record the same eruption is unfounded.", "credited_answers": ["A sediment core showing this ash layer does not necessarily record that eruption."], "explanation": "Overshoot: \"cores showing this layer record different eruptions.\" Rejection trails the wrapped claim.", "category": "Level 3: Nested modality and scope"}, {"order": 26, "prompt": "One cannot conclude from the residue alone that these vessels must have been reserved exclusively for ritual use.", "credited_answers": ["These vessels were not necessarily reserved exclusively for ritual use."], "explanation": "Scope note: \"exclusively\" must survive. \"These vessels were not reserved for ritual use\" is a different and much stronger claim the author never makes. Note: \"from the residue alone\" also limits the rejection; the author objects to the inference from that one evidence type.", "category": "Level 3: Nested modality and scope"}, {"order": 27, "prompt": "It does not follow that a firm reporting under the older standard must have understated its liabilities in every filing.", "credited_answers": ["A firm reporting under the older standard did not necessarily understate its liabilities in every filing."], "explanation": "Scope note: \"in every filing\" survives. Dropping it produces \"did not understate its liabilities,\" which is far stronger than the author''s point. Two qualifiers to thread: *must* and *every*.", "category": "Level 3: Nested modality and scope"}, {"order": 28, "prompt": "The claim that any settlement abandoned in this period must have been abandoned because of the drought cannot be sustained.", "credited_answers": ["A settlement abandoned in this period was not necessarily abandoned because of the drought."], "explanation": "Overshoot: \"the drought did not cause these abandonments.\" Note: the author objects to the *necessity* of the causal claim, leaving the drought available as one cause among others.", "category": "Level 3: Nested modality and scope"}, {"order": 29, "prompt": "There is no basis for holding that a signature in this ink must postdate the workshop''s move to Antwerp.", "credited_answers": ["A signature in this ink does not necessarily postdate the move to Antwerp."], "explanation": "Overshoot: \"signatures in this ink predate the move.\"", "category": "Level 3: Nested modality and scope"}, {"order": 30, "prompt": "It is a mistake to suppose that a species found only in these two valleys must have originated in one of them.", "credited_answers": ["A species found only in these two valleys did not necessarily originate in either."], "explanation": "Scope note: \"found only in these two valleys\" is the setup and stays intact; the necessity is what falls. Note: \"one of them\" negates to \"either,\" which students routinely render as \"neither,\" an overshoot.", "category": "Level 3: Nested modality and scope"}, {"order": 31, "prompt": "That a tremor recorded at this depth must be volcanic rather than tectonic is an inference the data do not support.", "credited_answers": ["A tremor recorded at this depth is not necessarily volcanic rather than tectonic."], "explanation": "Scope note: the internal contrast \"rather than tectonic\" survives whole. Rejection is the sentence''s predicate, with the claim as its subject.", "category": "Level 3: Nested modality and scope"}, {"order": 32, "prompt": "We should not accept that any endorsement collected under the older rule must be treated as valid for the full term.", "credited_answers": ["An endorsement collected under the older rule need not be treated as valid for the full term."], "explanation": "Scope note: \"for the full term\" survives; without it the claim becomes \"need not be treated as valid,\" which is a different objection.", "category": "Level 3: Nested modality and scope"}, {"order": 33, "prompt": "The suggestion that every panel with this ground preparation must come from the same workshop does not withstand examination.", "credited_answers": ["Panels with this ground preparation do not all necessarily come from the same workshop."], "explanation": "Overshoot: \"these panels come from different workshops.\"", "category": "Level 3: Nested modality and scope"}, {"order": 34, "prompt": "It is erroneous to infer that a text surviving in a single witness must be less reliable than one surviving in many.", "credited_answers": ["A text surviving in a single witness is not necessarily less reliable than one surviving in many."], "explanation": "Scope note: the comparison is the claim. An answer saying \"a single-witness text is reliable\" both drops the comparison and overshoots the necessity.", "category": "Level 3: Nested modality and scope"}, {"order": 35, "prompt": "Some economists argue that the deposit scheme raised recycling rates and that it did so at no cost to low-income households. The rates did rise. But the scheme''s unredeemed deposits fall disproportionately on households that cannot easily return containers, so the second half of that claim is wrong.", "credited_answers": ["The deposit scheme raised recycling rates, but it did so at some cost to low-income households."], "explanation": "Note: two moves, and only one of them is a rejection. The author concedes the first conjunct outright. An answer that rejects both (\"the scheme did not raise recycling rates\") contradicts a claim the author granted.", "category": "Level 4: Compound rebuttals"}, {"order": 36, "prompt": "Critics of the attribution say the underdrawing is inconsistent with the master''s practice and that the panel must therefore be a workshop product. The underdrawing is indeed unusual for him. It does not follow that the panel is a workshop product, since he is documented as varying his preparation on commissions of this scale.", "credited_answers": ["The underdrawing is unusual for the master, but the panel is not necessarily a workshop product."], "explanation": "Concession preserved. Overshoot: \"the underdrawing is consistent with his practice\" (contradicts the concession) or \"the panel is by the master\" (stronger than the author''s point).", "category": "Level 4: Compound rebuttals"}, {"order": 37, "prompt": "A common view holds that the treaty text was drafted in Latin and that the vernacular version is a later translation. The Latin is certainly the older of the two surviving copies. But the vernacular carries two clauses absent from the Latin, which a translator would have had no source for.", "credited_answers": ["The Latin copy is older, but the vernacular version is not simply a later translation of it."], "explanation": "An even more precise answer folds in the evidence: the vernacular carries clauses a translator working from the Latin could not have supplied. Note: the author rejects the second claim while granting the first, and the granted claim is *not* the same as the rejected one. Read the conjunction carefully.", "category": "Level 4: Compound rebuttals"}, {"order": 38, "prompt": "The report concludes that the outage began at the substation and that the maintenance crew''s error caused it. The substation was the origin. But the relay had already failed its last two tests, and a relay in that condition trips under load regardless of what a crew does.", "credited_answers": ["The outage began at the substation, but the maintenance crew''s error did not necessarily cause it."], "explanation": "Scope note: \"not necessarily\" rather than \"did not.\" The author''s evidence establishes an alternative sufficient cause, not the crew''s innocence. Overshoot: \"the crew made no error.\"", "category": "Level 4: Compound rebuttals"}, {"order": 39, "prompt": "Some historians maintain that the guild''s decline was caused by the new tariff and that no internal factor contributed. The tariff plainly hurt them. Yet the guild had lost a third of its masters to the city companies before the tariff passed.", "credited_answers": ["The tariff hurt the guild, but internal factors also contributed to its decline."], "explanation": "An even more precise answer folds in the evidence: it had already lost a third of its masters before the tariff passed. Note: the negation of \"no internal factor contributed\" is \"at least one did,\" not \"internal factors caused the decline.\"", "category": "Level 4: Compound rebuttals"}, {"order": 40, "prompt": "It is argued that the drug shortens recovery and that it should therefore be first-line therapy. Recovery was shorter in the treatment arm. But the trial excluded patients with the comorbidity that two-thirds of the eligible population has, so the recommendation outruns the evidence.", "credited_answers": ["The drug shortens recovery in the population studied, but that does not establish it as first-line therapy."], "explanation": "Scope note: \"in the population studied\" is the qualification the author''s objection turns on. Overshoot: \"the drug does not shorten recovery.\"", "category": "Level 4: Compound rebuttals"}, {"order": 41, "prompt": "Commentators claim the exhibition failed because the catalogue was late and that the venue was never a factor. The catalogue was late. But attendance at the same show in a comparable city, with the same delay, ran three times higher.", "credited_answers": ["The catalogue was late, but the venue was a factor in the exhibition''s performance."], "explanation": "An even more precise answer folds in the evidence: attendance ran three times higher for the same show, with the same delay, in a comparable city. Note: the author does not say the catalogue was irrelevant. Only the second claim is rejected.", "category": "Level 4: Compound rebuttals"}, {"order": 42, "prompt": "One school holds that the inscription is a forgery, on the grounds that its letterforms are too regular for the period and that no genuine inscription of the period is cut this deep. The letterforms are regular. But three securely dated inscriptions are cut deeper still, so the second ground fails and the first cannot carry the case alone.", "credited_answers": ["The letterforms are regular, but the depth of the cut is no evidence of forgery, and regularity alone does not establish that the inscription is a forgery."], "explanation": "Note: the hardest item in the bank. Three moves: a concession, a rejected sub-claim, and a judgment about what the surviving ground can support. An answer that says \"the inscription is genuine\" overshoots all three; the author says the case for forgery fails, which is not the same as establishing authenticity.", "category": "Level 4: Compound rebuttals"}]'::jsonb,
    NULL,
    NULL,
    NULL
  ),
  (
    'dumb-it-down',
    'Dumb it Down',
    'Compress the paragraph to its big ideas, in plain words',
    '{"coach": {"drill": "a paragraph-compression drill: the student restates a dense academic paragraph in plain language, keeping every big idea", "rubric": ["The credited answer is a plain-language summary carrying all of the paragraph''s big ideas. The author''s note lists them; check the response against that list.", "Judge coverage and accuracy, never elegance. A blunt, informal summary that carries every big idea is fully correct.", "Technical vocabulary does not need to be preserved. A student who explains a term in their own words has done the exercise correctly.", "Where the paragraph sets a common view against what is actually the case, or sets two camps against each other, both sides and who holds them must survive into the summary."], "partial_rule": "Mark ''partial'' when the summary is accurate but too narrow, carrying some big ideas and missing others, which is the drill''s signature miss. Mark ''incorrect'' when the response only names the topic without saying what the paragraph claims about it, or misstates the paragraph''s point."}, "tagline": "Understand the hard words functionally. Do not preserve them.", "task": "Read the paragraph and tell me what it says in plain language. Keep every big idea and drop everything else.", "rules": ["Your summary has to carry the big ideas. If one goes missing, the summary is too narrow no matter how well written it is.", "Say it in words you would use out loud. Technical vocabulary is there to be understood, not repeated.", "If the paragraph sets up a contrast between what people think and what is actually the case, both halves belong in your answer.", "Where two camps disagree, keep who thinks what. Losing the attribution loses the paragraph.", "Naming the topic is not summarizing the paragraph."], "answer_label": "Your plain-language version", "answer_placeholder": "Say what the paragraph says, in plain words…"}'::jsonb,
    'free-text',
    '[{"order": 1, "prompt": "Lighthouse keepers are often remembered as solitary romantics who chose isolation for its own sake. In practice, most keepers were practical tradespeople managing an industrial workplace. A single station required constant fuel measurement, lens polishing, logbook entries, and equipment repair on a strict schedule set by the lighthouse authority. Keepers who missed a lighting time or let a lens cloud over faced fines and dismissal. The job attracted people who wanted steady government wages and housing, not poets seeking solitude. The isolation was a cost of the work, not its attraction.", "credited_answers": ["Lighthouse keepers were not romantic loners but practical workers running a demanding industrial job, and the isolation was a downside of the work rather than the reason they chose it."], "explanation": "The big ideas your summary has to carry: (1) popular image: solitary romantics · (2) reality: tradespeople in a regulated industrial job · (3) isolation was a cost, not the appeal. Named traps: Too narrow: \"Keepers had to polish lenses and keep logbooks.\" Topic-only: \"Lighthouse keeping was a hard job.\"", "category": "Tier 1: One clear contrast, plain vocabulary"}, {"order": 2, "prompt": "Municipal fountains in nineteenth-century cities are commonly described as decorative luxuries commissioned by vain city councils. That description misses their sanitary purpose. Before household plumbing became widespread, public fountains were often the only reliable source of clean drinking water in crowded districts, and their placement closely tracked outbreaks of waterborne disease. Councils built them where wells had been contaminated, and engineers designed the basins to keep animals and washing away from the drinking spouts. The ornament was real, but it decorated a piece of public health infrastructure.", "credited_answers": ["Nineteenth-century public fountains were not just decoration; they were public health infrastructure that supplied clean drinking water to districts where wells were contaminated."], "explanation": "The big ideas your summary has to carry: (1) common view: decorative vanity projects · (2) actual function: clean water / disease prevention · (3) design and placement served the sanitary purpose. Named traps: Too narrow: \"Fountain basins kept animals away from the spouts.\" Topic-only: \"Cities built many fountains in the 1800s.\"", "category": "Tier 1: One clear contrast, plain vocabulary"}, {"order": 3, "prompt": "The switchboard operators who connected early telephone calls are sometimes dismissed as unskilled labor eliminated by obvious automation. The record suggests otherwise. Operators memorized hundreds of line assignments, diagnosed faults by ear, and managed emergency traffic during storms and fires when call volume spiked beyond anything the equipment was designed for. Telephone companies resisted automatic exchanges for decades partly because operators absorbed failures the machinery could not. Automation succeeded only after engineers redesigned the network around the judgment calls operators had quietly been making all along.", "credited_answers": ["Early switchboard operators were skilled workers whose judgment held the phone network together, and automation only replaced them once engineers rebuilt the system around the work they had been doing."], "explanation": "The big ideas your summary has to carry: (1) dismissive view: unskilled, obviously automatable · (2) reality: skilled diagnosis and emergency management · (3) automation required redesigning around their judgment. Named traps: Too narrow: \"Operators memorized hundreds of line assignments.\" Topic-only: \"Telephones used to need human operators.\"", "category": "Tier 1: One clear contrast, plain vocabulary"}, {"order": 4, "prompt": "Hand-copied recipe books passed between households are easy to read as quaint domestic keepsakes. Historians of food increasingly treat them as working technical documents. Copyists corrected quantities that failed, noted substitutions for scarce ingredients, and recorded which preparations preserved food safely through winter. Because the books moved between kitchens with the people who used them, their marginal notes preserve a record of trial, error, and adaptation that printed cookbooks of the period, written for idealized kitchens, deliberately smoothed over.", "credited_answers": ["Hand-copied recipe books were not just keepsakes but working technical records whose corrections and notes captured real kitchen experimentation that printed cookbooks left out."], "explanation": "The big ideas your summary has to carry: (1) quaint-keepsake view · (2) reality: corrected, tested technical documents · (3) they preserve trial-and-error evidence printed books smoothed over. Named traps: Too narrow: \"People wrote substitutions in the margins.\" Topic-only: \"Old recipe books are historically interesting.\"", "category": "Tier 1: One clear contrast, plain vocabulary"}, {"order": 5, "prompt": "The physician credited with early anesthesia records is often celebrated simply for using ether during surgery. Her more lasting contribution was procedural. She insisted that every administration be logged with the patient''s weight, the dose, the time to unconsciousness, and the time to waking, and she refused to call any outcome a success until the numbers were recorded. Colleagues found the bookkeeping tedious, yet those logs made dosage predictable, turned anesthesia from a gamble into a calculable procedure, and became the model for the clinical record-keeping that modern surgical safety depends on.", "credited_answers": ["Her real contribution was not just using ether but insisting on systematic dose records, which turned anesthesia into a predictable procedure and modeled modern clinical record-keeping."], "explanation": "The big ideas your summary has to carry: (1) remembered for: using ether · (2) actual leap: mandatory quantified logging · (3) consequence: predictable dosing and the template for clinical records. Named traps: Too narrow: \"She logged patients'' weights and doses.\" Topic-only: \"She was an early anesthesia pioneer.\"", "category": "Tier 2: A figure''s conceptual leap, mild jargon"}, {"order": 6, "prompt": "The cartographer who first mapped the deep Atlantic seafloor is usually mentioned for the maps themselves. Her conceptual advance was treating the ocean floor as terrain at all. Contemporaries assumed the deep sea was a featureless plain and plotted soundings as isolated numbers. She interpolated between soundings the way land surveyors did between hilltops, drew ridges and valleys where no one had authorized them, and in doing so revealed a continuous mountain range running down the ocean''s center. The maps mattered because the assumption behind them changed what the numbers could mean.", "credited_answers": ["Her breakthrough was treating the seafloor as real terrain rather than a featureless plain, which let scattered depth measurements reveal a continuous mid-ocean mountain range."], "explanation": "The big ideas your summary has to carry: (1) known for: the maps · (2) conceptual leap: seafloor as terrain, interpolating like a land surveyor · (3) result: the mid-ocean ridge became visible. Named traps: Too narrow: \"She drew ridges between soundings.\" Topic-only: \"She made important maps of the Atlantic.\"", "category": "Tier 2: A figure''s conceptual leap, mild jargon"}, {"order": 7, "prompt": "The economist who reorganized a national postal system is remembered for cutting delivery times, but the deeper idea was about pricing. Before the reform, postage was charged by distance and collected from the recipient, which made every letter a negotiation and left the system drowning in refused mail. He proposed a single low prepaid rate for any destination in the country, reasoning that the cost of handling a letter lay in sorting and delivery labor, not in miles traveled. Prepayment converted mail from a per-transaction haggle into cheap standardized infrastructure, and volume grew enough to pay for the reform many times over.", "credited_answers": ["His key insight was that mail should be prepaid at one flat rate because handling, not distance, drove the cost, which turned the post into cheap standardized infrastructure and massively grew volume."], "explanation": "The big ideas your summary has to carry: (1) remembered for: faster delivery · (2) real idea: flat prepaid pricing based on handling cost · (3) consequence: standardization and volume growth. Named traps: Too narrow: \"Recipients used to refuse their mail.\" Topic-only: \"He reformed the postal system.\"", "category": "Tier 2: A figure''s conceptual leap, mild jargon"}, {"order": 8, "prompt": "The programmer who wrote an early machine translation demonstration is often cited for the demonstration''s failure. Her working notes point somewhere more interesting. She concluded that translation failed not because dictionaries were too small but because meaning depends on context that sentences do not contain, and she proposed that any successful system would need to store and consult structured knowledge about the world. That diagnosis, largely ignored at the time, anticipated the direction the field eventually took decades later, when translation systems began to succeed by modeling context rather than by enlarging word lists.", "credited_answers": ["Her lasting contribution was diagnosing that machine translation fails without contextual world knowledge, not because dictionaries are too small, a conclusion the field only later proved right."], "explanation": "The big ideas your summary has to carry: (1) cited for: a failed demo · (2) diagnosis: meaning needs context beyond the sentence · (3) anticipation: the field later succeeded by modeling context. Named traps: Too narrow: \"Her demonstration did not work.\" Topic-only: \"Early machine translation was difficult.\"", "category": "Tier 2: A figure''s conceptual leap, mild jargon"}, {"order": 9, "prompt": "Some urban planners argue that widening congested roads is self-defeating because added capacity attracts new drivers until congestion returns to its old level. Others respond that this induced traffic is not waste but demand that was always there, suppressed by gridlock, and that the new trips represent real economic activity. The disagreement is therefore not about whether widened roads fill up. Both sides accept that they do. It is about whether the filling should be counted as a failure of congestion relief or as a success in serving trips the old road was silently rationing.", "credited_answers": ["Both camps agree widened roads fill back up; they disagree about whether that returning traffic proves widening fails or shows it is serving real demand the congestion had been suppressing."], "explanation": "The big ideas your summary has to carry: (1) camp one: induced traffic makes widening self-defeating · (2) camp two: the new trips are real suppressed demand · (3) shared ground: roads do fill up; the dispute is how to count it. Named traps: Too narrow: \"New lanes attract more drivers.\" Topic-only: \"Planners disagree about road widening.\" (Misses that the disagreement is about interpretation, not the facts.)", "category": "Tier 3: Two camps, and the summary must keep who-thinks-what"}, {"order": 10, "prompt": "Conservators disagree about restoring faded murals. One school holds that every repainted stroke, however faithful, replaces the artist''s hand with the restorer''s and should be refused on principle; better a ghost of the original than a confident forgery. The opposing school answers that murals were made to be legible public statements, and that leaving one illegible betrays the work''s purpose more deeply than careful inpainting ever could. Underneath the technical debate sits a disagreement about what the object actually is: a physical relic of the artist''s touch, or a public image whose meaning requires visibility.", "credited_answers": ["Mural restorers split between refusing repainting to preserve the artist''s actual hand and repainting to preserve the mural''s legible public message, a dispute over whether the object is a relic or an image."], "explanation": "The big ideas your summary has to carry: (1) camp one: never repaint, the touch is the work · (2) camp two: repaint, legibility is the work · (3) the real disagreement: what kind of object a mural is. Named traps: Too narrow: \"Some restorers use inpainting on faded murals.\" Topic-only: \"Experts disagree about restoration.\"", "category": "Tier 3: Two camps, and the summary must keep who-thinks-what"}, {"order": 11, "prompt": "When excavations uncover large storehouses beside ancient temples, one group of archaeologists reads them as evidence of centralized command economies in which priests collected and rationed the harvest. Skeptics counter that the same buildings are equally consistent with voluntary festival provisioning, insurance stockpiles against famine, or market warehousing, and that only the storerooms'' scale has been demonstrated, not their governance. The skeptics do not deny that temples stored grain. Their claim is that storage capacity by itself cannot distinguish between an economy run by decree and one that merely gathered in the same buildings.", "credited_answers": ["Everyone agrees ancient temples stored large amounts of grain; the dispute is whether big storehouses prove a centrally commanded economy or are equally consistent with voluntary and market uses."], "explanation": "The big ideas your summary has to carry: (1) camp one: storehouses show priestly command economies · (2) camp two: capacity alone cannot show governance · (3) shared ground: the storage itself is real. Named traps: Too narrow: \"Archaeologists found storerooms next to temples.\" Topic-only: \"Scholars debate ancient economies.\"", "category": "Tier 3: Two camps, and the summary must keep who-thinks-what"}, {"order": 12, "prompt": "Among linguists who study dying languages, documentation specialists argue that scarce funding should record elderly fluent speakers before their knowledge disappears, since a recorded language can in principle be revived later, while an unrecorded one cannot. Revitalization specialists reply that languages live only in daily use, that archives full of unspoken recordings are cemeteries rather than seed banks, and that the same money spent on children''s immersion programs keeps the language alive without needing revival at all. Each side accuses the other of planning for the wrong future: one for a future where the language has died, the other for a future where it never does.", "credited_answers": ["Documentation linguists want scarce funds spent recording elderly speakers so the language could someday be revived, while revitalization linguists want the money spent keeping children speaking it now, each side planning for a different future."], "explanation": "The big ideas your summary has to carry: (1) camp one: record before knowledge dies; archives enable revival · (2) camp two: fund immersion; use is life, archives are cemeteries · (3) the frame: they disagree about which future to plan for. Named traps: Too narrow: \"Linguists record elderly native speakers.\" Topic-only: \"Experts disagree about saving endangered languages.\"", "category": "Tier 3: Two camps, and the summary must keep who-thinks-what"}, {"order": 13, "prompt": "Estimates of historical famine mortality long depended on chronicles and tax rolls, sources that survive unevenly and that officials had reasons to distort. Demographers have begun instead to read the famines out of later census structure: a birth cohort gutted by starvation and delayed marriages leaves a permanent notch that moves up the age pyramid for a century, and its depth can be measured decades after the event by anyone with reliable census tables. The method does not date famines more precisely than the chronicles do, but it converts their severity from a matter of testimony into a matter of measurement.", "credited_answers": ["Demographers are shifting famine studies from trusting distorted chronicles to measuring the lasting notches famines leave in later census age structures, turning severity from testimony into measurement."], "explanation": "The big ideas your summary has to carry: (1) old method: chronicles and tax rolls, uneven and distorted · (2) new method: cohort notches in census pyramids · (3) the shift''s meaning: severity becomes measurable, though dating does not improve. Named traps: Too narrow: \"Famines leave notches in age pyramids.\" Topic-only: \"Historians study old famines.\"", "category": "Tier 4: The main point is a shift in method or framing, technical vocabulary"}, {"order": 14, "prompt": "Attribution of unsigned paintings once rested on connoisseurship, the trained eye of specialists who judged brushwork and composition and whose verdicts were difficult to challenge because the evidence was, in the end, their own perception. Laboratories have altered the terrain. Pigment chemistry can rule out dates, canvas weave matching can tie pictures to a workshop''s bolt of cloth, and imaging reveals underdrawings that copyists rarely reproduce. The techniques rarely name a painter outright. What they do is redistribute authority: a connoisseur''s attribution must now survive material tests that anyone can repeat, and the eye has become one instrument among several rather than the court of final appeal.", "credited_answers": ["Scientific analysis has shifted painting attribution from resting on connoisseurs'' unchallengeable trained eyes to requiring verdicts that survive repeatable material tests, demoting the eye to one instrument among several."], "explanation": "The big ideas your summary has to carry: (1) old regime: the connoisseur''s perception as final authority · (2) new tools: pigment dating, weave matching, imaging · (3) the shift: authority redistributed to repeatable tests; the eye demoted, not replaced. Named traps: Too narrow: \"Labs can match canvas weave to a workshop.\" Topic-only: \"Science helps identify paintings.\"", "category": "Tier 4: The main point is a shift in method or framing, technical vocabulary"}, {"order": 15, "prompt": "Wildlife censuses once counted what observers could see: animals flushed from transects, nests spotted from aircraft, tracks crossing survey lines. Sampling environmental DNA has begun to invert the logic. A liter of stream water carries genetic traces of everything that shed cells upstream, so presence is now inferred from molecules rather than encounters, and absence of a species becomes a statement about detection thresholds rather than about empty habitat. The change forces a redefinition of the census itself: fieldworkers no longer ask how many animals they found, but how much signal a landscape produces and what fraction of it their methods can recover.", "credited_answers": ["Environmental DNA is changing wildlife censuses from counting animals observers encounter to inferring presence from genetic traces in water, redefining surveys as questions about recoverable signal rather than sightings."], "explanation": "The big ideas your summary has to carry: (1) old method: visual encounter counts · (2) new method: molecular traces in environmental samples · (3) the redefinition: from \"how many did we find\" to \"how much signal can we recover\"; absence becomes a threshold claim. Named traps: Too narrow: \"Stream water contains animal DNA.\" Topic-only: \"There are new ways to count wildlife.\"", "category": "Tier 4: The main point is a shift in method or framing, technical vocabulary"}, {"order": 16, "prompt": "The dating of early metalworking sites long leaned on typology: arrange the recovered tools by shape, assume simple forms precede refined ones, and read the sequence as time. Radiometric methods embarrassed that assumption at site after site, showing refined and crude forms in use simultaneously, sometimes in the same workshop. The response has not been to abandon typology but to reassign its job. Tool shapes are now read as evidence of workshop tradition, trade connection, and intended market, while the calendar is left to laboratory dates. The shapes, in other words, stopped telling time and started telling everything else.", "credited_answers": ["Radiometric dating showed that tool shapes do not track time, so archaeologists reassigned typology from dating sites to revealing workshop traditions, trade, and markets, leaving chronology to the lab."], "explanation": "The big ideas your summary has to carry: (1) old assumption: simple-to-refined shape sequence equals time · (2) the embarrassment: lab dates showed forms coexisting · (3) the reassignment: shapes now evidence tradition/trade/market, not chronology. Named traps: Too narrow: \"Crude and refined tools were used at the same time.\" Topic-only: \"Archaeologists date metalworking sites.\"", "category": "Tier 4: The main point is a shift in method or framing, technical vocabulary"}, {"order": 17, "prompt": "Courts assessing eyewitness identifications historically asked whether the witness was confident, attentive, and honest, treating memory as a recording whose quality those virtues guaranteed. Decades of controlled experiments reframed the question by showing that identification accuracy depends heavily on conditions no witness controls: lighting, distance, stress, the composition of the lineup, and the feedback given afterward. The experiments do not show that eyewitnesses are generally wrong, and confident witnesses are still right more often than hesitant ones. What the research undermines is the inference from sincerity to accuracy, and courts have slowly begun to instruct juries on viewing conditions rather than character.", "credited_answers": ["Research reframed eyewitness reliability as a matter of viewing and lineup conditions rather than witness character, and while witnesses are not generally wrong, sincerity no longer counts as proof of accuracy."], "explanation": "The big ideas your summary has to carry: (1) old frame: confidence and honesty guarantee memory · (2) reframe: accuracy tracks conditions outside the witness''s control · (3) retained concession: witnesses are often right; what falls is the sincerity-to-accuracy inference. Named traps: Too narrow: \"Lineup composition affects identifications.\" Topic-only: \"Eyewitness testimony can be unreliable.\" (Overshoots by dropping the concession.)", "category": "Tier 5: Shift plus a retained concession the summary must keep"}, {"order": 18, "prompt": "Nutrition guidance once ranked dietary fats by their chemistry, condemning saturated varieties wholesale and promoting substitutes with more favorable laboratory profiles. Long-term population studies complicated the ranking by showing that health outcomes track what replaces a discarded fat: swapping it for refined starches yields no benefit, while swapping it for certain plant oils does. The chemistry was not wrong, and some substitutions really are improvements. The revision is in the unit of advice. Foods and their replacements, not molecules in isolation, have become the thing guidance is written about, because a nutrient''s effect proved inseparable from what fills its place at the table.", "credited_answers": ["Nutrition advice shifted from ranking fat molecules to evaluating whole substitutions, because outcomes depend on what replaces a discarded fat, even though the underlying chemistry and some swaps remain valid."], "explanation": "The big ideas your summary has to carry: (1) old unit: molecule-level rankings · (2) complication: outcomes track the replacement, not the removal · (3) retained concession: chemistry holds and some substitutions genuinely help; the change is the unit of advice. Named traps: Too narrow: \"Replacing fat with refined starch does not help.\" Topic-only: \"Nutrition science keeps changing its mind.\" (The cynical overshoot; the paragraph says the opposite.)", "category": "Tier 5: Shift plus a retained concession the summary must keep"}, {"order": 19, "prompt": "Flood control on large rivers was for a century an engineering contest: raise the levees, straighten the channel, move the water through faster. Repeated levee failures shifted the field toward a different accounting, in which the cheapest place to put floodwater is often a farm field purchased for occasional inundation rather than a wall built to exclude the water entirely. Engineered defenses still protect cities, and no one proposes removing them. The change is in what counts as infrastructure: acquired floodplain, wetland easements, and setback levees now appear in project budgets alongside concrete, because the failures showed that exclusion alone was purchasing risk at compound interest.", "credited_answers": ["After repeated levee failures, flood control expanded from pure exclusion engineering to budgeting land that can safely flood as infrastructure, while hard defenses still protect cities."], "explanation": "The big ideas your summary has to carry: (1) old contest: higher levees, faster channels · (2) shift: purchased floodplain and setbacks count as infrastructure · (3) retained concession: engineered defenses remain; exclusion alone compounded risk. Named traps: Too narrow: \"Some farm fields are bought to hold floodwater.\" Topic-only: \"Levees sometimes fail.\"", "category": "Tier 5: Shift plus a retained concession the summary must keep"}, {"order": 20, "prompt": "Histories of literacy long measured it by signatures: count who could sign a parish register, and map reading across a society. Scholars now emphasize that signing was taught after reading and separately from it, so signature counts systematically undercount readers, capturing mostly those schooled long enough to write, and excluding the many taught to read scripture at home who never held a pen. Signature evidence has not been discarded; nothing else survives at comparable scale, and its trends over time remain informative. What changed is the claim it supports: a floor under past literacy rather than an estimate of it.", "credited_answers": ["Because writing was taught after reading, signature counts undercount past readers, so historians now treat them as a floor under literacy rather than an estimate, while still relying on their trends."], "explanation": "The big ideas your summary has to carry: (1) old measure: signatures as literacy · (2) flaw: reading preceded writing, so readers are missed · (3) retained concession: the evidence survives at unmatched scale and still shows trends; its claim is downgraded to a floor. Named traps: Too narrow: \"Many people could read but not sign.\" Topic-only: \"Measuring historical literacy is hard.\"", "category": "Tier 5: Shift plus a retained concession the summary must keep"}, {"order": 21, "prompt": "Early quantitative studies of scientific careers measured productivity by publication counts and found that a small fraction of researchers produced most of the papers, a result read for decades as evidence of rare individual talent. Later work complicated both the measure and the reading. Counting papers weights fields unequally, since publication rates are set by disciplinary custom rather than effort, and the concentration itself proved to be manufactured partly by institutions: early access to equipment, students, and funding compounds, so that small initial differences in opportunity grow into large final differences in output. Talent has not been dismissed as a factor. The revision is subtler: concentration of output is now treated as a joint product of ability and cumulative institutional advantage, and the measure that revealed it is no longer trusted to compare across fields.", "credited_answers": ["The finding that a few scientists produce most papers is now explained as talent compounded by accumulating institutional advantage rather than rare ability alone, and raw publication counts are no longer trusted across fields."], "explanation": "The big ideas your summary has to carry: (1) original finding and reading: concentrated output proves rare talent · (2) first correction: the measure is field-biased · (3) second correction: institutions compound small early advantages · (4) retained role for talent in a joint explanation. Named traps: Too narrow: \"Some fields publish more papers than others.\" Topic-only: \"A few scientists write most papers.\" (States the finding while missing the reinterpretation, which is the point.)", "category": "Tier 6: Double contrast, abstract subject, maximum load"}, {"order": 22, "prompt": "Classic accounts of trade before state coinage assumed barter, with money arising to solve the awkwardness of matching wants. Records from early cities support a different sequence: temple and palace bookkeepers denominated debts in standard quantities of grain and silver long before coins circulated, and most exchange took the form of credit entries against future harvests. Coinage, when it arrived, served less to enable trade than to let rulers pay soldiers and collect taxes in a medium they controlled. Barter was real, but it flourished mainly between strangers and at frontiers, where no ledger bound the parties. On this account money''s origin is administrative rather than commercial, and the barter story survives as a special case rather than a beginning.", "credited_answers": ["Evidence from early cities suggests money began as administrative accounting for debts, with coins serving state payment and taxation, while barter was a frontier special case rather than the origin of trade."], "explanation": "The big ideas your summary has to carry: (1) classic story: barter first, money as its fix · (2) documented sequence: ledger credit in standard units preceded coins · (3) coinage''s actual role: state payment and taxation · (4) barter retained as a real but special case among strangers. Named traps: Too narrow: \"Bookkeepers recorded debts in grain and silver.\" Topic-only: \"Money has a long history.\"", "category": "Tier 6: Double contrast, abstract subject, maximum load"}, {"order": 23, "prompt": "Sleep research first treated the sleeping brain as idle, then, after recordings revealed intense nocturnal activity, as busy with a single master task, with memory consolidation the leading candidate. Both frames now look too simple. The sleeping brain runs distinct programs in different stages, and interventions that disrupt one stage impair some functions while leaving others intact: slow-wave disruption degrades factual recall but spares motor learning, while dream-stage suppression does something closer to the reverse. Consolidation has not been dethroned as one genuine function among several. What has been abandoned is the search for the purpose of sleep, in favor of mapping which stage serves which function, on the view that sleep is a schedule of maintenance operations rather than a single process with a single point.", "credited_answers": ["Sleep science has moved from asking what sleep is for to mapping which sleep stage serves which function, treating sleep as a schedule of distinct maintenance programs, with memory consolidation kept as one function among several."], "explanation": "The big ideas your summary has to carry: (1) frame one: idle brain · (2) frame two: one master task (consolidation) · (3) current view: stage-specific functions shown by selective disruption · (4) retained: consolidation is real but not the single purpose; the single-purpose question itself is abandoned. Named traps: Too narrow: \"Disrupting slow-wave sleep hurts factual recall.\" Topic-only: \"Scientists study why we sleep.\"", "category": "Tier 6: Double contrast, abstract subject, maximum load"}, {"order": 24, "prompt": "Antitrust doctrine spent half a century anchored to a single question, whether conduct raised prices for consumers, a standard prized for making enforcement predictable and economic rather than political. Critics now press two distinct objections that are often conflated. The first accepts the consumer-price frame and argues the measurements were done badly, since quality degradation, data extraction, and forgone innovation are price-like harms the cases ignored. The second rejects the frame itself, holding that concentrated private power injures suppliers, workers, and the openness of markets in ways no consumer metric captures. Defenders answer that the first critique is absorbable and the second is a mandate for judges to weigh incommensurable values without a scale. The live dispute is therefore not whether the old standard missed harms. It is whether the remedy is better measurement inside the frame or replacement of the frame, at the cost of the predictability that made the standard attractive.", "credited_answers": ["Everyone now grants the consumer-price standard missed real harms; the fight is between fixing its measurements within the frame and replacing the frame to reach power-based harms, at the price of the predictability that justified it."], "explanation": "The big ideas your summary has to carry: (1) old anchor: consumer prices, prized for predictability · (2) critique one: right frame, bad measurement (quality, data, innovation) · (3) critique two: wrong frame, power harms beyond consumers · (4) defenders'' reply and the real dispute: repair vs replace, with predictability as the stake. Named traps: Too narrow: \"Antitrust cases ignored data extraction.\" Topic-only: \"People disagree about antitrust law.\" (Also trap: presenting the two critiques as one, which the paragraph explicitly warns against conflating.)", "category": "Tier 6: Double contrast, abstract subject, maximum load"}]'::jsonb,
    NULL,
    NULL,
    NULL
  ),
  (
    'spot-the-callback',
    'Spot the Callback',
    'Say what the marked phrase is pointing back to',
    '{"coach": {"drill": "a callback drill: a phrase in the second paragraph refers back to an idea in the first paragraph in different words, and the student has to say which idea and what it means", "rubric": ["Judge two things separately. First, did the student point at the correct earlier idea, on the correct side of any debate. Second, did they actually restate its content.", "Naming a location is not an answer. ''The thing in the first paragraph about the drums'' identifies where the idea is and says nothing about what it is.", "Where the paragraph sets two views against each other, pointing at the wrong side is wrong even if the topic is right.", "On the harder items the phrase carries the author''s judgment. A student who gets the topic but lands on the wrong valence has not finished the job.", "Where the author''s note names a planted near-miss, a student who chose it should be told what separates it from the real referent rather than simply marked down."], "partial_rule": "Mark ''partial'' when the student points at the right earlier idea but does not translate it, restating only its location or its topic. Mark ''incorrect'' when they point at the wrong idea, at a planted near-miss, or at the opposing side of the debate."}, "tagline": "That, this, the second one. Every one of them points backward.", "task": "The marked phrase refers back to an idea from the first paragraph. Tell me which idea it is, and say what that idea actually claims.", "rules": ["Start with the phrase itself. A demonstrative like that or this is a signal that the author is reaching backward.", "Decode the phrase''s parts before you go looking. Cartographic is about mapmaking, insulation is protection, so cartographic insulation is protection through mapmaking.", "Then find the idea in the first paragraph that the phrase is standing in for.", "Saying where the idea is does not count. Say what it claims.", "If the first paragraph holds two opposed views, decide which one the phrase is pointing at before you answer."], "worked_example": {"statement": "The club spent two seasons building around a high defensive line that squeezed play into the opposition half. It worked against sides that wanted to pass out from the back. It failed badly against anyone willing to kick long.\n\nThe new manager has abandoned \"that compressed shape\" and drops the back four twenty yards deeper.", "credited_answers": ["The high defensive line that squeezed play into the opposition half."], "explanation": "That signals a backward reference. Compressed shape is new wording for the same thing the first paragraph described as a high line squeezing play into the opposition half. Saying the old tactic would point in the right direction without translating anything, which is why it is only a near miss."}, "answer_label": "Your answer", "answer_placeholder": "Name the idea the marked phrase points back to, and what it says…"}'::jsonb,
    'free-text',
    '[{"order": 1, "prompt": "The city''s civic centre was built in the 1960s with a raised concrete plaza separating the building from the street. Planners at the time described the plaza as a dignified approach. Pedestrians described it as a wind tunnel they crossed as fast as they could.\n\nThe current renovation removes **\"that elevated forecourt\"** and brings the entrance down to pavement level.", "credited_answers": ["the raised concrete plaza between the building and the street."], "explanation": "Topic: Architecture. Translation must say: a raised plaza that held the entrance away from the street. Near-miss: none planted at this rung. `partial`: \"the plaza\" with no content, or \"the thing being removed.\"", "category": "Q1: near-synonym swap"}, {"order": 2, "prompt": "Conservators argued for years that the spalling terracotta panels should be swapped for cast replicas. The architects who ran the survey disagreed. A panel losing its surface, they held, still carries the mould marks that date the building, and a replica carries none.\n\n**\"That position\"** has now been written into the listing, and no panel may be replaced while its mould marks survive.", "credited_answers": ["the architects'' claim that a decaying original still carries datable mould marks a replica cannot."], "explanation": "Topic: Architecture. Translation must name *which* claim and *whose*. Near-miss: the conservators'' replacement argument, stated first and at equal length. `partial`: \"the architects'' view\" without saying what it was.", "category": "Q2: demonstrative compression"}, {"order": 3, "prompt": "For a century the museum showed its marbles as art and its plaster casts as teaching aids, shelved in an unlabelled basement corridor. Recent scholarship treats the casts as objects in their own right, with their own makers, their own damage, and their own history of handling.\n\n**\"This rehabilitation of the copy\"** is why the basement corridor is being relabelled as a gallery.", "credited_answers": ["the recent scholarly move to treat casts as objects worth study in themselves."], "explanation": "Topic: Architecture. Translation must carry the approving valence: the copy has been promoted, not merely discussed. Near-miss: \"the marbles shown as art.\" `partial`: \"new research on casts,\" which loses the promotion.", "category": "Q3: nominalized swap, valence matters"}, {"order": 4, "prompt": "The 1890s arcade was glazed with one continuous sheet of rolled glass along its whole length, which the builders praised as an unbroken sky. Shopkeepers underneath complained of glare and heat. Later arcades in the same city broke the glazing into bays with solid ribs between them, and their tenants stayed longer.\n\nThe trust''s report attributes the arcade''s decline to **\"that fenestral overreach\"** and recommends reinstating the bays.", "credited_answers": ["the single continuous glass roof."], "explanation": "Topic: Architecture. Decode: *fenestral* is to do with glazing and windows; *overreach* is going too far. So: glazing taken too far. Translation must name the unbroken sheet, not its effects. Near-misses planted: the glare and heat (the consequence), and the later arcades'' bays (the remedy). `partial`: \"the glare problem.\"", "category": "Q4: re-categorization with a vocabulary decode"}, {"order": 5, "prompt": "A school of postwar planners held that a neighbourhood''s health could be read off one number, its density, and that raising the number would raise the health. Critics at the time noted that two districts at identical densities behaved nothing alike, because one had shops along the ground floor and the other had blank walls. The planners'' answer was to build to the target density and wait.\n\nThe current masterplan is written by people who watched **\"that arithmetic faith\"** empty three districts, and it specifies ground-floor use before it specifies density at all.", "credited_answers": ["the postwar planners'' belief that density alone determines a neighbourhood''s health, so raising density raises health."], "explanation": "Topic: Architecture. Attribution required: the planners'', not the critics''. The precise mistaken use: treating a single number as sufficient, not \"using numbers.\" Near-misses: density as a topic; the critics'' ground-floor observation. `partial`: \"the planners'' focus on density,\" which names the topic and misses that the error was treating it as the whole story.", "category": "Q5: evaluative metaphor, whole position"}, {"order": 6, "prompt": "The club spent two seasons building around a high defensive line that squeezed play into the opposition half. It worked against sides that wanted to pass out from the back. It failed badly against anyone willing to kick long.\n\nThe new manager has abandoned **\"that compressed shape\"** and drops the back four twenty yards deeper.", "credited_answers": ["the high defensive line squeezing play into the opposition half."], "explanation": "Topic: Sport. Translation must say what the shape was, not just that it existed. `partial`: \"the old tactic.\"", "category": "Q1: near-synonym swap"}, {"order": 7, "prompt": "The analytics staff argued the striker''s finishing was fine and his service was the problem. The coaching staff read the same numbers the other way: the chances were arriving, and he was missing them.\n\n**\"This second reading\"** is what the transfer list reflects, and it is the striker who has been listed.", "credited_answers": ["the coaching staff''s reading, that the chances were arriving and the striker was missing them."], "explanation": "Topic: Sport. Near-miss: the analytics view, given first. `partial`: \"the coaches'' opinion.\"", "category": "Q2: demonstrative compression"}, {"order": 8, "prompt": "Distance coaches once treated the long slow run as the whole foundation of training, and anything faster as garnish. Physiologists pushed back, showing that easy volume develops one system and leaves another untouched, and that runners on volume alone plateau within two seasons.\n\n**\"That physiological correction\"** is why modern programmes put two hard sessions inside an otherwise easy week.", "credited_answers": ["the physiologists'' finding that easy volume alone develops one system, leaves another untouched, and produces a plateau."], "explanation": "Topic: Sport. Valence: the physiologists are being credited. Near-miss: the old coaching orthodoxy. `partial`: \"what scientists said about training.\"", "category": "Q3: nominalized swap, valence matters"}, {"order": 9, "prompt": "The federation ranks teams by a rating that adds a fixed bonus for playing away and subtracts nothing for the quality of the opposition. Smaller nations quickly learned to schedule away fixtures against weak sides. Their ratings climbed for two years while their results against ranked opponents got worse.\n\nThe review calls the whole episode **\"that incentive myopia\"** and rewrites the formula around opposition strength.", "credited_answers": ["the rating formula''s fixed away bonus with no adjustment for opposition quality."], "explanation": "Topic: Sport. Decode: *myopia* is short-sightedness; an incentive that fails to see past its own immediate effect. Translation must name the formula''s defect, not the behaviour it produced. Near-misses: the scheduling behaviour of small nations, and the worsening results. `partial`: \"teams gaming the rankings,\" which describes the symptom.", "category": "Q4: re-categorization with a vocabulary decode"}, {"order": 10, "prompt": "One tradition of coaching holds that a player''s ceiling is fixed early and the job is to identify it, so squads are cut young and the cut is treated as information. Its critics point out that the players cut at sixteen and the players kept differ mostly in birth month, and that late-born players who survive outperform the others by twenty-two. The tradition''s response has been to cut earlier.\n\nThe academy''s new director was one of the players released at sixteen, and she has built her whole intake policy against **\"that early verdict\"**.", "credited_answers": ["the coaching tradition''s belief that a player''s ceiling is fixed early, making an early cut a reliable read."], "explanation": "Topic: Sport. Attribution: the tradition''s, not the critics''. The precise mistaken use: treating the early cut as information about ceiling. Near-misses: the birth-month finding; the fact of being released. `partial`: \"cutting players young,\" which is the practice and not the belief that licensed it.", "category": "Q5: evaluative metaphor, whole position"}, {"order": 11, "prompt": "The estuary restoration began by breaching the seawall in three places and letting the tide back onto two hundred hectares of former pasture. Salt marsh re-established within four years. Waders returned in the fifth.\n\n**\"That deliberate flooding\"** is now the template for six other sites on the same coast.", "credited_answers": ["breaching the seawall to let the tide back onto former pasture."], "explanation": "Topic: Ecology. Translation must include the intent and the mechanism. `partial`: \"the flooding.\"", "category": "Q1: near-synonym swap"}, {"order": 12, "prompt": "Foresters proposed removing the standing deadwood to reduce fire load. The entomologists on the panel objected that the deadwood holds the beetle assemblage the woodpeckers feed on, and that a stand cleared of it goes quiet within a decade.\n\n**\"That objection\"** is why the management plan now leaves every trunk over forty centimetres standing.", "credited_answers": ["the entomologists'' claim that deadwood holds the beetle assemblage the woodpeckers depend on, so clearing it silences the stand."], "explanation": "Topic: Ecology. Near-miss: the fire-load rationale. `partial`: \"the entomologists disagreed.\"", "category": "Q2: demonstrative compression"}, {"order": 13, "prompt": "Reserve design was governed for decades by a rule that one large protected area always beats several small ones of the same total size. Field surveys through the 1990s kept finding the opposite in fragmented farmland, where several small reserves held more species between them than one large block did.\n\n**\"This inversion of the old rule\"** is what the county''s scattered reserve network was built on.", "credited_answers": ["the survey finding that in fragmented farmland several small reserves outperform one large block."], "explanation": "Topic: Ecology. Valence: the old rule is being displaced. Near-miss: the old single-large rule itself. `partial`: \"research on reserve size.\"", "category": "Q3: nominalized swap, valence matters"}, {"order": 14, "prompt": "The lake''s recovery programme measured success by total fish biomass, which rose every year for six years. Almost all of the rise was one introduced species that tolerates low oxygen. The native community that the programme existed to protect kept contracting underneath the rising total.\n\nThe audit blames **\"that aggregative blindness\"** and rewrites the target around native species richness.", "credited_answers": ["measuring success by total fish biomass, a single aggregate that hid the composition underneath."], "explanation": "Topic: Ecology. Decode: *aggregative* is to do with totals; *blindness* is what the total could not show. Translation must name the metric choice, not the outcome. Near-misses: the introduced species; the contracting natives. `partial`: \"the invasive fish.\"", "category": "Q4: re-categorization with a vocabulary decode"}, {"order": 15, "prompt": "A strand of restoration thinking holds that an ecosystem has one correct prior state, that this state can be read off a historical baseline, and that the job is to return the system to it. Its critics observe that the chosen baseline is almost always the earliest date with good records rather than any ecologically meaningful moment, and that the climate the baseline formed under no longer exists. Practitioners in the tradition have responded by pushing the baseline further back.\n\nThe catchment''s new plan was written by an ecologist who spent a decade failing to hold a river to **\"that documentary ideal\"**, and it sets targets in terms of function rather than composition.", "credited_answers": ["the restorationist belief that a single correct prior state exists, can be read from a historical baseline, and should be restored."], "explanation": "Topic: Ecology. Attribution: the tradition''s, not the critics''. The precise mistaken use: treating a records-driven baseline as *the* correct state. Near-misses: the climate-has-changed point (the critics''); historical records as a topic. `partial`: \"restoring rivers to how they used to be,\" which loses that the error is in where the target comes from.", "category": "Q5: evaluative metaphor, whole position"}, {"order": 16, "prompt": "The novel was published in monthly parts, and each part had to end on a hook strong enough to sell the next one. The chapter breaks in the modern single volume fall exactly where those hooks were. Readers who meet it as a book often find the pacing strange.\n\n**\"That serial rhythm\"** is invisible on the shelf and audible on every page.", "credited_answers": ["the monthly part-publication that forced a hook at the end of each instalment."], "explanation": "Topic: Literature. `partial`: \"the way it was published.\"", "category": "Q1: near-synonym swap"}, {"order": 17, "prompt": "One editor argued the manuscript''s inconsistencies were authorial and should stand. The other held that a scribe copying at speed produces exactly this pattern of error, and that preserving it preserves the scribe rather than the author.\n\n**\"The second argument\"** carried the volume, and the edition silently corrects sixty readings.", "credited_answers": ["the claim that the pattern of error is what a fast-copying scribe produces, so keeping it preserves the scribe rather than the author."], "explanation": "Topic: Literature. Near-miss: the first editor''s authorial-inconsistency position. `partial`: \"the second editor''s view.\"", "category": "Q2: demonstrative compression"}, {"order": 18, "prompt": "Critics long read the narrator''s flat affect as a failure of characterisation, a writer unable to render feeling. A later generation read the same flatness as the point: a narrator describing a year she cannot yet feel, in the only register available to her.\n\n**\"This reversal of the charge\"** is why the novel is now taught in the same course that once used it as a bad example.", "credited_answers": ["the later reading that the flat affect is deliberate and characterising rather than a failure."], "explanation": "Topic: Literature. Valence: a defence, not a neutral alternative. Near-miss: the original charge of failed characterisation. `partial`: \"critics changed their minds.\"", "category": "Q3: nominalized swap, valence matters"}, {"order": 19, "prompt": "The prize''s judges are given the full list in January and asked to submit a shortlist in March. Almost every shortlisted book in twenty years has been published between September and December. Publishers now schedule their strongest titles into that window and their others outside it.\n\nThe trustees'' report names **\"that recency artefact\"** and moves the reading period to a rolling twelve months.", "credited_answers": ["the compressed January-to-March judging window that leaves recently published books freshest in judges'' minds."], "explanation": "Topic: Literature. Decode: *recency* is the nearness in time; an *artefact* is a distortion produced by the method rather than the thing measured. Translation must name the judging schedule, not publisher behaviour. Near-misses: the autumn publication pattern; publishers'' scheduling. `partial`: \"books published in autumn win,\" which is the symptom.", "category": "Q4: re-categorization with a vocabulary decode"}, {"order": 20, "prompt": "A durable school of criticism holds that a work''s meaning is settled by what its author intended, that the intention is recoverable from letters and drafts, and that a reading unsupported by that record is simply wrong. Its opponents point out that drafts record what an author tried, not what the finished work does, and that the letters of working writers are full of intentions the books abandon. The school''s reply has been to widen the archive.\n\nThe editor of the new companion spent four years in a novelist''s papers and came out of them arguing against **\"that archival certainty\"**, and the volume prints six incompatible readings without ranking them.", "credited_answers": ["the school''s belief that authorial intention settles meaning and is recoverable from the documentary record, making unsupported readings wrong."], "explanation": "Topic: Literature. Attribution: the school''s, not its opponents''. The precise mistaken use: treating the archive as decisive about meaning, not merely informative. Near-misses: the drafts-record-attempts point (the opponents''); archives as a topic. `partial`: \"the idea that the author''s intention matters,\" which is far weaker than the position being rejected.", "category": "Q5: evaluative metaphor, whole position"}]'::jsonb,
    NULL,
    NULL,
    NULL
  ),
  (
    'read-recall-colour',
    'Read, Recall, Colour',
    'Read a chunk, lose it, and say it back with every detail intact',
    '{"coach": {"drill": "a spoken recall drill, where the student reads one chunk of a stimulus, loses sight of it, and says it back from memory in her own words", "rubric": ["Judge by meaning, never by wording. Her own words are required here, so a good recall will never match the chunk''s phrasing. Equivalent phrasing carries the detail.", "Order is free. She is encouraged to deliver the ideas out of the order she read them in, and reordering must never cost her anything.", "Casual, unpolished, laughing delivery is expected. Never mark down for style, length or fluency.", "A detail merely gestured at is not carried. Naming the topic is not the same as saying what was claimed about it.", "Numbers, names, dates, quantities and connecting words are each their own detail. Never treat one as carried because the sentence around it was."], "partial_rule": "Mark ''partial'' when the retelling is real but at least one detail went missing, which is the drill''s ordinary state. Mark ''incorrect'' only when the response is a gist or a topic label rather than a retelling."}, "tagline": "Read it once. Then say it back with nothing on the screen.", "task": "Say the chunk back from memory, out loud, in your own words, keeping every detail.", "rules": ["Read the chunk once. When you tap Got it, it disappears, and it is not coming back.", "Say it back out loud, in your own words, the way you would tell a friend. Out of order is fine. Laughing is fine.", "Keep everything. Names, numbers, dates and small connecting words all count. This is not a summary.", "Then react to it out loud. Any reaction counts, nothing is scored, and you cannot move on without one.", "Every few chunks you will be asked to say back everything so far, still with nothing on the screen."], "briefing": {"lede": "This is the drill that decides whether you still have the stimulus by the time you reach the answer choices.", "sections": [{"heading": "Understanding it is not the same as holding it.", "body": ["You can follow a stimulus perfectly, sentence by sentence, and still get down to answer choice C with almost nothing left. That is not a comprehension problem. It is a retention problem, and it is the one this drill was built for.", "Understanding is necessary for everything and sufficient for nothing. If the argument is not still with you while you work the answers, your understanding never gets the chance to help."]}, {"heading": "The text disappears, and that is the point.", "body": ["Once you tap Got it, the chunk is gone and it is not coming back.", "If you could glance back, you would, and then none of this is recall. You are just reading it a second time, and you will start handing it back in their words instead of yours. Taking the text away is the only thing that keeps the stage honest."]}, {"heading": "Say it the way you would tell a friend.", "body": ["Out loud, in your own words, in whatever order it comes out. Casual is fine. Stumbling is fine. Laughing is fine.", "These stimuli are often built to be hard to hold onto. Your job is to cut one down to size and say the same thing in plain language. Saying a complicated thing simply is the whole skill."]}, {"heading": "Plain is not the same as short.", "body": ["Keep everything. Names, numbers, dates, quantities, and the small connecting words that tell you how two ideas are related. Each one is its own detail, and none of them are safe to drop because the sentence around them survived.", "The pull is always toward giving the gist and moving on. But you cannot know which parts mattered until after you have read it, so filtering on the way through mostly means quietly throwing out the piece you were going to need.", "You already know what this sounds like from the other side. When someone repeats your problem back to you and half of it is missing, you can tell straight away that they were not really listening. Say it back the way you would want it said back to you."]}, {"heading": "Then react to it, and mean it.", "body": ["After the chunk is back, say what you actually think of it. Anything genuine counts, none of it is scored, and you cannot move on without it.", "One standard: if your reaction would fit any sentence on the test, it is not a reaction. \"Okay, makes sense\" is not doing anything. The moment you push on a claim, notice what it quietly takes for granted, or connect it to something you already know, you have started doing the question rather than waiting for it."]}, {"heading": "The load grows on purpose.", "body": ["Every few chunks you will be asked for everything so far, still with nothing on the screen. First one chunk, then the first two together, then the whole thing.", "That is the part almost nobody makes themselves do on paper, and it is the part that matters most. The answer choices arrive after the entire stimulus, never after one sentence of it."]}, {"heading": "Go slowly here. It is the fast route.", "body": ["What you intend on the way in decides what you keep. Read only to be finished and your brain will happily cooperate, sliding past anything that feels like a speed bump, including the clause the question turns on.", "Nothing here is timed. Take the pause, sit in the part where you cannot remember what came next, and let yourself be slow while you are slow. Speed arrives later, and it comes from having done this properly, not from having done it faster."]}], "closer": "Expect the first few to feel slow and a little ridiculous. That is what this feels like when it is working."}, "answer_label": "What you said", "answer_placeholder": "Say the chunk back from memory, keeping every detail…"}'::jsonb,
    'spoken-recall',
    '[{"order": 1, "prompt": "In its coverage of a controversy regarding a proposal to build a new freeway, a television news program showed interviews with several people who would be affected by the proposed freeway. Of the interviews shown, those conducted with people against the new freeway outnumbered those conducted with people for it two to one. The television program is therefore biased against the proposed freeway.", "credited_answers": ["So people are arguing about whether to put in a new freeway, and a TV news show did a segment on it. They talked to a handful of folks who would have to live with it either way. Out of the clips they actually ran, there were twice as many from people who don''t want it as from people who do. So the point being made is that the show is slanted against the freeway."], "explanation": "The details your recall has to carry, by chunk: (1) There is a controversy. · The controversy is over a proposal to build a new freeway. · A television news program was covering it. · The program showed interviews. · The interviews were with several people. · Those people would be affected by the proposed freeway. (2) This is about the interviews the program actually showed. · Some of the people interviewed were against the new freeway. · Some of the people interviewed were for it. · The against interviews outnumbered the for interviews. · The margin was two to one. (3) This is the conclusion drawn from what came before it. · The claim is about the television program. · The program is biased. · The bias is against the proposed freeway. Named misses: **Gist.** \"A news show interviewed people about a freeway and it came out biased.\" Fails details kept: no ratio, no who was affected, no controversy. This is the common one and it is why \"complete, not a gist\" is stated first. **Verbatim.** Saying \"those conducted with people against the new freeway outnumbered those conducted with people for it two to one\" back word for word. Passes details kept and fails own words. She has not retold it, she has quoted it, which is the habit rereading produces. **Pieces come apart.** \"There was a controversy, some people were interviewed, two to one, the program is biased.\" Every detail is technically present and nothing supports anything else. Fails how the pieces fit: the ratio is no longer the reason for the bias claim, it is just a number sitting there.", "category": "Argument: a conclusion drawn from a count", "chunks": [{"n": 1, "text": "In its coverage of a controversy regarding a proposal to build a new freeway, a television news program showed interviews with several people who would be affected by the proposed freeway.", "details": [{"n": 1, "text": "There is a controversy."}, {"n": 2, "text": "The controversy is over a proposal to build a new freeway."}, {"n": 3, "text": "A television news program was covering it."}, {"n": 4, "text": "The program showed interviews."}, {"n": 5, "text": "The interviews were with several people."}, {"n": 6, "text": "Those people would be affected by the proposed freeway."}]}, {"n": 2, "text": "Of the interviews shown, those conducted with people against the new freeway outnumbered those conducted with people for it two to one.", "details": [{"n": 1, "text": "This is about the interviews the program actually showed."}, {"n": 2, "text": "Some of the people interviewed were against the new freeway."}, {"n": 3, "text": "Some of the people interviewed were for it."}, {"n": 4, "text": "The against interviews outnumbered the for interviews."}, {"n": 5, "text": "The margin was two to one."}]}, {"n": 3, "text": "The television program is therefore biased against the proposed freeway.", "details": [{"n": 1, "text": "This is the conclusion drawn from what came before it."}, {"n": 2, "text": "The claim is about the television program."}, {"n": 3, "text": "The program is biased."}, {"n": 4, "text": "The bias is against the proposed freeway."}]}], "cumulative_after": [2, 3]}]'::jsonb,
    NULL,
    NULL,
    NULL
  ),
  (
    'read-recall-colour-pt1-s3',
    'Read, Recall, Colour · PT1 Section 3',
    'A whole section, out loud, against the clock',
    '{"tagline": "Read it, say it back, react to it. Then the stimulus disappears and you say the whole argument back from memory.", "task": "Work through the stimulus out loud, a piece at a time. When you have got all of it, press space. The text goes away, and you say the entire argument back from memory.", "rules": ["Everything here is out loud. The whole section records in one take, and it never pauses.", "Read silently, about a sentence at a time. When you are not sure how much to take on, take less.", "Look away and say it back in your own words. Then react to it. Both out loud.", "Keep going like that through the whole stimulus. You pick the pieces. Nothing on screen is counting them.", "Press space when you have got all of it. The stimulus vanishes and stays gone. Now say the whole argument back from memory, with every detail you can hold.", "Press space again and the next one loads. No breaks, no going back, all the way to the end."], "briefing": {"lede": "Worth reading properly once. After that, skim the rules above and go.", "sections": [{"heading": "You can understand every sentence and still arrive with nothing.", "body": ["You follow a stimulus, sentence by sentence, and it all makes sense as it goes. Then you get down to answer choice C and realise you are holding almost none of it. That is not a comprehension problem. It is a retention problem, and it is the one this drill was built for.", "Understanding is necessary for everything and sufficient for nothing. If the argument is not still with you while you work the answers, your understanding never got the chance to help.", "Most of what you call reading is built for getting to the end. Scanning names. Dropping the connecting words. Turning a list of three into one label. That is a fine way to read a phone bill. It is a bad way to read something that is about to ask you for every detail back."]}, {"heading": "What you actually do.", "body": ["Three beats through the stimulus, then a fourth once you have got all of it. You decide how much to take on at a time, and nothing on the screen is tracking where you are.", "Space is the only key, and you press it twice per stimulus. The first press takes the text away and asks you for the whole argument from memory. The second press moves you to the next stimulus. Nothing advances on its own, so a pause to think costs you nothing but the clock."], "steps": [{"label": "Read it.", "body": "Intake only. Nothing comes back out yet. Take on about a sentence, with full intonation so every word gets its weight. When you are unsure how much to take, take less. What gets lost when you grab too much is always the front of it."}, {"label": "Say it back.", "body": "Look away from the screen and say it back in your own words, out loud, like you are telling a friend what it said. Out of order is fine. Casual is fine. Laughing is fine."}, {"label": "Colour it.", "body": "React. A doubt, a question, an example, a joke, a feeling. One or two seconds is plenty. It does not have to be clever, it has to be yours."}, {"label": "The Recall.", "body": "Press space. The stimulus disappears and does not come back. Now say the entire argument back from memory, out loud, with every detail you can still hold. This is the part that gets scored."}]}, {"heading": "Simpler is not the same as shorter.", "body": ["Do not give back the gist, or the summary, or the important parts. You cannot know which parts were important until you have read the whole thing, so filtering on the way through mostly means quietly throwing out the piece you were going to need.", "Fewer words is fine when the words cover the same ideas. Fewer ideas is not. The names, the numbers, and the small words carrying the load, all, most, only, probably, they either come back or they do not.", "**Efficiency is never a licence to leave information out.**"]}, {"heading": "You will think you have nothing to say. Everybody does.", "body": ["You will open your mouth to colour something and find nothing there. That lasts about a week.", "It is not that you have no thoughts. It is that nobody has ever asked you for one in the middle of reading before, and the habit takes a few sessions to wake up. Say something obvious on purpose if you have to. \"Okay, sure.\" \"That seems like a stretch.\" \"Who measured that?\" All of those count.", "The reaction is what makes the sentence yours instead of the author''s. Skip it and you are back to repeating words you do not own."]}, {"heading": "Look away. That part is on you.", "body": ["While you are working the stimulus, nothing on the screen hides. The whole thing stays readable, which means the only thing stopping you rereading a line while you say it back is you, looking away from it.", "That is deliberate. Reading while you recall is a one way street with cars coming both ways. It jams. You stop using your memory at all and slide straight back into the author''s exact words instead of finding your own.", "It is also the version that still works on paper, and on test day. A screen that hides the text for you is a crutch that cannot come with you."]}, {"heading": "Twenty-five minutes, and what that number means.", "body": ["The goal is twenty-five minutes for a whole section, and it only counts if every stimulus got recalled, coloured, and given a Read. Finishing early with four of them skipped is not finishing early. If you have extra time on test day, your goal scales with it.", "The clock in the corner counts up, not down. It is there so you can pace a section, and it is deliberately not counting towards zero, because a number falling away in the corner of your eye produces exactly the skating read this drill exists to fix.", "It is not a race. It is the pace at which this stops being a study exercise and starts being how you read under a clock. Go slower while it is new. The speed shows up on its own once the method does."]}], "closer": "One a day holds you steady. The second one is where you improve."}, "coach": {"drill": "a whole Logical Reasoning section run out loud, where the student reads each line of a stimulus, looks away, says it back from memory in her own words, reacts to it, and gives a Read of the whole stimulus before moving to the next one", "rubric": ["Judge by meaning, never by wording. Her own words are required here, so a good recall will never match the line''s phrasing. High overlap with the original is the failure, not the standard.", "Order is free. She is encouraged to deliver the ideas out of the order she read them in, and reordering must never cost her anything.", "Casual, unpolished, laughing delivery is expected. Never mark down for style, length or fluency.", "A detail merely gestured at is not carried. Naming the topic is not the same as saying what was claimed about it.", "Numbers, names, dates, quantities and connecting words are each their own detail. Never treat one as carried because the sentence around it was.", "A reaction that could be pasted onto any other sentence does not count as a colour. Judge whether it engages this content, never whether it is correct or well put.", "Score The Read against the captured key for that stimulus, not against a retelling. A different name for the same move is fine; missing the move is not.", "Silence during a silent read is correct and expected. Only silence inside a recall or a colour counts against her."], "partial_rule": "Mark ''partial'' when the retelling is real but at least one detail went missing, which is the drill''s ordinary state. Mark ''incorrect'' only when the response is a gist or a topic label rather than a retelling."}}'::jsonb,
    'spoken-recall',
    '[{"order": 1, "slug": "PT1_S3_Q1", "prompt": "It is difficult to keep deep wounds free of bacteria. Even strong antibiotics fail to kill the bacteria that live in such wounds. However, many physicians have succeeded in eliminating bacteria from deep wounds by packing the wound with a sweet substance like sugar.", "credited_answers": [], "cumulative_after": [], "explanation": "The details your recall has to carry, by chunk: (1) This is about wounds. · The wounds are deep. · The subject is keeping them free of bacteria. · Doing that is difficult. (2) This is about antibiotics. · The antibiotics are strong ones. · Even the strong ones fail. · What they fail to do is kill the bacteria. · Those bacteria live in such wounds. (3) This is a contrast with what came before. · This is about physicians. · Many of them have succeeded. · What they succeeded at is eliminating bacteria. · The bacteria were eliminated from deep wounds. · They did it by packing the wound. · The wound is packed with a sweet substance. · Sugar is given as the example.", "category": "Resolution", "chunks": [{"n": 1, "text": "It is difficult to keep deep wounds free of bacteria.", "details": [{"n": 1, "text": "This is about wounds."}, {"n": 2, "text": "The wounds are deep."}, {"n": 3, "text": "The subject is keeping them free of bacteria."}, {"n": 4, "text": "Doing that is difficult."}]}, {"n": 2, "text": "Even strong antibiotics fail to kill the bacteria that live in such wounds.", "details": [{"n": 1, "text": "This is about antibiotics."}, {"n": 2, "text": "The antibiotics are strong ones."}, {"n": 3, "text": "Even the strong ones fail."}, {"n": 4, "text": "What they fail to do is kill the bacteria."}, {"n": 5, "text": "Those bacteria live in such wounds."}]}, {"n": 3, "text": "However, many physicians have succeeded in eliminating bacteria from deep wounds by packing the wound with a sweet substance like sugar.", "details": [{"n": 1, "text": "This is a contrast with what came before."}, {"n": 2, "text": "This is about physicians."}, {"n": 3, "text": "Many of them have succeeded."}, {"n": 4, "text": "What they succeeded at is eliminating bacteria."}, {"n": 5, "text": "The bacteria were eliminated from deep wounds."}, {"n": 6, "text": "They did it by packing the wound."}, {"n": 7, "text": "The wound is packed with a sweet substance."}, {"n": 8, "text": "Sugar is given as the example."}]}], "the_read": "What if sugar creates an inhospitable environment for bacteria?", "the_read_type": "R", "questions": [{"citation": "PT1.S3.Q1", "qnum": 1, "question_type": "Resolution", "correct_answer": "A"}]}, {"order": 2, "slug": "PT1_S3_Q2", "prompt": "People who are red/green color-blind cannot distinguish between green and brown. Gerald cannot distinguish between green and brown. Therefore Gerald is red/green color-blind.", "credited_answers": [], "cumulative_after": [], "explanation": "The details your recall has to carry, by chunk: (1) This is about certain people. · Those people are red/green color-blind. · They cannot distinguish between two colors. · The colors are green and brown. (2) This is about a person named Gerald. · Gerald cannot distinguish between two colors. · The colors are green and brown. (3) This is the conclusion. · The conclusion is about Gerald. · It says he is red/green color-blind.", "category": "Parallel Reasoning", "chunks": [{"n": 1, "text": "People who are red/green color-blind cannot distinguish between green and brown.", "details": [{"n": 1, "text": "This is about certain people."}, {"n": 2, "text": "Those people are red/green color-blind."}, {"n": 3, "text": "They cannot distinguish between two colors."}, {"n": 4, "text": "The colors are green and brown."}]}, {"n": 2, "text": "Gerald cannot distinguish between green and brown.", "details": [{"n": 1, "text": "This is about a person named Gerald."}, {"n": 2, "text": "Gerald cannot distinguish between two colors."}, {"n": 3, "text": "The colors are green and brown."}]}, {"n": 3, "text": "Therefore Gerald is red/green color-blind.", "details": [{"n": 1, "text": "This is the conclusion."}, {"n": 2, "text": "The conclusion is about Gerald."}, {"n": 3, "text": "It says he is red/green color-blind."}]}], "the_read": "What if we can''t use bad conditional reasoning? What if many things are sufficient to inhibit someone from distinguishing between green and brown?", "the_read_type": "L", "questions": [{"citation": "PT1.S3.Q2", "qnum": 2, "question_type": "Parallel Reasoning", "correct_answer": "B"}]}, {"order": 3, "slug": "PT1_S3_Q3", "prompt": "The theory of military deterrence was based on a simple psychological truth, that fear of retaliation makes a would-be aggressor nation hesitate before attacking and is often sufficient to deter it altogether from attacking. Clearly, then, to maintain military deterrence, a nation would have to be believed to have retaliatory power so great that a potential aggressor nation would have reason to think that it could not defend itself against such retaliation.", "credited_answers": [], "cumulative_after": [], "explanation": "The details your recall has to carry, by chunk: (1) This is about a theory. · The theory is military deterrence. · It was based on something. · What it was based on is a psychological truth. · That truth is described as simple. (2) This states the truth itself. · It is about fear of retaliation. · That fear makes a nation hesitate. · The nation is a would-be aggressor. · It hesitates before attacking. · The fear is also often sufficient. · It can deter the nation altogether from attacking. (3) This is the conclusion. · The goal is maintaining military deterrence. · A nation would have to be believed to have retaliatory power. · That power has to be extremely great. · The belief is what matters here. · A potential aggressor would have reason to think something. · It would think it could not defend itself. · What it could not defend against is such retaliation.", "category": "Inference", "chunks": [{"n": 1, "text": "The theory of military deterrence was based on a simple psychological truth,", "details": [{"n": 1, "text": "This is about a theory."}, {"n": 2, "text": "The theory is military deterrence."}, {"n": 3, "text": "It was based on something."}, {"n": 4, "text": "What it was based on is a psychological truth."}, {"n": 5, "text": "That truth is described as simple."}]}, {"n": 2, "text": "that fear of retaliation makes a would-be aggressor nation hesitate before attacking and is often sufficient to deter it altogether from attacking.", "details": [{"n": 1, "text": "This states the truth itself."}, {"n": 2, "text": "It is about fear of retaliation."}, {"n": 3, "text": "That fear makes a nation hesitate."}, {"n": 4, "text": "The nation is a would-be aggressor."}, {"n": 5, "text": "It hesitates before attacking."}, {"n": 6, "text": "The fear is also often sufficient."}, {"n": 7, "text": "It can deter the nation altogether from attacking."}]}, {"n": 3, "text": "Clearly, then, to maintain military deterrence, a nation would have to be believed to have retaliatory power so great that a potential aggressor nation would have reason to think that it could not defend itself against such retaliation.", "details": [{"n": 1, "text": "This is the conclusion."}, {"n": 2, "text": "The goal is maintaining military deterrence."}, {"n": 3, "text": "A nation would have to be believed to have retaliatory power."}, {"n": 4, "text": "That power has to be extremely great."}, {"n": 5, "text": "The belief is what matters here."}, {"n": 6, "text": "A potential aggressor would have reason to think something."}, {"n": 7, "text": "It would think it could not defend itself."}, {"n": 8, "text": "What it could not defend against is such retaliation."}]}], "the_read": "What if nations are just conflict averse and fear any aggression, even if they think they can defend themselves if need be?", "the_read_type": "L", "questions": [{"citation": "PT1.S3.Q3", "qnum": 3, "question_type": "Inference", "correct_answer": "D"}]}, {"order": 4, "slug": "PT1_S3_Q4", "prompt": "To the Editor:\n\n   In 1960, an astronomer proposed a mathematical model for determining whether extraterrestrial life exists. It was based on the assumptions that life as we know it could exist only on a planet and that many stars are, like our Sun, orbited by planets. On the basis that there are nine planets in our solar system and one of them has life as we know it, the astronomer predicted that there are as many as one million extraterrestrial civilizations across all solar systems. Yet astronomers to date have not detected even one planet outside our solar system. This indicates that the astronomer’s model is wrong, and life as we know it exists only on the planet Earth.\n\nClay Moltz", "credited_answers": [], "cumulative_after": [], "explanation": "The details your recall has to carry, by chunk: (1) This is addressed to an editor. · This is about the year 1960. · An astronomer proposed something. · What was proposed is a mathematical model. · The model determines whether something exists. · What it is about is extraterrestrial life. (2) The model rested on assumptions. · There is more than one assumption. · The first is about where life could exist. · Life as we know it could exist only on a planet. · The second assumption is about stars. · Many stars are orbited by planets. · Our Sun is given as the comparison. (3) This gives the basis for what follows. · Our solar system has nine planets. · One of those planets has life. · The life is life as we know it. (4) The astronomer made a prediction. · The prediction is about extraterrestrial civilizations. · The number is one million. · That is stated as an upper figure. · The civilizations are across all solar systems. (5) This is a contrast with what came before. · This is about astronomers. · They have not detected any planet. · Not even one has been detected. · The planets in question are outside our solar system. · This is true as of the time of writing. (6) This is the conclusion. · It says the astronomer''s model is wrong. · It makes a second claim as well. · Life as we know it exists in only one place. · That place is the planet Earth. (7) This is the signature at the end. · The writer''s first name is Clay. · The writer''s last name is Moltz.", "category": "Weaken", "chunks": [{"n": 1, "text": "To the Editor: In 1960, an astronomer proposed a mathematical model for determining whether extraterrestrial life exists.", "details": [{"n": 1, "text": "This is addressed to an editor."}, {"n": 2, "text": "This is about the year 1960."}, {"n": 3, "text": "An astronomer proposed something."}, {"n": 4, "text": "What was proposed is a mathematical model."}, {"n": 5, "text": "The model determines whether something exists."}, {"n": 6, "text": "What it is about is extraterrestrial life."}]}, {"n": 2, "text": "It was based on the assumptions that life as we know it could exist only on a planet and that many stars are, like our Sun, orbited by planets.", "details": [{"n": 1, "text": "The model rested on assumptions."}, {"n": 2, "text": "There is more than one assumption."}, {"n": 3, "text": "The first is about where life could exist."}, {"n": 4, "text": "Life as we know it could exist only on a planet."}, {"n": 5, "text": "The second assumption is about stars."}, {"n": 6, "text": "Many stars are orbited by planets."}, {"n": 7, "text": "Our Sun is given as the comparison."}]}, {"n": 3, "text": "On the basis that there are nine planets in our solar system and one of them has life as we know it,", "details": [{"n": 1, "text": "This gives the basis for what follows."}, {"n": 2, "text": "Our solar system has nine planets."}, {"n": 3, "text": "One of those planets has life."}, {"n": 4, "text": "The life is life as we know it."}]}, {"n": 4, "text": "the astronomer predicted that there are as many as one million extraterrestrial civilizations across all solar systems.", "details": [{"n": 1, "text": "The astronomer made a prediction."}, {"n": 2, "text": "The prediction is about extraterrestrial civilizations."}, {"n": 3, "text": "The number is one million."}, {"n": 4, "text": "That is stated as an upper figure."}, {"n": 5, "text": "The civilizations are across all solar systems."}]}, {"n": 5, "text": "Yet astronomers to date have not detected even one planet outside our solar system.", "details": [{"n": 1, "text": "This is a contrast with what came before."}, {"n": 2, "text": "This is about astronomers."}, {"n": 3, "text": "They have not detected any planet."}, {"n": 4, "text": "Not even one has been detected."}, {"n": 5, "text": "The planets in question are outside our solar system."}, {"n": 6, "text": "This is true as of the time of writing."}]}, {"n": 6, "text": "This indicates that the astronomer’s model is wrong, and life as we know it exists only on the planet Earth.", "details": [{"n": 1, "text": "This is the conclusion."}, {"n": 2, "text": "It says the astronomer''s model is wrong."}, {"n": 3, "text": "It makes a second claim as well."}, {"n": 4, "text": "Life as we know it exists in only one place."}, {"n": 5, "text": "That place is the planet Earth."}]}, {"n": 7, "text": "Clay Moltz", "details": [{"n": 1, "text": "This is the signature at the end."}, {"n": 2, "text": "The writer''s first name is Clay."}, {"n": 3, "text": "The writer''s last name is Moltz."}]}], "the_read": "What if just because they haven''t yet detected life on another planet, that doesn''t mean it''s impossible?", "the_read_type": "L", "questions": [{"citation": "PT1.S3.Q4", "qnum": 4, "question_type": "Weaken", "correct_answer": "C"}]}, {"order": 5, "slug": "PT1_S3_Q5", "prompt": "If Max were guilty, he would not ask the police to investigate. Therefore, his asking the police to investigate shows that he is not guilty.", "credited_answers": [], "cumulative_after": [], "explanation": "The details your recall has to carry, by chunk: (1) This is a conditional statement. · It is about a person named Max. · The condition is Max being guilty. · The result concerns asking the police. · He would not ask them to investigate. (2) This is the conclusion. · It is drawn from what came before. · Max did ask the police to investigate. · That asking is treated as showing something. · What it shows is that he is not guilty.", "category": "Parallel Reasoning", "chunks": [{"n": 1, "text": "If Max were guilty, he would not ask the police to investigate.", "details": [{"n": 1, "text": "This is a conditional statement."}, {"n": 2, "text": "It is about a person named Max."}, {"n": 3, "text": "The condition is Max being guilty."}, {"n": 4, "text": "The result concerns asking the police."}, {"n": 5, "text": "He would not ask them to investigate."}]}, {"n": 2, "text": "Therefore, his asking the police to investigate shows that he is not guilty.", "details": [{"n": 1, "text": "This is the conclusion."}, {"n": 2, "text": "It is drawn from what came before."}, {"n": 3, "text": "Max did ask the police to investigate."}, {"n": 4, "text": "That asking is treated as showing something."}, {"n": 5, "text": "What it shows is that he is not guilty."}]}], "the_read": "What if the rules of conditional reasoning don''t apply?", "the_read_type": "L", "questions": [{"citation": "PT1.S3.Q5", "qnum": 5, "question_type": "Parallel Reasoning", "correct_answer": "A"}]}, {"order": 6, "slug": "PT1_S3_Q6", "prompt": "A population of game ducks at a western lake contains 55 males to every 45 females, while a population of game ducks at an eastern lake contains 65 males for every 35 females. Among those ducks that have not yet bred there are only slightly more males than females, but among older ducks the number of males greatly exceeds the number of females. Because there are appreciably more males among adult ducks than among young ducks, we can infer that the greater the disparity in overall sex ratios, the greater the percentage of older male ducks in the population.", "credited_answers": [], "cumulative_after": [], "explanation": "The details your recall has to carry, by chunk: (1) This is about game ducks. · Two populations are being compared. · One population is at a western lake. · That one has 55 males to every 45 females. · The other population is at an eastern lake. · That one has 65 males for every 35 females. (2) This is about ducks that have not yet bred. · Among those there are more males than females. · The difference is only slight. · A contrast is drawn with older ducks. · Among older ducks males exceed females. · That excess is great rather than slight. (3) This gives a reason for what follows. · It compares adult ducks with young ducks. · Adult ducks have more males. · The difference is appreciable. (4) This is the conclusion. · It is stated as something we can infer. · It links two things that rise together. · The first is the disparity in overall sex ratios. · The second is the percentage of older male ducks. · The percentage is of the population.", "category": "Inference", "chunks": [{"n": 1, "text": "A population of game ducks at a western lake contains 55 males to every 45 females, while a population of game ducks at an eastern lake contains 65 males for every 35 females.", "details": [{"n": 1, "text": "This is about game ducks."}, {"n": 2, "text": "Two populations are being compared."}, {"n": 3, "text": "One population is at a western lake."}, {"n": 4, "text": "That one has 55 males to every 45 females."}, {"n": 5, "text": "The other population is at an eastern lake."}, {"n": 6, "text": "That one has 65 males for every 35 females."}]}, {"n": 2, "text": "Among those ducks that have not yet bred there are only slightly more males than females, but among older ducks the number of males greatly exceeds the number of females.", "details": [{"n": 1, "text": "This is about ducks that have not yet bred."}, {"n": 2, "text": "Among those there are more males than females."}, {"n": 3, "text": "The difference is only slight."}, {"n": 4, "text": "A contrast is drawn with older ducks."}, {"n": 5, "text": "Among older ducks males exceed females."}, {"n": 6, "text": "That excess is great rather than slight."}]}, {"n": 3, "text": "Because there are appreciably more males among adult ducks than among young ducks,", "details": [{"n": 1, "text": "This gives a reason for what follows."}, {"n": 2, "text": "It compares adult ducks with young ducks."}, {"n": 3, "text": "Adult ducks have more males."}, {"n": 4, "text": "The difference is appreciable."}]}, {"n": 4, "text": "we can infer that the greater the disparity in overall sex ratios, the greater the percentage of older male ducks in the population.", "details": [{"n": 1, "text": "This is the conclusion."}, {"n": 2, "text": "It is stated as something we can infer."}, {"n": 3, "text": "It links two things that rise together."}, {"n": 4, "text": "The first is the disparity in overall sex ratios."}, {"n": 5, "text": "The second is the percentage of older male ducks."}, {"n": 6, "text": "The percentage is of the population."}]}], "the_read": "What if this is not a representative sample?", "the_read_type": "L", "questions": [{"citation": "PT1.S3.Q6", "qnum": 6, "question_type": "Inference", "correct_answer": "A"}]}, {"order": 7, "slug": "PT1_S3_Q7", "prompt": "The common procedure for determining whether a food additive should be banned from use is to compare its health-related benefits with its potential risks. Yellow Dye No. 5, an additive used to color lemon soda, might cause allergic reactions in a few consumers. For most consumers of lemon soda, however, the coloring enhances their enjoyment of the beverage. This particular additive should not be banned, therefore, because its benefits greatly outweigh its risks.", "credited_answers": [], "cumulative_after": [], "explanation": "The details your recall has to carry, by chunk: (1) This is about a procedure. · The procedure is described as common. · It determines whether a food additive should be banned. · The procedure is a comparison. · One side is the additive''s health-related benefits. · The other side is its potential risks. (2) This is about a specific additive. · The additive is Yellow Dye No. 5. · It is used to color lemon soda. · It might cause allergic reactions. · This is stated as a possibility. · The reactions would affect a few consumers. (3) This is a contrast with what came before. · It is about most consumers of lemon soda. · The coloring enhances something for them. · What is enhanced is their enjoyment. · The enjoyment is of the beverage. (4) This is the conclusion. · It is about this particular additive. · It says the additive should not be banned. · A reason is given. · The reason is that benefits outweigh risks. · The outweighing is described as great.", "category": "Classic Flaw", "chunks": [{"n": 1, "text": "The common procedure for determining whether a food additive should be banned from use is to compare its health-related benefits with its potential risks.", "details": [{"n": 1, "text": "This is about a procedure."}, {"n": 2, "text": "The procedure is described as common."}, {"n": 3, "text": "It determines whether a food additive should be banned."}, {"n": 4, "text": "The procedure is a comparison."}, {"n": 5, "text": "One side is the additive''s health-related benefits."}, {"n": 6, "text": "The other side is its potential risks."}]}, {"n": 2, "text": "Yellow Dye No. 5, an additive used to color lemon soda, might cause allergic reactions in a few consumers.", "details": [{"n": 1, "text": "This is about a specific additive."}, {"n": 2, "text": "The additive is Yellow Dye No. 5."}, {"n": 3, "text": "It is used to color lemon soda."}, {"n": 4, "text": "It might cause allergic reactions."}, {"n": 5, "text": "This is stated as a possibility."}, {"n": 6, "text": "The reactions would affect a few consumers."}]}, {"n": 3, "text": "For most consumers of lemon soda, however, the coloring enhances their enjoyment of the beverage.", "details": [{"n": 1, "text": "This is a contrast with what came before."}, {"n": 2, "text": "It is about most consumers of lemon soda."}, {"n": 3, "text": "The coloring enhances something for them."}, {"n": 4, "text": "What is enhanced is their enjoyment."}, {"n": 5, "text": "The enjoyment is of the beverage."}]}, {"n": 4, "text": "This particular additive should not be banned, therefore, because its benefits greatly outweigh its risks.", "details": [{"n": 1, "text": "This is the conclusion."}, {"n": 2, "text": "It is about this particular additive."}, {"n": 3, "text": "It says the additive should not be banned."}, {"n": 4, "text": "A reason is given."}, {"n": 5, "text": "The reason is that benefits outweigh risks."}, {"n": 6, "text": "The outweighing is described as great."}]}], "the_read": "What if enjoyment is not a health-related benefit?", "the_read_type": "L", "questions": [{"citation": "PT1.S3.Q7", "qnum": 7, "question_type": "Classic Flaw", "correct_answer": "B"}]}, {"order": 8, "slug": "PT1_S3_Q8", "prompt": "Fines levied against those responsible for certain environmentally damaging accidents are now so high that it costs a company responsible for such an accident more to pay the fine than it would have cost to adopt measures that would have prevented the accident. Therefore, since businesses value their profits, those that might have such accidents will now install adequate environmental safeguards.", "credited_answers": [], "cumulative_after": [], "explanation": "The details your recall has to carry, by chunk: (1) This is about fines. · The fines are levied against those responsible for accidents. · The accidents are environmentally damaging ones. · This applies to certain accidents, not all. · The fines are now very high. · Paying the fine costs a company more. · The comparison is with the cost of preventive measures. · Those measures would have prevented the accident. (2) This is the conclusion. · A reason is given for it. · The reason is that businesses value their profits. · It is about businesses that might have such accidents. · They will install environmental safeguards. · The safeguards are described as adequate. · This is predicted to happen now.", "category": "Weaken", "chunks": [{"n": 1, "text": "Fines levied against those responsible for certain environmentally damaging accidents are now so high that it costs a company responsible for such an accident more to pay the fine than it would have cost to adopt measures that would have prevented the accident.", "details": [{"n": 1, "text": "This is about fines."}, {"n": 2, "text": "The fines are levied against those responsible for accidents."}, {"n": 3, "text": "The accidents are environmentally damaging ones."}, {"n": 4, "text": "This applies to certain accidents, not all."}, {"n": 5, "text": "The fines are now very high."}, {"n": 6, "text": "Paying the fine costs a company more."}, {"n": 7, "text": "The comparison is with the cost of preventive measures."}, {"n": 8, "text": "Those measures would have prevented the accident."}]}, {"n": 2, "text": "Therefore, since businesses value their profits, those that might have such accidents will now install adequate environmental safeguards.", "details": [{"n": 1, "text": "This is the conclusion."}, {"n": 2, "text": "A reason is given for it."}, {"n": 3, "text": "The reason is that businesses value their profits."}, {"n": 4, "text": "It is about businesses that might have such accidents."}, {"n": 5, "text": "They will install environmental safeguards."}, {"n": 6, "text": "The safeguards are described as adequate."}, {"n": 7, "text": "This is predicted to happen now."}]}], "the_read": "What if businesses think they''ll never have an accident so there''s no need to invest in safeguards?", "the_read_type": "L", "questions": [{"citation": "PT1.S3.Q8", "qnum": 8, "question_type": "Weaken", "correct_answer": "A"}]}, {"order": 9, "slug": "PT1_S3_Q9", "prompt": "Even in a democracy, it is necessary to restrict the dissemination of advanced technological knowledge that i